INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C1','math',4,2,'u2',2,'수직 — 두 직선이 만나서 이루는 각이 직각일 때 두 직선은 서로 수직이며, 놓인 방향이 아니라 만나서 이루는 각으로 정한다',ARRAY['4수03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C2','math',4,2,'u2',2,'수선과 수선 긋기 — 두 직선이 수직일 때 한 직선을 다른 직선에 대한 수선이라 하고, 삼각자의 직각 부분이나 각도기의 90°로 수선을 긋는다',ARRAY['4수03-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C3','math',4,2,'u2',3,'평행과 평행선 — 한 직선에 수직인 두 직선처럼 아무리 늘여도 만나지 않는 두 직선은 서로 평행하고, 평행한 두 직선을 평행선이라 하며, 공통의 수선으로 확인한다',ARRAY['4수03-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C4','math',4,2,'u2',4,'평행선 사이의 거리 — 평행선의 한 직선에서 다른 직선에 그은 수직인 선분의 길이로, 가장 짧고 어디에서 재어도 같다',ARRAY['4수03-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C5','math',4,2,'u2',5,'사다리꼴 — 평행한 변이 한 쌍이라도 있는 사각형으로, 평행한 변이 두 쌍인 사각형도 사다리꼴이다',ARRAY['4수03-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C6','math',4,2,'u2',6,'평행사변형 — 마주 보는 두 쌍의 변이 서로 평행한 사각형으로, 기울어져 있지 않아도(직사각형·정사각형도) 평행사변형이다',ARRAY['4수03-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C7','math',4,2,'u2',6,'평행사변형의 성질 — 마주 보는 두 변의 길이가 같고, 마주 보는 두 각의 크기가 같으며, 이웃한 두 각의 크기의 합이 180°이다',ARRAY['4수03-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C8','math',4,2,'u2',7,'마름모와 그 성질 — 네 변의 길이가 모두 같은 사각형으로, 마주 보는 두 쌍의 변이 평행하고 마주 보는 각이 같으며, 마주 보는 꼭짓점끼리 이은 두 선분은 수직으로 만나 서로를 반으로 나눈다',ARRAY['4수03-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C9','math',4,2,'u2',8,'여러 가지 사각형의 관계 — 직사각형·정사각형의 성질을 알고, 기준(평행한 변·변의 길이·각의 크기)에 따라 한 사각형이 여러 이름으로 불릴 수 있음을 알기',ARRAY['4수03-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u2-C10','math',4,2,'u2',9,'조건에 맞는 사각형 그리기 — 크기가 같은 두 원의 중심과 만나는 점을 이어 마름모를 그리고(네 변이 모두 반지름), 평행선·같은 길이를 이용해 여러 가지 사각형을 그리기',ARRAY['4수03-10']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X01','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3']::text[],'옆으로·위아래로 반듯하게 놓인 선만 수직·수선이라고 생각한다 — 기울어진 직선끼리 직각으로 만나면 수직이 아니라고 한다','놓인 방향 말고 만나서 이루는 각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X02','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3']::text[],'관계를 나타내는 말(수직·평행)과 직선을 가리키는 말(수선·평행선)을 섞어 쓴다','수직·평행은 관계, 수선·평행선은 직선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X03','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2']::text[],'직각에 가까운 각으로 만나도 수직이라고 눈대중한다 — 삼각자를 대어 확인하지 않는다','삼각자를 대어 직각인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X04','math',4,'u2',ARRAY['M4-2-u2-C2','M4-2-u2-C3']::text[],'한 직선에 대한 수선·평행선은 하나뿐이라고 생각하거나, 한 점을 지나는 수선·평행선이 여러 개라고 생각한다','한 직선에는 셀 수 없이 많이, 한 점을 지나면 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X05','math',4,'u2',ARRAY['M4-2-u2-C3']::text[],'그림 안에서 만나지 않으면 평행이라고 생각한다 — 늘이면 만나는 두 직선도 평행이라고 한다','끝없이 늘여 보기·공통의 수선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X06','math',4,'u2',ARRAY['M4-2-u2-C3','M4-2-u2-C5','M4-2-u2-C6']::text[],'기울어져 있거나 길이가 다르거나 멀리 떨어진 두 직선(변)은 평행하지 않다고 생각한다','방향·길이가 아니라 만나는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X07','math',4,'u2',ARRAY['M4-2-u2-C4']::text[],'평행선 사이의 거리를 비스듬한 선분이나 가장 긴 선분의 길이로 잰다','수직인 선분의 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X08','math',4,'u2',ARRAY['M4-2-u2-C4']::text[],'평행선 사이의 거리가 재는 자리마다 다르다고 생각한다','어디에서 재어도 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X09','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C9']::text[],'사다리꼴은 평행한 변이 「한 쌍만」 있어야 한다고 생각한다 — 평행사변형·직사각형은 사다리꼴이 아니라고 한다','한 쌍이라도 있으면 사다리꼴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X10','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C9']::text[],'사각형의 이름을 모양(위가 좁은 사다리 모양·비스듬히 기운 모양)으로 정한다 — 평행한 변을 확인하지 않는다','평행한 변이 몇 쌍인지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X11','math',4,'u2',ARRAY['M4-2-u2-C6','M4-2-u2-C9']::text[],'평행사변형은 비스듬히 기울어져 있어야 한다고 생각한다 — 직사각형·정사각형은 평행사변형이 아니라고 한다','마주 보는 두 쌍의 변이 평행하면 평행사변형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X12','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C8','M4-2-u2-C9']::text[],'마주 보는 각과 이웃한 각을 섞는다 — 이웃한 두 각이 같다고 하거나 이웃한 두 각의 합을 90°·360°로 계산한다','마주 보는 각은 같고, 이웃한 두 각의 합은 180°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X14','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C8']::text[],'평행사변형은 네 변의 길이가 모두 같다고 생각하거나, 마름모를 다이아몬드처럼 세워 놓인 모양으로만 안다','변의 길이를 재어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X15','math',4,'u2',ARRAY['M4-2-u2-C8']::text[],'마름모의 마주 보는 꼭짓점끼리 이은 두 선분이 길이가 같다고 하거나, 수직으로 만나지 않는다·반으로 나누지 않는다고 생각한다','두 선분은 수직으로 만나 서로를 반으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X16','math',4,'u2',ARRAY['M4-2-u2-C8','M4-2-u2-C9']::text[],'사각형 사이의 관계를 거꾸로 안다 — 마름모는 모두 정사각형, 사다리꼴은 모두 평행사변형, 직사각형은 모두 정사각형이라고 한다','정사각형 → 마름모(거꾸로는 아님)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X17','math',4,'u2',ARRAY['M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C8','M4-2-u2-C9']::text[],'한 사각형에는 이름이 하나뿐이라고 생각한다 — 정사각형은 마름모·직사각형이 아니라고 한다','기준마다 이름이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X18','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3','M4-2-u2-C4','M4-2-u2-C5','M4-2-u2-C6','M4-2-u2-C7','M4-2-u2-C8','M4-2-u2-C9','M4-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X19','math',4,'u2',ARRAY['M4-2-u2-C10']::text[],'두 원으로 그린 사각형의 변이 반지름임을 놓친다 — 크기가 다른 두 원으로도 마름모가 된다고 하거나 지름을 변의 길이로 잡는다','네 변이 모두 반지름인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X20','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C9']::text[],'선분(변)끼리 직각으로 만나는 것은 수직이라고 하지 않는다고 생각한다 — 「직사각형에는 서로 수직인 변이 없다」고 한다(익힘 21 퐁당·교과서 32)','선분과 선분이 직각으로 만나도 서로 수직') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X21','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2']::text[],'한 직선에 수직인 직선을 「수직선」이라고 부른다 — 눈금과 수를 적은 수직선과 섞는다(지도서 213 질문 1)','수직인 직선은 줄여서 수선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X22','math',4,'u2',ARRAY['M4-2-u2-C4']::text[],'평행선 사이의 거리를 잴 때 선분을 평행선에 닿게 긋지 않는다 — 선분이 평행선을 지나치거나 평행선에 미치지 못한 채 잰다(지도서 204·225)','선분의 두 끝이 두 평행선에 꼭 닿게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X23','math',4,'u2',ARRAY['M4-2-u2-C1','M4-2-u2-C2','M4-2-u2-C3']::text[],'수직과 평행(수선과 평행선)을 서로 바꿔 생각한다 — 평행한 직선을 그으라는데 수선을 긋거나, 수직인 두 직선을 평행하다고 한다(지도서 203·222)','수직은 직각으로 만나요, 평행은 만나지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X24','math',4,'u2',ARRAY['M4-2-u2-C3']::text[],'평행선을 그을 때 주어진 직선에 삼각자의 한 변을 맞추지 않거나, 한 삼각자를 고정하지 않고 둘 다 움직인다(지도서 203·222)','한 삼각자는 꼭 잡고, 다른 삼각자만 밀어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X25','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C8']::text[],'삼각자·각도기를 비뚤게 대고 잰 결과로 사각형의 성질을 잘못 추측한다 — 「마름모는 평행한 변이 없다」「마주 보는 두 각의 크기가 다르다」(지도서 238)','도구를 바르게 대고 다시 재어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X26','math',4,'u2',ARRAY['M4-2-u2-C7','M4-2-u2-C9']::text[],'변에 대해 「마주 보는」과 「이웃한」을 섞는다 — 「직사각형은 이웃한 두 변의 길이가 같다」「정사각형은 마주 보는 두 변이 수직이다」(지도서 242)','마주 보는 변과 이웃한 변을 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X27','math',4,'u2',ARRAY['M4-2-u2-C6','M4-2-u2-C9']::text[],'마주 보는 두 쌍의 변이 평행하기만 하면 직사각형이라고 한다 — 네 각이 모두 직각인지 확인하지 않는다(지도서 241)','직사각형은 네 각이 모두 직각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u2-X28','math',4,'u2',ARRAY['M4-2-u2-C10']::text[],'그린 사각형이 마름모인 까닭을 「네 변의 길이가 같아 보여서」라고 댄다 — 네 변이 모두 원의 반지름이라 같다는 근거를 대지 않는다(지도서 246 평가)','보이는 모양 말고 반지름이라는 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#1','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C9',1,'mc','auto','「준비하기」 — 네 각이 모두 직각인 사각형을 무엇이라고 하나요?',ARRAY['M4-2-u2-X14','M4-2-u2-X11','M4-2-u2-X10']::text[],true,'{"seq":1,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「준비하기」 — 네 각이 모두 직각인 사각형을 무엇이라고 하나요?","options":[{"t":"직사각형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"평행사변형","mis":"M4-2-u2-X11"},{"t":"사다리꼴","mis":"M4-2-u2-X10"}],"explanation":["3학년 1학기 「평면도형」에서 배운 사각형이에요.","네 각이 모두 직각인 사각형을 직사각형이라고 해요.","삼각자의 직각 부분을 네 각에 대어 확인해요."],"variant_rule":{"alt":[{"stem":"「준비하기」 — 네 각이 모두 직각이고 네 변의 길이가 모두 같은 사각형을 무엇이라고 하나요?","options":[{"t":"정사각형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"사다리꼴","mis":"M4-2-u2-X10"},{"t":"평행사변형","mis":"M4-2-u2-X11"}],"explanation":["네 각이 모두 직각이에요.","게다가 네 변의 길이가 모두 같아요.","이런 사각형을 정사각형이라고 해요 — 비스듬히 세워 놓아도 정사각형이에요."]},{"stem":"「스스로 준비 학습」 — 양쪽으로 끝이 없는 곧은 선을 무엇이라고 하나요?","options":[{"t":"직선","correct":true},{"t":"선분","mis":"M4-2-u2-X02"},{"t":"반직선","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X02"}],"explanation":["3학년 1학기 「평면도형」에서 배운 선이에요.","두 점을 곧게 이은 선은 선분, 한쪽으로 끝없이 늘인 선은 반직선이에요.","양쪽으로 끝없이 늘인 곧은 선이 직선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#2','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','「준비하기」 — 그림처럼 네 각이 90°, 120°, 70°, 80°인 사각형이 있어요. 사각형의 네 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"「준비하기」 — 그림처럼 네 각이 90°, 120°, 70°, 80°인 사각형이 있어요. 사각형의 네 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["4학년 1학기 「각도」에서 배운 내용이에요.","90 + 120 + 70 + 80 = 360이에요.","사각형의 네 각의 크기의 합은 360°예요."],"asset":{"type":"geo","items":[{"w":124.6,"h":96.0,"poly":[[[18.0,18.0],[81.0,18.0],[106.6,62.4],[18.0,78.0]]],"right":[[[18.0,78.0],[18.0,18.0],[81.0,18.0]]],"lab":[[[28.6,28.6],"90°"],[[73.5,31.0],"120°"],[[91.9,55.5],"70°"],[[27.6,66.5],"80°"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「스스로 준비 학습」 — 사각형의 두 각이 직각이고 한 각이 110°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","90 + 90 + 110 = 290이에요.","360 − 290 = 70 — 70°예요."],"asset":{"type":"geo","items":[{"w":111.0,"h":108.3,"poly":[[[18.0,18.0],[93.0,18.0],[93.0,90.3],[18.0,63.0]]],"right":[[[18.0,63.0],[18.0,18.0],[93.0,18.0]],[[18.0,18.0],[93.0,18.0],[93.0,90.3]]],"lab":[[[30.3,54.4],"110°"],[[83.7,77.0],"?"]]}],"tag":false}},{"stem":"「스스로 준비 학습」 — 사각형의 한 각이 직각이고, 두 각이 100°와 70°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","90 + 100 + 70 = 260이에요.","360 − 260 = 100 — 100°예요."],"asset":{"type":"geo","items":[{"w":126.0,"h":93.2,"poly":[[[18.0,30.2],[87.2,18.0],[108.0,75.2],[18.0,75.2]]],"right":[[[108.0,75.2],[18.0,75.2],[18.0,30.2]]],"lab":[[[79.7,31.0],"100°"],[[94.7,65.9],"70°"],[[29.5,39.8],"?"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#3','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',1,'mc','auto','「개념 쏙」 — 두 직선이 만나서 이루는 각이 직각일 때 두 직선은 서로 무엇이라고 하나요?',ARRAY['M4-2-u2-X02','M4-2-u2-X23','M4-2-u2-X21']::text[],true,'{"seq":3,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 두 직선이 만나서 이루는 각이 직각일 때 두 직선은 서로 무엇이라고 하나요?","options":[{"t":"수직","correct":true},{"t":"수선","mis":"M4-2-u2-X02"},{"t":"평행","mis":"M4-2-u2-X23"},{"t":"수직선","mis":"M4-2-u2-X21"}],"explanation":["주차선처럼 두 직선이 직각으로 만나는 경우를 생각해요.","두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요.","수직은 두 직선의 관계를 나타내는 말이에요."],"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 두 직선이 서로 수직으로 만날 때, 한 직선을 다른 직선에 대한 무엇이라고 하나요?","options":[{"t":"수선","correct":true},{"t":"수직","mis":"M4-2-u2-X02"},{"t":"수직선","mis":"M4-2-u2-X21"},{"t":"평행선","mis":"M4-2-u2-X23"}],"explanation":["수직은 두 직선의 관계예요.","수직으로 만날 때 한 직선을 다른 직선에 대한 수선이라고 해요.","수직인 직선을 줄여서 수선이라고 불러요 — 수직선이라고 하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#4','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',1,'mc','auto','「단원 도입」 — 주차장 바닥에 그어진 선과 선이 만나 직각을 이루고 있어요. 두 선이 만나서 이루는 각이 직각인지 확인하려면 삼각자의 어느 부분을 대어 보나요?',ARRAY['M4-2-u2-X03']::text[],true,'{"seq":4,"concept":"M4-2-u2-C1","difficulty":1,"kind":"mc","stem":"「단원 도입」 — 주차장 바닥에 그어진 선과 선이 만나 직각을 이루고 있어요. 두 선이 만나서 이루는 각이 직각인지 확인하려면 삼각자의 어느 부분을 대어 보나요?","options":[{"t":"직각 부분","correct":true},{"t":"가장 긴 변","mis":"M4-2-u2-X03"},{"t":"가장 뾰족한 각 부분","mis":"M4-2-u2-X03"},{"t":"대어 보지 않고 눈으로 봐요","mis":"M4-2-u2-X03"}],"explanation":["직각인지는 눈대중이 아니라 도구로 확인해요.","삼각자에서 직각 부분을 찾아 두 선이 만나는 곳에 대어 봐요.","꼭 맞으면 두 선이 만나서 이루는 각은 직각이에요."],"variant_rule":{"alt":[{"stem":"「단원 도입」 — 주차장에서 직사각형도 정사각형도 아닌 사각형 모양을 찾았어요. 이 사각형의 이름을 알아보려면 무엇을 살펴보아야 하나요?","options":[{"t":"변끼리 평행한지, 변의 길이와 각의 크기가 어떤지","correct":true},{"t":"사각형이 놓인 방향","mis":"M4-2-u2-X10"},{"t":"사각형의 크기","mis":"M4-2-u2-X10"},{"t":"사각형의 색깔","mis":"M4-2-u2-X10"}],"explanation":["사각형의 이름은 변과 각으로 정해요.","평행한 변이 있는지, 변의 길이·각의 크기가 같은지 살펴봐요.","이 단원에서 사다리꼴·평행사변형·마름모를 배워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#5','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',2,'mc','auto','「생각 톡」 — 두 직선이 만나는 그림이에요. 두 직선이 만나서 이루는 각이 직각인 것을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X01','M4-2-u2-X03','M4-2-u2-X18']::text[],true,'{"seq":5,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"「생각 톡」 — 두 직선이 만나는 그림이에요. 두 직선이 만나서 이루는 각이 직각인 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮","mis":"M4-2-u2-X01"},{"t":"㉮, ㉯, ㉰","mis":"M4-2-u2-X03"},{"t":"㉰","mis":"M4-2-u2-X18"}],"explanation":["삼각자의 직각 부분을 두 직선이 만나는 곳에 대어 봐요.","㉮와 ㉯는 직각으로 만나요 — ㉯는 비스듬히 놓였을 뿐이에요.","㉰는 직각에 가깝지 않게 비스듬히 만나요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"seg":[[[7.5,45.0],[82.5,45.0]],[[45.0,7.5],[45.0,82.5]]]},{"w":105,"h":90,"seg":[[[15.0,30.0],[75.0,60.0]],[[30.0,75.0],[60.0,15.0]]]},{"w":105,"h":90,"seg":[[[15.0,12.0],[75.0,78.0]],[[7.5,57.0],[82.5,33.0]]]}]},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 삼각자를 사용하여 주어진 두 직선이 서로 수직인 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯, ㉰","correct":true},{"t":"㉰","mis":"M4-2-u2-X01"},{"t":"㉯, ㉰, ㉱","mis":"M4-2-u2-X03"},{"t":"㉮, ㉱","mis":"M4-2-u2-X18"}],"explanation":["두 직선이 만나서 이루는 각이 직각이면 서로 수직이에요.","㉯(비스듬한 ×)와 ㉰(+)가 직각으로 만나요.","㉮·㉱는 직각이 아니에요 — 놓인 방향이 아니라 각으로 봐요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"seg":[[[7.5,52.5],[82.5,52.5]],[[22.5,82.5],[67.5,22.5]]]},{"w":105,"h":90,"seg":[[[15.0,15.0],[75.0,75.0]],[[15.0,75.0],[75.0,15.0]]]},{"w":105,"h":90,"seg":[[[7.5,45.0],[82.5,45.0]],[[45.0,7.5],[45.0,82.5]]]},{"w":105,"h":90,"seg":[[[7.5,30.0],[82.5,67.5]],[[7.5,67.5],[82.5,30.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#6','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C2',2,'mc','auto','「개념 톡」 — 삼각자를 사용하여 주어진 직선에 대한 수선을 그어요. ① 주어진 직선에 삼각자의 직각을 낀 한 변을 맞춰요. ② 다음에 할 일은 무엇인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X23']::text[],true,'{"seq":6,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 삼각자를 사용하여 주어진 직선에 대한 수선을 그어요. ① 주어진 직선에 삼각자의 직각을 낀 한 변을 맞춰요. ② 다음에 할 일은 무엇인가요?","options":[{"t":"삼각자의 직각을 낀 다른 변을 따라 선을 그어요","correct":true},{"t":"삼각자의 가장 긴 변을 따라 선을 그어요","mis":"M4-2-u2-X03"},{"t":"주어진 직선과 만나지 않게 나란히 선을 그어요","mis":"M4-2-u2-X23"},{"t":"삼각자를 떼고 눈대중으로 선을 그어요","mis":"M4-2-u2-X03"}],"explanation":["수선은 주어진 직선과 직각으로 만나는 직선이에요.","삼각자의 직각을 낀 한 변을 직선에 맞추면 다른 변은 직선과 직각을 이뤄요.","그 다른 변을 따라 그으면 수선이 돼요."],"variant_rule":{"alt":[{"stem":"「개념 톡」 — 각도기와 자를 사용하여 수선을 그어요. 주어진 직선에 점을 찍고, 각도기의 중심을 점에, 밑금을 직선에 맞췄어요. 각도기에서 몇 도가 되는 곳에 점을 표시하나요?","options":[{"t":"90°","correct":true},{"t":"180°","mis":"M4-2-u2-X03"},{"t":"45°","mis":"M4-2-u2-X03"},{"t":"60°","mis":"M4-2-u2-X03"}],"explanation":["수선은 주어진 직선과 만나서 이루는 각이 직각이에요.","직각은 90°예요.","90°가 되는 곳에 점을 표시하고 두 점을 직선으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#7','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',2,'mc','auto','「문제 척」 — 직선 가에 대한 수선이 아닌 직선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X18','M4-2-u2-X03','M4-2-u2-X01']::text[],true,'{"seq":7,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"「문제 척」 — 직선 가에 대한 수선이 아닌 직선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 다, 직선 마","correct":true},{"t":"직선 나, 직선 라","mis":"M4-2-u2-X18"},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 다, 직선 라, 직선 마","mis":"M4-2-u2-X01"}],"explanation":["직선 가와 만나서 이루는 각이 직각인지 삼각자로 확인해요.","직선 나·라는 직선 가와 직각으로 만나요.","직선 다·마는 직각으로 만나지 않아 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,82.5],[150.0,82.5]],[[30.0,0.0],[30.0,105.0]],[[52.5,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]],[[142.5,0.0],[120.0,105.0]]],"lab":[[[13.5,93.8],"가"],[[18.8,13.5],"나"],[[67.0,9.9],"다"],[[116.2,13.5],"라"],[[133.8,94.2],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 직선 가에 대한 수선이 아닌 직선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 나, 직선 라","correct":true},{"t":"직선 다, 직선 마","mis":"M4-2-u2-X18"},{"t":"직선 나","mis":"M4-2-u2-X03"},{"t":"직선 나, 직선 다, 직선 라","mis":"M4-2-u2-X01"}],"explanation":["직선 가와 직각으로 만나는지 확인해요.","직선 다·마는 직선 가와 직각으로 만나요.","직선 나·라는 비스듬히 만나 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,90.0],[150.0,90.0]],[[7.5,90.0],[37.5,0.0]],[[60.0,0.0],[60.0,105.0]],[[82.5,0.0],[105.0,105.0]],[[127.5,0.0],[127.5,105.0]]],"lab":[[[36.0,78.8],"가"],[[22.6,9.2],"나"],[[71.2,36.0],"다"],[[96.3,10.8],"라"],[[138.8,13.5],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#8','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',2,'mc','auto','「수학익힘」 — 그림을 보고 답하세요. 직선 가와 서로 수직인 직선은 어느 것인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X03','M4-2-u2-X01']::text[],true,'{"seq":8,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 그림을 보고 답하세요. 직선 가와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 라","correct":true},{"t":"직선 나","mis":"M4-2-u2-X23"},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["직선 가와 직각으로 만나는 직선을 찾아요.","직선 라가 직선 가와 직각으로 만나요.","직선 나는 직선 가와 만나지 않고, 직선 다는 비스듬히 만나요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[45.0,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[60.1,8.9],"다"],[[116.2,13.5],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 그림을 보고 답하세요. 직선 라에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 가, 직선 나","correct":true},{"t":"직선 가","mis":"M4-2-u2-X04"},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 가, 직선 나, 직선 다","mis":"M4-2-u2-X03"}],"explanation":["직선 라와 직각으로 만나는 직선을 모두 찾아요.","직선 가와 직선 나가 모두 직선 라와 직각으로 만나요.","한 직선에 대한 수선은 여러 개일 수 있어요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[45.0,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[60.1,8.9],"다"],[[116.2,13.5],"라"]]}],"tag":false}},{"stem":"「확인 문제」 — 직선 가와 서로 수직인 직선은 어느 것인가요?","options":[{"t":"직선 나","correct":true},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 나, 직선 다","mis":"M4-2-u2-X03"},{"t":"수직인 직선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["직선 가와 직각으로 만나는 직선을 찾아요.","직선 나가 직선 가와 직각으로 만나요 — 직선 나는 직선 가에 대한 수선이에요.","직선 다는 비스듬히 만나 수직이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,60.0],[150.0,60.0]],[[90.0,0.0],[90.0,105.0]],[[0.0,15.0],[150.0,90.0]]],"lab":[[[13.5,71.2],"가"],[[78.8,13.5],"나"],[[7.0,31.1],"다"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#9','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C2',2,'error','auto','「수학에 퐁당」 — 수직과 수선에 대해 잘못 설명한 사람은 누구인가요?',ARRAY['M4-2-u2-X20','M4-2-u2-X18']::text[],false,'{"seq":9,"concept":"M4-2-u2-C2","difficulty":2,"kind":"error","stem":"「수학에 퐁당」 — 수직과 수선에 대해 잘못 설명한 사람은 누구인가요?","options":[{"t":"민준 — 「직사각형에는 서로 수직인 변이 없어.」","correct":true,"mis_target":"M4-2-u2-X20"},{"t":"지아 — 「한 직선에 대한 수선은 셀 수 없이 많아.」","mis":"M4-2-u2-X18"},{"t":"정후 — 「선분과 선분이 만나서 이루는 각이 직각일 때도 서로 수직이라고 해.」","mis":"M4-2-u2-X18"}],"explanation":["직사각형의 네 각은 모두 직각이에요.","그래서 직사각형은 서로 이웃한 두 변이 모두 수직이에요.","민준이의 말이 잘못이에요 — 선분끼리 직각으로 만나도 서로 수직이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_basic#10','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_basic','lesson_basic','M4-2-u2-C1',3,'mc','auto','「수학익힘」 — 삼각자를 사용하여 서로 수직인 변이 있는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X20','M4-2-u2-X03','M4-2-u2-X18']::text[],false,'{"seq":10,"concept":"M4-2-u2-C1","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 삼각자를 사용하여 서로 수직인 변이 있는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉰, ㉱","correct":true},{"t":"㉰","mis":"M4-2-u2-X20"},{"t":"㉯, ㉰, ㉱","mis":"M4-2-u2-X03"},{"t":"㉮, ㉯","mis":"M4-2-u2-X18"}],"explanation":["도형에서 두 변이 만나서 이루는 각에 삼각자의 직각 부분을 대어 봐요.","㉰와 ㉱에 직각으로 만나는 두 변이 있어요 — 변(선분)끼리도 수직이에요.","㉮·㉯에는 직각이 없어요 — 비스듬한 각을 직각으로 보지 않아요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]]]},{"w":105,"h":90,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]]]},{"w":105,"h":90,"poly":[[[15.0,75.0],[90.0,75.0],[15.0,22.5]]]},{"w":105,"h":90,"poly":[[[15.0,30.0],[75.0,22.5],[90.0,75.0],[15.0,75.0]]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#1','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',2,'mc','auto','「수학에 퐁당」 — 지아는 「한 직선에 대한 수선은 셀 수 없이 많아.」라고 말했어요. 한 직선에 대한 수선은 몇 개 그을 수 있나요?',ARRAY['M4-2-u2-X04']::text[],true,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"「수학에 퐁당」 — 지아는 「한 직선에 대한 수선은 셀 수 없이 많아.」라고 말했어요. 한 직선에 대한 수선은 몇 개 그을 수 있나요?","options":[{"t":"셀 수 없이 많이 그을 수 있어요","correct":true},{"t":"1개만 그을 수 있어요","mis":"M4-2-u2-X04"},{"t":"2개만 그을 수 있어요","mis":"M4-2-u2-X04"},{"t":"직선의 양쪽 끝에 하나씩, 2개예요","mis":"M4-2-u2-X04"}],"explanation":["수선은 주어진 직선과 직각으로 만나는 직선이에요.","주어진 직선 위의 어느 곳에서나 직각이 되게 그을 수 있어요.","그래서 한 직선에 대한 수선은 셀 수 없이 많아요."],"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 직선 다에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 가, 직선 나","correct":true},{"t":"직선 가","mis":"M4-2-u2-X04"},{"t":"직선 나","mis":"M4-2-u2-X04"},{"t":"수선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["직선 다와 직각으로 만나는 직선을 모두 찾아요.","직선 가와 직선 나가 모두 직선 다와 수직으로 만나요.","하나만 찾지 않도록 해요 — 수선은 여러 개일 수 있어요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[75.0,0.0],[75.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[63.8,13.5],"다"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#2','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',2,'ox','auto','「궁금해요」 — 한 직선에 수직인 직선을 줄여서 「수직선」이라고 불러요.',ARRAY['M4-2-u2-X21']::text[],false,'{"seq":2,"concept":"M4-2-u2-C2","difficulty":2,"kind":"ox","stem":"「궁금해요」 — 한 직선에 수직인 직선을 줄여서 「수직선」이라고 불러요.","answer":"X","reason_options":[{"t":"수직선은 눈금과 수를 적은 선을 가리키는 말이라 수직인 직선은 줄여서 수선이라고 해서","correct":true},{"t":"수직인 직선이니 줄여서 수직선이라고 해서","mis":"M4-2-u2-X21"}],"mis":"M4-2-u2-X21","explanation":["수학에서는 한 낱말이 한 가지만 가리키도록 약속해요.","수직선은 덧셈·뺄셈에서 쓴 눈금 있는 선이에요.","수직인 직선은 줄여서 수선이라고 해요 — 이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#3','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',3,'sa','auto','「문제 척」 — 그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C1","difficulty":3,"kind":"sa","stem":"「문제 척」 — 그림에서 직선 가에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["직선 가와 만나서 이루는 각이 직각인 직선을 세어요.","직선 나와 직선 라가 직선 가와 직각으로 만나요.","직선 다·마는 수선이 아니에요 — 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,82.5],[150.0,82.5]],[[30.0,0.0],[30.0,105.0]],[[52.5,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]],[[142.5,0.0],[120.0,105.0]]],"lab":[[[13.5,93.8],"가"],[[18.8,13.5],"나"],[[67.0,9.9],"다"],[[116.2,13.5],"라"],[[133.8,94.2],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 그림에서 직선 라에 대한 수선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["직선 라와 직각으로 만나는 직선을 세어요.","직선 가와 직선 나가 직선 라와 직각으로 만나요.","직선 다는 비스듬히 만나요 — 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[45.0,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[60.1,8.9],"다"],[[116.2,13.5],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#4','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',3,'ox','auto','「문제 척」 — 직선 다가 직선 가에 대한 수선이 아닌 까닭은 직선 다가 기울어져 있기 때문이에요.',ARRAY['M4-2-u2-X01']::text[],false,'{"seq":4,"concept":"M4-2-u2-C1","difficulty":3,"kind":"ox","stem":"「문제 척」 — 직선 다가 직선 가에 대한 수선이 아닌 까닭은 직선 다가 기울어져 있기 때문이에요.","answer":"X","reason_options":[{"t":"기울어진 것과 상관없이 직선 가와 만나서 이루는 각이 직각이 아니기 때문이라서","correct":true},{"t":"기울어진 직선은 수선이 될 수 없어서","mis":"M4-2-u2-X01"}],"mis":"M4-2-u2-X01","explanation":["수선인지는 놓인 방향이 아니라 만나서 이루는 각으로 정해요.","직선 다는 직선 가와 만나서 이루는 각이 직각이 아니라서 수선이 아니에요.","기울어진 직선도 직각으로 만나면 수선이 돼요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,82.5],[150.0,82.5]],[[30.0,0.0],[30.0,105.0]],[[52.5,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]],[[142.5,0.0],[120.0,105.0]]],"lab":[[[13.5,93.8],"가"],[[18.8,13.5],"나"],[[67.0,9.9],"다"],[[116.2,13.5],"라"],[[133.8,94.2],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#5','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',3,'error','auto','「수학익힘」 — 도형에 대해 잘못 설명한 것은 어느 것인가요?',ARRAY['M4-2-u2-X01','M4-2-u2-X18']::text[],false,'{"seq":5,"concept":"M4-2-u2-C2","difficulty":3,"kind":"error","stem":"「수학익힘」 — 도형에 대해 잘못 설명한 것은 어느 것인가요?","options":[{"t":"가 — 「선분 ㄱㄷ과 서로 수직인 선분은 1개입니다.」","correct":true,"mis_target":"M4-2-u2-X01"},{"t":"나 — 「선분 ㄱㅁ과 선분 ㄴㄷ은 서로 수직입니다.」","mis":"M4-2-u2-X18"},{"t":"다 — 「선분 ㄱㄴ과 선분 ㄴㄷ은 서로 수직이 아닙니다.」","mis":"M4-2-u2-X18"}],"explanation":["선분 ㄱㄷ과 직각으로 만나는 선분을 모두 찾아요.","선분 ㄱㄴ과 선분 ㅁㄹ이 선분 ㄱㄷ과 직각으로 만나요 — 비스듬히 놓인 선분 ㄱㄴ도 수직이에요.","그래서 가가 잘못이에요 — 바르게 고치면 「2개입니다.」예요."],"asset":{"type":"geo","items":[{"w":195,"h":96.0,"pts":{"ㄱ":[42.0,15.0,"n"],"ㄴ":[4.5,90.0,"w"],"ㄷ":[192.0,90.0,"e"],"ㅁ":[42.0,90.0,"s"],"ㄹ":[72.0,30.0,"ne"],"ㅂ":[117.0,52.5,"ne"]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄱ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㄹ"],["ㅁ","ㅂ"]],"right":[["ㄴ","ㄱ","ㄷ"],["ㄴ","ㅁ","ㄱ"],["ㅁ","ㄹ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#6','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',3,'sa','auto','「서술형」 — 그림에서 선분 ㄱㄷ과 서로 수직인 선분은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u2-C2","difficulty":3,"kind":"sa","stem":"「서술형」 — 그림에서 선분 ㄱㄷ과 서로 수직인 선분은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분 ㄱㄷ과 만나서 이루는 각에 삼각자를 대어 봐요.","선분 ㄱㄴ(각 ㄱ이 직각)과 선분 ㅁㄹ(각 ㄹ이 직각)이에요.","선분 ㅁㅂ은 비스듬히 만나요 — 2개예요."],"asset":{"type":"geo","items":[{"w":195,"h":96.0,"pts":{"ㄱ":[42.0,15.0,"n"],"ㄴ":[4.5,90.0,"w"],"ㄷ":[192.0,90.0,"e"],"ㅁ":[42.0,90.0,"s"],"ㄹ":[72.0,30.0,"ne"],"ㅂ":[117.0,52.5,"ne"]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄱ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㄹ"],["ㅁ","ㅂ"]],"right":[["ㄴ","ㄱ","ㄷ"],["ㄴ","ㅁ","ㄱ"],["ㅁ","ㄹ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#7','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',3,'mc','auto','「확인 문제」 — 삼각자를 사용하여 주어진 직선에 대한 수선을 바르게 그은 것은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X23']::text[],false,'{"seq":7,"concept":"M4-2-u2-C2","difficulty":3,"kind":"mc","stem":"「확인 문제」 — 삼각자를 사용하여 주어진 직선에 대한 수선을 바르게 그은 것은 어느 것인가요?","options":[{"t":"삼각자의 직각을 낀 한 변을 직선에 맞추고, 직각을 낀 다른 변을 따라 그은 선","correct":true},{"t":"삼각자의 가장 긴 변을 직선에 맞추고, 다른 변을 따라 그은 선","mis":"M4-2-u2-X03"},{"t":"삼각자를 직선에서 떨어뜨려 놓고 직선과 나란히 그은 선","mis":"M4-2-u2-X23"},{"t":"직선 위에 점을 찍고 각도기의 45°에 맞추어 이은 선","mis":"M4-2-u2-X03"}],"explanation":["수선은 주어진 직선과 직각으로 만나야 해요.","삼각자의 직각 부분을 쓰면 직각이 돼요.","가장 긴 변이나 45°로 그으면 직각이 아니고, 나란히 그은 선은 평행선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#8','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C9',4,'sa','auto','「수학익힘」 — 직사각형의 네 각은 모두 직각이에요. 직사각형에서 서로 수직으로 만나는 두 변은 모두 몇 쌍인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"「수학익힘」 — 직사각형의 네 각은 모두 직각이에요. 직사각형에서 서로 수직으로 만나는 두 변은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직사각형은 네 꼭짓점마다 두 변이 직각으로 만나요.","서로 이웃한 두 변이 모두 수직이에요.","꼭짓점이 4개이니 4쌍이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#9','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C1',4,'essay','teacher','「문제 척」 — 직선 다, 직선 마는 직선 가에 대한 수선이 아니에요. 그 이유를 「직각」이라는 말을 넣어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C1","difficulty":4,"kind":"essay","stem":"「문제 척」 — 직선 다, 직선 마는 직선 가에 대한 수선이 아니에요. 그 이유를 「직각」이라는 말을 넣어 써 보세요.","answer_guide":{"answer":"예: 직선 가와 직선 다, 직선 가와 직선 마가 만나서 이루는 각이 직각이 아니므로 직선 다, 직선 마는 직선 가에 대한 수선이 아닙니다.","scoring_points":["직선 가와 만나서 이루는 각을 기준으로 썼는가","그 각이 직각이 아니라고 썼는가","기울기나 놓인 방향을 이유로 들지 않았는가"]},"explanation":["수선은 두 직선이 만나서 이루는 각이 직각일 때의 한 직선이에요.","직선 다·마는 직선 가와 직각으로 만나지 않아요.","그래서 수선이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,82.5],[150.0,82.5]],[[30.0,0.0],[30.0,105.0]],[[52.5,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]],[[142.5,0.0],[120.0,105.0]]],"lab":[[[13.5,93.8],"가"],[[18.8,13.5],"나"],[[67.0,9.9],"다"],[[116.2,13.5],"라"],[[133.8,94.2],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L02_challenge#10','math',4,2,'u2','L02','tb_g4_2_math_u2_L02_challenge','lesson_challenge','M4-2-u2-C2',4,'essay','teacher','「개념 톡」 — 삼각자 사용하기와 각도기와 자 사용하기 가운데 한 방법을 골라, 주어진 직선에 대한 수선을 긋는 순서를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C2","difficulty":4,"kind":"essay","stem":"「개념 톡」 — 삼각자 사용하기와 각도기와 자 사용하기 가운데 한 방법을 골라, 주어진 직선에 대한 수선을 긋는 순서를 써 보세요.","answer_guide":{"answer":"예(삼각자): 주어진 직선에 삼각자의 직각을 낀 한 변을 맞추고, 삼각자의 다른 변을 따라 선을 긋습니다. / 예(각도기와 자): 주어진 직선에 점을 표시하고, 각도기의 중심을 점에, 밑금을 직선에 맞춘 다음 90°가 되는 곳에 점을 표시하고 두 점을 직선으로 잇습니다.","scoring_points":["고른 도구를 밝혔는가","직각(90°)을 만드는 단계를 썼는가","순서대로 썼는가"]},"explanation":["수선은 주어진 직선과 직각으로 만나야 해요.","삼각자는 직각 부분으로, 각도기는 90°로 직각을 만들어요.","다른 방법을 고른 친구와 비교해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#1','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'mc','auto','「개념 쏙」 — 한 직선에 수직인 두 직선을 그었을 때 만나지 않는 두 직선을 서로 어떻다고 하나요?',ARRAY['M4-2-u2-X23','M4-2-u2-X02']::text[],true,'{"seq":1,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 한 직선에 수직인 두 직선을 그었을 때 만나지 않는 두 직선을 서로 어떻다고 하나요?","options":[{"t":"평행하다","correct":true},{"t":"수직이다","mis":"M4-2-u2-X23"},{"t":"수선이다","mis":"M4-2-u2-X02"},{"t":"평행선이다","mis":"M4-2-u2-X02"}],"explanation":["한 직선에 수직인 두 직선은 끝없이 늘여도 만나지 않아요.","만나지 않는 두 직선을 서로 평행하다고 해요.","평행은 관계, 평행선은 평행한 두 직선을 가리켜요."],"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 평행한 두 직선을 무엇이라고 하나요?","options":[{"t":"평행선","correct":true},{"t":"평행","mis":"M4-2-u2-X02"},{"t":"수선","mis":"M4-2-u2-X23"},{"t":"수직선","mis":"M4-2-u2-X21"}],"explanation":["서로 만나지 않는 두 직선은 평행해요.","이때 평행한 두 직선을 평행선이라고 해요.","수선은 수직으로 만나는 직선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#2','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'mc','auto','「생각 톡」 — 자전거 도로와 인도의 선이에요. 직선 가, 나, 다 가운데 서로 만나지 않는 두 직선은 어느 것인가요?',ARRAY['M4-2-u2-X05']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 자전거 도로와 인도의 선이에요. 직선 가, 나, 다 가운데 서로 만나지 않는 두 직선은 어느 것인가요?","options":[{"t":"직선 가와 직선 나","correct":true},{"t":"직선 가와 직선 다","mis":"M4-2-u2-X05"},{"t":"직선 나와 직선 다","mis":"M4-2-u2-X05"},{"t":"세 직선 모두","mis":"M4-2-u2-X05"}],"explanation":["직선은 양쪽으로 끝이 없어요 — 끝없이 늘였을 때를 생각해요.","직선 가와 직선 나는 모눈의 간격이 일정해서 늘여도 만나지 않아요.","직선 다는 그림 안에서는 안 만나도 늘이면 다른 직선과 만나요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,52.5],[150.0,52.5]],[[0.0,97.5],[150.0,75.0]],[[45.0,0.0],[45.0,105.0]]],"lab":[[[13.5,33.8],"가"],[[136.5,41.2],"나"],[[11.7,84.4],"다"],[[56.2,69.0],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#3','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'mc','auto','「생각 톡」 — 직선 가와 직선 나는 직선 ㉠(빨간색 직선)과 어떻게 만나나요?',ARRAY['M4-2-u2-X23','M4-2-u2-X03','M4-2-u2-X04']::text[],false,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 직선 가와 직선 나는 직선 ㉠(빨간색 직선)과 어떻게 만나나요?","options":[{"t":"둘 다 직선 ㉠과 서로 수직으로 만나요","correct":true},{"t":"둘 다 직선 ㉠과 만나지 않아요","mis":"M4-2-u2-X23"},{"t":"둘 다 직선 ㉠과 비스듬히 만나요","mis":"M4-2-u2-X03"},{"t":"직선 가만 직선 ㉠과 수직으로 만나요","mis":"M4-2-u2-X04"}],"explanation":["직선 가와 직선 ㉠이 만나서 이루는 각은 직각이에요.","직선 나와 직선 ㉠이 만나서 이루는 각도 직각이에요.","한 직선에 수직인 두 직선은 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,52.5],[150.0,52.5]],[[0.0,97.5],[150.0,75.0]],[[45.0,0.0],[45.0,105.0]]],"lab":[[[13.5,33.8],"가"],[[136.5,41.2],"나"],[[11.7,84.4],"다"],[[56.2,69.0],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#4','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',1,'ox','auto','「문제 척」 — 생활 속에서 평행선을 찾았어요. 공책의 줄은 서로 평행해요.',ARRAY['M4-2-u2-X06']::text[],true,'{"seq":4,"concept":"M4-2-u2-C3","difficulty":1,"kind":"ox","stem":"「문제 척」 — 생활 속에서 평행선을 찾았어요. 공책의 줄은 서로 평행해요.","answer":"O","reason_options":[{"t":"공책의 줄은 끝없이 늘여도 서로 만나지 않고 두 줄에 공통의 수선을 그을 수 있어서","correct":true},{"t":"공책의 줄은 길이가 같아서","mis":"M4-2-u2-X06"}],"mis":"M4-2-u2-X06","explanation":["평행선인지는 두 직선이 만나는지 만나지 않는지로 정해요.","공책의 줄에 공통의 수선을 그을 수 있어요.","그래서 공책의 줄은 평행선이에요(O)."],"variant_rule":{"alt":[{"stem":"「문제 척」 — 생활 속에서 평행선을 찾았어요. 악보의 오선은 서로 평행해요.","answer":"O","reason_options":[{"t":"오선의 줄들은 늘여도 서로 만나지 않아서","correct":true},{"t":"줄이 가로로 놓여 있어서","mis":"M4-2-u2-X01"}],"explanation":["평행선은 가로로 놓였는지가 아니라 만나지 않는지로 정해요.","오선의 줄들은 서로 만나지 않아요.","평행선이에요(O)."]},{"stem":"「문제 척」 — 생활 속에서 평행선을 찾았어요. 운동장의 달리기 트랙 선은 서로 평행해요.","answer":"O","reason_options":[{"t":"곧게 그어진 트랙 선들은 늘여도 서로 만나지 않아서","correct":true},{"t":"트랙 선의 색이 같아서","mis":"M4-2-u2-X06"}],"explanation":["곧은 트랙 선들 사이의 간격이 일정해요.","늘여도 서로 만나지 않아요.","평행선이에요(O)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#5','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',2,'mc','auto','「수학익힘」 — 두 선분을 양쪽으로 끝없이 늘인다고 생각할 때, 서로 평행한 것을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X06','M4-2-u2-X05','M4-2-u2-X18']::text[],false,'{"seq":5,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 두 선분을 양쪽으로 끝없이 늘인다고 생각할 때, 서로 평행한 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯, ㉱","correct":true},{"t":"㉯","mis":"M4-2-u2-X06"},{"t":"㉯, ㉰, ㉱","mis":"M4-2-u2-X05"},{"t":"㉮, ㉰","mis":"M4-2-u2-X18"}],"explanation":["두 선분을 양쪽으로 늘였을 때 만나는지 생각해요.","㉯는 비스듬해도, ㉱는 엇갈려 놓여 있어도 늘이면 만나지 않아요 — 평행해요.","㉰는 그림 안에서는 안 만나지만 늘이면 만나요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"seg":[[[7.5,22.5],[97.5,75.0]],[[30.0,82.5],[75.0,7.5]]]},{"w":105,"h":90,"seg":[[[7.5,75.0],[60.0,7.5]],[[37.5,82.5],[90.0,15.0]]]},{"w":105,"h":90,"seg":[[[30.0,7.5],[30.0,82.5]],[[52.5,82.5],[75.0,7.5]]]},{"w":105,"h":90,"seg":[[[45.0,22.5],[97.5,22.5]],[[7.5,67.5],[60.0,67.5]]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#6','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C1',2,'mc','auto','「수학익힘」 — 그림을 보고 답하세요. 직선 가에 수직인 직선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X03']::text[],true,'{"seq":6,"concept":"M4-2-u2-C1","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 그림을 보고 답하세요. 직선 가에 수직인 직선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 다, 직선 마","correct":true},{"t":"직선 다","mis":"M4-2-u2-X04"},{"t":"직선 나, 직선 라","mis":"M4-2-u2-X18"},{"t":"직선 나, 직선 다, 직선 라, 직선 마","mis":"M4-2-u2-X03"}],"explanation":["직선 가와 직각으로 만나는 직선을 찾아요.","직선 다와 직선 마가 직선 가와 직각으로 만나요.","직선 나·라는 비스듬히 만나요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,90.0],[150.0,90.0]],[[7.5,90.0],[37.5,0.0]],[[60.0,0.0],[60.0,105.0]],[[82.5,0.0],[105.0,105.0]],[[127.5,0.0],[127.5,105.0]]],"lab":[[[36.0,78.8],"가"],[[22.6,9.2],"나"],[[71.2,36.0],"다"],[[96.3,10.8],"라"],[[138.8,13.5],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 그림을 보고 답하세요. 서로 평행한 직선은 어느 것인가요?","options":[{"t":"직선 다와 직선 마","correct":true},{"t":"직선 나와 직선 라","mis":"M4-2-u2-X05"},{"t":"직선 가와 직선 다","mis":"M4-2-u2-X23"},{"t":"직선 가와 직선 마","mis":"M4-2-u2-X23"}],"explanation":["직선 다와 직선 마는 모두 직선 가에 수직이에요.","한 직선에 수직인 두 직선은 만나지 않아요.","그래서 직선 다와 직선 마가 평행해요 — 직선 가와 직선 다는 수직이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,90.0],[150.0,90.0]],[[7.5,90.0],[37.5,0.0]],[[60.0,0.0],[60.0,105.0]],[[82.5,0.0],[105.0,105.0]],[[127.5,0.0],[127.5,105.0]]],"lab":[[[36.0,78.8],"가"],[[22.6,9.2],"나"],[[71.2,36.0],"다"],[[96.3,10.8],"라"],[[138.8,13.5],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#7','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',2,'mc','auto','「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 그어요. 바른 방법은 어느 것인가요?',ARRAY['M4-2-u2-X24','M4-2-u2-X23']::text[],true,'{"seq":7,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 그어요. 바른 방법은 어느 것인가요?","options":[{"t":"주어진 직선에 두 삼각자의 한 변을 맞추고, 한 삼각자는 고정한 채 다른 삼각자를 움직여 직선을 그어요","correct":true},{"t":"두 삼각자를 모두 움직이며 직선을 그어요","mis":"M4-2-u2-X24"},{"t":"주어진 직선에 삼각자의 직각을 낀 한 변을 맞추고 다른 변을 따라 그어요","mis":"M4-2-u2-X23"},{"t":"삼각자 없이 나란해 보이게 그어요","mis":"M4-2-u2-X24"}],"explanation":["주어진 직선에 두 삼각자의 한 변을 맞춰요.","한 삼각자는 꼭 잡아 고정하고, 다른 삼각자만 움직여 직선을 그어요.","직각을 낀 다른 변을 따라 그으면 평행선이 아니라 수선이 돼요."],"variant_rule":{"alt":[{"stem":"「수학에 퐁당」 — 알지오매스 키즈로 직선을 그리고 그 직선의 평행선을 그렸어요. 평행선을 잡고 이리저리 움직여 보면 두 직선은 어떻게 되나요?","options":[{"t":"어디로 움직여도 서로 만나지 않아요","correct":true},{"t":"움직이면 서로 만나요","mis":"M4-2-u2-X05"},{"t":"움직이면 서로 수직이 돼요","mis":"M4-2-u2-X23"},{"t":"두 직선 사이의 간격이 곳곳마다 달라져요","mis":"M4-2-u2-X08"}],"explanation":["평행선 도구로 그린 직선은 처음 직선과 평행해요.","움직여도 방향은 그대로라 두 직선은 만나지 않아요.","두 직선 사이의 간격도 어디서나 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#8','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',2,'mc','auto','「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X23']::text[],true,'{"seq":8,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㅁㅂ, 변 ㄷㄹ","correct":true},{"t":"변 ㅁㅂ","mis":"M4-2-u2-X04"},{"t":"변 ㄴㄷ, 변 ㄹㅁ, 변 ㅂㄱ","mis":"M4-2-u2-X23"},{"t":"변 ㄷㄹ","mis":"M4-2-u2-X04"}],"explanation":["변 ㄱㄴ을 양쪽으로 늘였을 때 만나지 않는 변을 찾아요.","변 ㅁㅂ과 변 ㄷㄹ이 변 ㄱㄴ과 평행해요 — 길이가 달라도 평행해요.","변 ㄴㄷ·ㄹㅁ·ㅂㄱ은 변 ㄱㄴ과 수직이에요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄴ":[15.0,90.0,"sw"],"ㄷ":[120.0,90.0,"se"],"ㄹ":[120.0,52.5,"ne"],"ㅁ":[90.0,52.5,"sw"],"ㅂ":[90.0,15.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"right":[["ㅂ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㅁ"],["ㄹ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 도형에서 변 ㄴㄷ과 평행한 변을 모두 고른 것은 어느 것인가요?","options":[{"t":"변 ㄹㅁ, 변 ㅂㄱ","correct":true},{"t":"변 ㄹㅁ","mis":"M4-2-u2-X04"},{"t":"변 ㄱㄴ, 변 ㄷㄹ, 변 ㅁㅂ","mis":"M4-2-u2-X23"},{"t":"변 ㅂㄱ","mis":"M4-2-u2-X04"}],"explanation":["변 ㄴㄷ을 늘였을 때 만나지 않는 변을 찾아요.","변 ㄹㅁ과 변 ㅂㄱ이 평행해요.","세로 변들은 변 ㄴㄷ과 수직이에요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄴ":[15.0,90.0,"sw"],"ㄷ":[120.0,90.0,"se"],"ㄹ":[120.0,52.5,"ne"],"ㅁ":[90.0,52.5,"sw"],"ㅂ":[90.0,15.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"right":[["ㅂ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㅁ"],["ㄹ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#9','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',2,'mc','auto','「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X06','M4-2-u2-X23']::text[],false,'{"seq":9,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자를 모두 고른 것은 어느 것인가요?","options":[{"t":"ㅁ, ㅂ, ㅋ, ㅍ","correct":true},{"t":"ㅁ, ㅂ, ㅍ","mis":"M4-2-u2-X06"},{"t":"ㄱ, ㄴ","mis":"M4-2-u2-X23"},{"t":"ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ","mis":"M4-2-u2-X23"}],"explanation":["글자의 획을 선분으로 보고, 늘여도 만나지 않는 두 획을 찾아요.","ㅁ·ㅂ·ㅍ에는 평행한 획이 있고, ㅋ의 두 가로획도 길이는 달라도 평행해요.","ㄱ·ㄴ은 두 획이 직각으로 만날 뿐 평행선이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_basic#10','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_basic','lesson_basic','M4-2-u2-C3',3,'mc','auto','「확인 문제」 — 그림에서 직선 나에 대한 수선을 모두 찾고, 그 수선끼리의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X03','M4-2-u2-X04']::text[],false,'{"seq":10,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"「확인 문제」 — 그림에서 직선 나에 대한 수선을 모두 찾고, 그 수선끼리의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"직선 다, 직선 라 — 서로 평행해요","correct":true},{"t":"직선 다, 직선 라 — 서로 수직이에요","mis":"M4-2-u2-X23"},{"t":"직선 가, 직선 다 — 서로 평행해요","mis":"M4-2-u2-X03"},{"t":"직선 다 — 수선은 하나뿐이에요","mis":"M4-2-u2-X04"}],"explanation":["직선 나와 직각으로 만나는 직선은 직선 다와 직선 라예요.","한 직선에 수직인 두 직선은 만나지 않아요.","그래서 직선 다와 직선 라는 평행선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,105.0],[60.0,0.0]],[[0.0,60.0],[150.0,60.0]],[[82.5,0.0],[82.5,105.0]],[[120.0,0.0],[120.0,105.0]]],"lab":[[[30.7,97.0],"가"],[[13.5,48.8],"나"],[[93.8,13.5],"다"],[[131.2,13.5],"라"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#1','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',2,'match','auto','알맞은 말끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u2-C3","difficulty":2,"kind":"match","stem":"알맞은 말끼리 이으세요.","pairs":[{"l":"두 직선이 만나서 이루는 각이 직각인 관계","r":"수직"},{"l":"한 직선에 수직인 두 직선처럼 서로 만나지 않는 관계","r":"평행"},{"l":"평행한 두 직선","r":"평행선"}],"mis":"M4-2-u2-X02","explanation":["수직과 평행은 두 직선의 관계예요.","평행선은 평행한 두 직선을 가리켜요.","관계를 나타내는 말과 직선을 가리키는 말을 구별해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 말끼리 이으세요.","pairs":[{"l":"서로 수직으로 만날 때 한 직선을 다른 직선에 대해 부르는 말","r":"수선"},{"l":"한 평면 위에서 서로 만나지 않는 두 직선","r":"평행선"},{"l":"양쪽으로 끝이 없는 곧은 선","r":"직선"}],"explanation":["수선은 수직으로 만나는 직선이에요.","평행선은 만나지 않는 두 직선이에요.","직선은 양쪽으로 끝이 없는 곧은 선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#2','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',2,'ox','auto','「헷갈려요」 — 그림의 두 선분은 나란히 마주 놓여 있지 않고 엇갈려 있으니 평행하지 않아요.',ARRAY['M4-2-u2-X06']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 그림의 두 선분은 나란히 마주 놓여 있지 않고 엇갈려 있으니 평행하지 않아요.","answer":"X","reason_options":[{"t":"양쪽으로 끝없이 늘여도 서로 만나지 않으면 평행해서","correct":true},{"t":"두 선분이 나란히 마주 놓여 있어야 평행해서","mis":"M4-2-u2-X06"}],"mis":"M4-2-u2-X06","explanation":["평행인지는 나란히 놓인 모습이 아니라 만나는지로 정해요.","두 선분을 양쪽으로 늘이면 서로 만나지 않아요.","그래서 평행해요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"seg":[[[45.0,22.5],[97.5,22.5]],[[7.5,67.5],[60.0,67.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#3','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'mc','auto','「생각해 봐요」 — 직선을 실제로 끝없이 늘여 볼 수 없는데도 직선 가와 직선 나가 만나지 않는다는 것을 어떻게 알 수 있나요?',ARRAY['M4-2-u2-X05','M4-2-u2-X06','M4-2-u2-X01']::text[],false,'{"seq":3,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 직선을 실제로 끝없이 늘여 볼 수 없는데도 직선 가와 직선 나가 만나지 않는다는 것을 어떻게 알 수 있나요?","options":[{"t":"두 직선에 공통으로 수직인 직선을 그을 수 있고, 모눈으로 보면 두 직선 사이의 간격이 일정해서","correct":true},{"t":"그림 안에서 두 직선이 만나지 않아서","mis":"M4-2-u2-X05"},{"t":"두 직선의 길이가 같아서","mis":"M4-2-u2-X06"},{"t":"두 직선이 모두 가로로 놓여 있어서","mis":"M4-2-u2-X01"}],"explanation":["직선은 끝이 없어서 그림만으로는 알 수 없어요.","두 직선이 모두 직선 ㉠에 수직이에요 — 공통의 수선이 있어요.","모눈의 수를 세어 보면 간격도 일정해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,52.5],[150.0,52.5]],[[0.0,97.5],[150.0,75.0]],[[45.0,0.0],[45.0,105.0]]],"lab":[[[13.5,33.8],"가"],[[136.5,41.2],"나"],[[11.7,84.4],"다"],[[56.2,69.0],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#4','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'mc','auto','「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X23','M4-2-u2-X06']::text[],false,'{"seq":4,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄹㄷ","correct":true},{"t":"변 ㄱㄹ과 변 ㄴㄷ","mis":"M4-2-u2-X03"},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M4-2-u2-X23"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X06"}],"explanation":["변 ㄱㄴ과 변 ㄹㄷ은 모두 변 ㄴㄷ에 수직이에요.","한 직선에 수직인 두 직선(변)은 평행해요.","변 ㄱㄹ은 기울어져 있어 변 ㄴㄷ과 평행하지 않아요."],"asset":{"type":"geo","items":[{"w":96.0,"h":103.5,"pts":{"ㄱ":[18.0,36.0,"nw"],"ㄴ":[18.0,85.5,"sw"],"ㄷ":[78.0,85.5,"se"],"ㄹ":[78.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#5','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'sa','auto','「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C3","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변 ㄱㄴ과 만나지 않는 변을 찾아요.","변 ㅁㅂ, 변 ㄷㄹ — 길이는 달라도 평행해요.","2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄴ":[15.0,90.0,"sw"],"ㄷ":[120.0,90.0,"se"],"ㄹ":[120.0,52.5,"ne"],"ㅁ":[90.0,52.5,"sw"],"ㅂ":[90.0,15.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"right":[["ㅂ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㅁ"],["ㄹ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 도형에서 변 ㄴㄷ과 평행한 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변 ㄴㄷ을 늘였을 때 만나지 않는 변을 찾아요.","변 ㄹㅁ, 변 ㅂㄱ이에요.","2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄴ":[15.0,90.0,"sw"],"ㄷ":[120.0,90.0,"se"],"ㄹ":[120.0,52.5,"ne"],"ㅁ":[90.0,52.5,"sw"],"ㅂ":[90.0,15.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"right":[["ㅂ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㅁ"],["ㄹ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#6','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'error','auto','「문제 척」 — 생활 속에서 평행선을 찾아 이야기했어요. 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X18']::text[],false,'{"seq":6,"concept":"M4-2-u2-C3","difficulty":3,"kind":"error","stem":"「문제 척」 — 생활 속에서 평행선을 찾아 이야기했어요. 잘못 말한 사람은 누구인가요?","options":[{"t":"건우 — 「운동장의 출발선과 트랙 선은 서로 직각으로 만나니까 평행선이야.」","correct":true,"mis_target":"M4-2-u2-X23"},{"t":"은비 — 「악보의 오선에서 평행선을 찾았어.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「계단의 난간에서 평행선을 찾았어.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「칠판의 위쪽 테두리와 아래쪽 테두리는 평행선이야.」","mis":"M4-2-u2-X18"}],"explanation":["평행선은 서로 만나지 않는 두 직선이에요.","직각으로 만나는 두 선은 평행선이 아니라 서로 수직이에요.","건우의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#7','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',3,'mc','auto','「수학익힘」 — 직선 다와 직선 마는 모두 직선 가에 수직이에요. 직선 다와 직선 마는 서로 어떤 관계인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X05','M4-2-u2-X06']::text[],false,'{"seq":7,"concept":"M4-2-u2-C3","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 직선 다와 직선 마는 모두 직선 가에 수직이에요. 직선 다와 직선 마는 서로 어떤 관계인가요?","options":[{"t":"서로 평행해요","correct":true},{"t":"서로 수직이에요","mis":"M4-2-u2-X23"},{"t":"늘이면 만나요","mis":"M4-2-u2-X05"},{"t":"알 수 없어요","mis":"M4-2-u2-X06"}],"explanation":["직선 다는 직선 가에 수직이에요.","직선 마도 직선 가에 수직이에요.","한 직선에 수직인 두 직선은 만나지 않아요 — 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,90.0],[150.0,90.0]],[[60.0,0.0],[60.0,105.0]],[[127.5,0.0],[127.5,105.0]]],"lab":[[[13.5,78.8],"가"],[[48.8,13.5],"다"],[[116.2,13.5],"마"]],"right":[[[150.0,90.0],[60.0,90.0],[60.0,105.0]],[[150.0,90.0],[127.5,90.0],[127.5,105.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#8','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'sa','auto','「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C3","difficulty":4,"kind":"sa","stem":"「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["글자의 획에서 서로 만나지 않는 두 획을 찾아요.","ㅁ, ㅂ, ㅋ, ㅍ에 평행한 획이 있어요 — ㅋ의 두 가로획은 길이가 달라도 평행해요.","4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#9','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'essay','teacher','「개념 쏙」 — 직선 가와 직선 나가 서로 평행한 까닭을 「수직」이라는 말을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C3","difficulty":4,"kind":"essay","stem":"「개념 쏙」 — 직선 가와 직선 나가 서로 평행한 까닭을 「수직」이라는 말을 넣어 설명해 보세요.","answer_guide":{"answer":"예: 직선 가와 직선 나는 모두 직선 ㉠에 수직입니다. 한 직선에 수직인 두 직선은 끝없이 늘여도 만나지 않으므로 직선 가와 직선 나는 서로 평행합니다.","scoring_points":["두 직선이 모두 직선 ㉠에 수직이라고 썼는가","늘여도 만나지 않는다고 썼는가","그래서 평행하다고 결론을 냈는가"]},"explanation":["평행은 수직을 바탕으로 정해요.","한 직선에 수직인 두 직선은 만나지 않아요.","그래서 두 직선은 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,52.5],[150.0,52.5]],[[0.0,97.5],[150.0,75.0]],[[45.0,0.0],[45.0,105.0]]],"lab":[[[13.5,33.8],"가"],[[136.5,41.2],"나"],[[11.7,84.4],"다"],[[56.2,69.0],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L03_challenge#10','math',4,2,'u2','L03','tb_g4_2_math_u2_L03_challenge','lesson_challenge','M4-2-u2-C3',4,'essay','teacher','「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 긋는 방법을 쓰고, 그은 직선이 주어진 직선과 평행한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C3","difficulty":4,"kind":"essay","stem":"「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 긋는 방법을 쓰고, 그은 직선이 주어진 직선과 평행한 까닭을 써 보세요.","answer_guide":{"answer":"예: 주어진 직선에 두 삼각자의 한 변을 맞춘 다음 한 삼각자를 고정하고 다른 삼각자를 움직여 직선을 긋습니다. 삼각자의 한 변과 주어진 직선이 서로 수직이고 그 변과 그은 직선도 서로 수직이므로 두 직선은 평행합니다.","scoring_points":["두 삼각자를 맞추고 한 삼각자를 고정해 움직인다고 썼는가","두 직선이 삼각자의 한 변에 각각 수직이라고 썼는가","그래서 평행하다고 썼는가"]},"explanation":["한 삼각자는 고정하고 다른 삼각자만 움직여요.","삼각자의 한 변이 두 직선에 모두 수직이에요.","한 직선에 수직인 두 직선은 평행해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#1','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'mc','auto','「개념 쏙」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 그었을 때, 이 선분의 길이를 무엇이라고 하나요?',ARRAY['M4-2-u2-X02','M4-2-u2-X07']::text[],false,'{"seq":1,"concept":"M4-2-u2-C4","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 그었을 때, 이 선분의 길이를 무엇이라고 하나요?","options":[{"t":"평행선 사이의 거리","correct":true},{"t":"수선의 길이","mis":"M4-2-u2-X02"},{"t":"평행선의 길이","mis":"M4-2-u2-X07"},{"t":"가장 긴 선분의 길이","mis":"M4-2-u2-X07"}],"explanation":["평행선의 한 직선에서 다른 직선에 수직인 선분을 그어요.","그 선분의 길이를 평행선 사이의 거리라고 해요.","수직인 선분은 평행선 사이에 그은 선분 가운데 가장 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#2','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'mc','auto','「생각 톡」 — 점 ㄱ에서 직선 나에 선분을 여러 개 그었어요. 그은 선분 가운데 길이가 가장 짧은 선분은 직선 나와 어떻게 만나나요?',ARRAY['M4-2-u2-X07','M4-2-u2-X22','M4-2-u2-X23']::text[],false,'{"seq":2,"concept":"M4-2-u2-C4","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 점 ㄱ에서 직선 나에 선분을 여러 개 그었어요. 그은 선분 가운데 길이가 가장 짧은 선분은 직선 나와 어떻게 만나나요?","options":[{"t":"수직으로 만나요","correct":true},{"t":"비스듬히 만나요","mis":"M4-2-u2-X07"},{"t":"만나지 않아요","mis":"M4-2-u2-X22"},{"t":"평행하게 만나요","mis":"M4-2-u2-X23"}],"explanation":["점 ㄱ에서 직선 나에 수직인 선분 1개와 수직이 아닌 선분 3개를 그었어요.","길이를 재어 보면 수직인 선분이 가장 짧아요.","가장 짧은 선분과 평행선이 만나서 이루는 각은 직각이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[75.0,22.5],[75.0,82.5]],[[75.0,22.5],[22.5,82.5]],[[75.0,22.5],[112.5,82.5]],[[75.0,22.5],[138.0,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"]],"right":[[[75.0,22.5],[75.0,82.5],[90.0,82.5]]],"pts":{"ㄱ":[75.0,22.5,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#3','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'sa','auto','「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 길이가 가장 짧은 선분을 재었더니 3 cm였어요. 평행선 가와 나 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 길이가 가장 짧은 선분을 재었더니 3 cm였어요. 평행선 가와 나 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가장 짧은 선분은 직선 나와 수직으로 만나요.","평행선의 한 직선에서 다른 직선에 그은 수직인 선분의 길이가 평행선 사이의 거리예요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[75.0,22.5],[75.0,82.5]],[[75.0,22.5],[22.5,82.5]],[[75.0,22.5],[112.5,82.5]],[[75.0,22.5],[138.0,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"]],"right":[[[75.0,22.5],[75.0,82.5],[90.0,82.5]]],"pts":{"ㄱ":[75.0,22.5,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 도로에서 찾은 평행한 두 직선 가와 나가 있어요. 직선 가에서 직선 나에 수직인 선분을 긋고 재었더니 2 cm였어요. 직선 가와 나 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["직선 가에서 직선 나에 수직인 선분을 그었어요.","이 선분의 길이가 평행선 사이의 거리예요.","2 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#4','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',1,'sa','auto','「개념 톡」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 긋고 재었더니 2 cm였어요. 평행선 사이의 거리를 나타내는 선분을 다른 곳에 한 개 더 그어 재면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「개념 톡」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 긋고 재었더니 2 cm였어요. 평행선 사이의 거리를 나타내는 선분을 다른 곳에 한 개 더 그어 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["평행선 사이의 거리를 나타내는 선분은 어디에 그어도 돼요.","그은 선분의 길이를 비교하면 같아요 — 평행선 사이의 거리는 일정해요.","2 cm예요."],"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 평행선 사이의 거리를 재었더니 4 cm였어요. 같은 평행선의 다른 곳에서 수직인 선분을 그어 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행선 사이의 거리는 어디서 재든 같아요.","수직인 선분의 길이는 모두 같아요.","4 cm예요."]},{"stem":"「스스로 마무리하기」 — 비스듬히 놓인 평행선 사이의 거리를 재었더니 1 cm였어요. 다른 곳에서 수직인 선분을 그어 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["평행선이 비스듬히 놓여 있어도 거리를 재는 방법은 같아요.","수직인 선분의 길이는 어디서나 같아요.","1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#5','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'mc','auto','「수학익힘」 — 직선 가와 나는 평행해요. 삼각자를 사용하여 직선 가와 나 사이의 거리를 나타내는 선분을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X07']::text[],true,'{"seq":5,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 직선 가와 나는 평행해요. 삼각자를 사용하여 직선 가와 나 사이의 거리를 나타내는 선분을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉢, ㉤","correct":true},{"t":"㉢","mis":"M4-2-u2-X04"},{"t":"㉠, ㉡, ㉣","mis":"M4-2-u2-X18"},{"t":"㉠, ㉢, ㉤","mis":"M4-2-u2-X07"}],"explanation":["평행선 사이의 거리는 두 직선에 수직인 선분의 길이예요.","㉢과 ㉤이 두 직선과 직각으로 만나요.","비스듬한 ㉠·㉡·㉣은 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[33.0,22.5],[54.0,82.5]],[[66.0,22.5],[58.5,82.5]],[[87.0,22.5],[87.0,82.5]],[[120.0,22.5],[102.0,82.5]],[[139.5,22.5],[139.5,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"],[[33.0,12.8],"㉠"],[[66.0,12.8],"㉡"],[[87.0,12.8],"㉢"],[[120.0,12.8],"㉣"],[[139.5,12.8],"㉤"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 직선 가와 나는 평행해요. 평행선 사이의 거리를 나타내는 선분을 고른 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M4-2-u2-X07"},{"t":"㉡, ㉢","mis":"M4-2-u2-X07"},{"t":"㉣","mis":"M4-2-u2-X07"}],"explanation":["두 직선에 수직인 선분을 찾아요.","㉢만 직선 가·나와 직각으로 만나요.","나머지는 비스듬한 선분이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[36.0,22.5],[21.0,82.5]],[[66.0,22.5],[87.0,82.5]],[[99.0,22.5],[99.0,82.5]],[[126.0,22.5],[141.0,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"],[[36.0,12.8],"㉠"],[[66.0,12.8],"㉡"],[[99.0,12.8],"㉢"],[[126.0,12.8],"㉣"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#6','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'sa','auto','「수학익힘」 — 직선 가와 나는 평행해요. 그림의 세 선분 가운데 직선 가와 나 사이의 거리를 나타내는 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 직선 가와 나는 평행해요. 그림의 세 선분 가운데 직선 가와 나 사이의 거리를 나타내는 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["평행선 사이의 거리는 두 직선에 수직인 선분의 길이예요.","직각 표시가 있는 3 cm 선분이 수직인 선분이에요.","4 cm·3.5 cm 선분은 비스듬해요 — 3 cm예요."],"asset":{"type":"geo","items":[{"w":165,"h":105,"line":[[[0.0,15.0],[165.0,15.0]],[[0.0,82.5],[165.0,82.5]]],"seg":[[[24.0,15.0],[24.0,82.5]],[[72.0,15.0],[108.0,82.5]],[[123.0,15.0],[144.0,82.5]]],"lab":[[[6.8,26.2],"가"],[[6.8,93.8],"나"],[[43.5,48.8],"3 cm"],[[103.5,48.8],"4 cm"],[[147.0,48.8],"3.5 cm"]],"right":[[[24.0,15.0],[24.0,82.5],[39.0,82.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#7','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'mc','auto','「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 평행해요. 평행선 사이의 거리를 재려면 어느 변의 길이를 재어야 하나요?',ARRAY['M4-2-u2-X07','M4-2-u2-X23']::text[],false,'{"seq":7,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 평행해요. 평행선 사이의 거리를 재려면 어느 변의 길이를 재어야 하나요?","options":[{"t":"변 ㄱㄹ","correct":true},{"t":"변 ㄴㄷ","mis":"M4-2-u2-X07"},{"t":"변 ㄱㄴ","mis":"M4-2-u2-X23"},{"t":"변 ㄹㄷ","mis":"M4-2-u2-X23"}],"explanation":["변 ㄱㄴ과 변 ㄹㄷ에 모두 수직인 변을 찾아요.","각 ㄱ과 각 ㄹ이 직각이라 변 ㄱㄹ이 두 변에 수직이에요.","변 ㄴㄷ은 비스듬해서 거리를 나타내지 않아요."],"asset":{"type":"geo","items":[{"w":126.0,"h":90.0,"pts":{"ㄱ":[18.0,18.0,"nw"],"ㄴ":[18.0,72.0,"sw"],"ㄷ":[108.0,45.0,"e"],"ㄹ":[108.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#8','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'mc','auto','「수학에 퐁당」 — 친구는 평행선 사이에 가로로 선분을 긋고 3 cm라고 했어요. 바르게 잰 평행선 사이의 거리는 몇 cm인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X08','M4-2-u2-X22']::text[],false,'{"seq":8,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「수학에 퐁당」 — 친구는 평행선 사이에 가로로 선분을 긋고 3 cm라고 했어요. 바르게 잰 평행선 사이의 거리는 몇 cm인가요?","options":[{"t":"2 cm","correct":true},{"t":"3 cm","mis":"M4-2-u2-X07"},{"t":"2 cm와 3 cm 둘 다 맞아요","mis":"M4-2-u2-X08"},{"t":"평행선이 비스듬해서 잴 수 없어요","mis":"M4-2-u2-X22"}],"explanation":["평행선 사이의 거리는 한 직선에서 다른 직선에 그은 수직인 선분의 길이예요.","친구가 그은 가로 선분은 평행선과 수직이 아니에요.","수직인 선분을 바르게 그어 재면 2 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"seg":[[[7.5,15.0],[103.5,91.8]],[[52.5,15.0],[148.5,91.8]],[[43.5,43.8],[88.5,43.8]]],"lab":[[[66.0,34.8],"3 cm"]]},{"w":150,"h":105,"seg":[[[7.5,15.0],[103.5,91.8]],[[52.5,15.0],[148.5,91.8]],[[43.5,43.8],[61.1,21.8]]],"right":[[[43.5,43.8],[61.1,21.8],[91.1,45.8]]],"lab":[[[49.3,22.3],"2 cm"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#9','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',2,'mc','auto','「문제 척」 — 평행선 사이의 거리가 3 cm인 평행선을 완성하려고 해요. 바른 방법은 어느 것인가요?',ARRAY['M4-2-u2-X24','M4-2-u2-X07']::text[],true,'{"seq":9,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「문제 척」 — 평행선 사이의 거리가 3 cm인 평행선을 완성하려고 해요. 바른 방법은 어느 것인가요?","options":[{"t":"주어진 직선에 두 삼각자의 한 변을 맞추고, 한 삼각자를 고정한 채 다른 삼각자를 3 cm만큼 움직여 직선을 그어요","correct":true},{"t":"두 삼각자를 함께 3 cm만큼 움직여 직선을 그어요","mis":"M4-2-u2-X24"},{"t":"주어진 직선에 비스듬히 3 cm 선분을 긋고, 그 끝에서 나란해 보이게 그어요","mis":"M4-2-u2-X07"},{"t":"주어진 직선에서 3 cm 떨어진 점 하나를 찍고 아무 방향으로나 그어요","mis":"M4-2-u2-X24"}],"explanation":["삼각자 두 개를 사용해요.","한 삼각자는 고정하고, 다른 삼각자를 주어진 직선과 수직인 방향으로 3 cm만큼 움직여요.","비스듬히 잰 3 cm는 평행선 사이의 거리가 아니에요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 평행선 사이의 거리가 2.5 cm가 되도록 주어진 직선과 평행한 직선을 그으려고 해요. 바른 방법은 어느 것인가요?","options":[{"t":"한 삼각자를 고정하고, 다른 삼각자를 주어진 직선과 수직인 방향으로 2.5 cm만큼 움직여 직선을 그어요","correct":true},{"t":"두 삼각자를 함께 2.5 cm만큼 움직여 직선을 그어요","mis":"M4-2-u2-X24"},{"t":"주어진 직선에 비스듬히 2.5 cm 선분을 긋고 그 끝에서 나란해 보이게 그어요","mis":"M4-2-u2-X07"},{"t":"주어진 직선에 수선을 긋고 그 수선을 2.5 cm로 그려요","mis":"M4-2-u2-X23"}],"explanation":["평행선 사이의 거리는 수직인 방향으로 재요.","한 삼각자는 고정하고 다른 삼각자를 2.5 cm만큼 움직여요.","그은 직선과 주어진 직선 사이의 수직인 선분이 2.5 cm가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_basic#10','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_basic','lesson_basic','M4-2-u2-C4',3,'ox','auto','「개념 톡」 — 평행선 사이의 거리는 어디에서 재든 같아요.',ARRAY['M4-2-u2-X08']::text[],false,'{"seq":10,"concept":"M4-2-u2-C4","difficulty":3,"kind":"ox","stem":"「개념 톡」 — 평행선 사이의 거리는 어디에서 재든 같아요.","answer":"O","reason_options":[{"t":"평행선의 한 직선에서 다른 직선에 그은 수직인 선분의 길이는 모두 같아서","correct":true},{"t":"평행선의 왼쪽과 오른쪽은 떨어진 정도가 달라서","mis":"M4-2-u2-X08"}],"mis":"M4-2-u2-X08","explanation":["평행선 사이의 거리를 나타내는 선분을 여러 곳에 그어 재어 봐요.","그은 선분의 길이가 모두 같아요.","평행선 사이의 거리는 일정해요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#1','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',2,'mc','auto','「생각해 봐요」 — 도로의 폭을 잴 때 어느 곳을 재야 할까요?',ARRAY['M4-2-u2-X07','M4-2-u2-X02']::text[],true,'{"seq":1,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「생각해 봐요」 — 도로의 폭을 잴 때 어느 곳을 재야 할까요?","options":[{"t":"도로의 두 경계선에 수직인 선분의 길이","correct":true},{"t":"두 경계선을 비스듬히 잇는 선분의 길이","mis":"M4-2-u2-X07"},{"t":"두 경계선을 잇는 가장 긴 선분의 길이","mis":"M4-2-u2-X07"},{"t":"경계선 하나의 길이","mis":"M4-2-u2-X02"}],"explanation":["도로의 두 경계선은 평행선이에요.","도로의 폭은 평행선 사이의 거리예요.","그래서 두 경계선에 수직인 선분의 길이를 재요."],"variant_rule":{"alt":[{"stem":"「생각해 봐요」 — 책장 선반 사이의 간격을 재려고 해요. 어느 곳을 재야 할까요?","options":[{"t":"위 선반과 아래 선반에 수직인 선분의 길이","correct":true},{"t":"위 선반의 왼쪽 끝과 아래 선반의 오른쪽 끝을 잇는 선분의 길이","mis":"M4-2-u2-X07"},{"t":"선반 하나의 길이","mis":"M4-2-u2-X02"},{"t":"재는 곳마다 달라서 정할 수 없어요","mis":"M4-2-u2-X08"}],"explanation":["책장의 위아래 선반은 평행해요.","선반 사이의 간격은 평행선 사이의 거리예요.","두 선반에 수직인 선분의 길이를 재요."]},{"stem":"「생각해 봐요」 — 기차선로의 두 레일 사이의 간격을 재려고 해요. 어느 곳을 재야 할까요?","options":[{"t":"두 레일에 수직인 선분의 길이","correct":true},{"t":"두 레일을 비스듬히 잇는 선분의 길이","mis":"M4-2-u2-X07"},{"t":"레일 하나의 길이","mis":"M4-2-u2-X02"},{"t":"재는 곳마다 달라서 정할 수 없어요","mis":"M4-2-u2-X08"}],"explanation":["두 레일은 평행선이에요.","레일 사이의 간격은 평행선 사이의 거리예요.","두 레일에 수직인 선분의 길이를 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#2','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',2,'ox','auto','「꼭 알아 둬요」 — 평행선 사이의 거리를 잴 때, 그은 선분의 끝이 평행선에 닿지 않거나 평행선을 지나쳐도 비슷하게만 재면 돼요.',ARRAY['M4-2-u2-X22']::text[],false,'{"seq":2,"concept":"M4-2-u2-C4","difficulty":2,"kind":"ox","stem":"「꼭 알아 둬요」 — 평행선 사이의 거리를 잴 때, 그은 선분의 끝이 평행선에 닿지 않거나 평행선을 지나쳐도 비슷하게만 재면 돼요.","answer":"X","reason_options":[{"t":"선분의 두 끝이 두 평행선에 꼭 닿아야 평행선 사이의 거리가 되어서","correct":true},{"t":"대강 비슷한 길이만 알면 되어서","mis":"M4-2-u2-X22"}],"mis":"M4-2-u2-X22","explanation":["평행선 사이의 거리는 한 직선에서 다른 직선까지 그은 수직인 선분의 길이예요.","선분이 평행선에 미치지 못하면 짧게, 지나치면 길게 재어져요.","선분을 평행선에 닿게 그어야 해요 — 이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#3','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'mc','auto','「스스로 마무리하기」 — 평행선 사이의 거리를 재었더니 4 cm였어요. 같은 평행선 사이에 비스듬한 선분을 그어 재면 그 길이는 4 cm와 비교해 어떤가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X08']::text[],true,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 — 평행선 사이의 거리를 재었더니 4 cm였어요. 같은 평행선 사이에 비스듬한 선분을 그어 재면 그 길이는 4 cm와 비교해 어떤가요?","options":[{"t":"4 cm보다 길어요","correct":true},{"t":"4 cm보다 짧아요","mis":"M4-2-u2-X07"},{"t":"4 cm와 같아요","mis":"M4-2-u2-X08"},{"t":"그을 때마다 4 cm보다 짧을 때도 있어요","mis":"M4-2-u2-X07"}],"explanation":["평행선 사이에 그은 선분 가운데 수직인 선분이 가장 짧아요.","비스듬한 선분은 수직인 선분보다 길어요.","그래서 4 cm보다 길어요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 세로로 놓인 평행선 사이의 거리를 재었더니 4.5 cm였어요. 같은 평행선 사이에 비스듬한 선분을 그어 재면 그 길이는 4.5 cm와 비교해 어떤가요?","options":[{"t":"4.5 cm보다 길어요","correct":true},{"t":"4.5 cm보다 짧아요","mis":"M4-2-u2-X07"},{"t":"4.5 cm와 같아요","mis":"M4-2-u2-X08"},{"t":"그을 때마다 4.5 cm보다 짧을 때도 있어요","mis":"M4-2-u2-X07"}],"explanation":["평행선이 세로로 놓여도 마찬가지예요.","수직인 선분이 가장 짧아요.","비스듬한 선분은 4.5 cm보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#4','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'error','auto','「더 해 봐요」 — 교실에 있는 물건에서 평행선 사이의 거리를 재었어요. 잘못 잰 사람은 누구인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X18']::text[],false,'{"seq":4,"concept":"M4-2-u2-C4","difficulty":3,"kind":"error","stem":"「더 해 봐요」 — 교실에 있는 물건에서 평행선 사이의 거리를 재었어요. 잘못 잰 사람은 누구인가요?","options":[{"t":"건우 — 「사물함 문의 두 테두리 사이를 비스듬히 대각선으로 재었어.」","correct":true,"mis_target":"M4-2-u2-X07"},{"t":"은비 — 「칠판의 위아래 테두리에 수직이 되게 자를 대고 재었어.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「공책의 두 줄 사이를 줄에 수직이 되게 재었어.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「책상의 두 모서리 사이를 삼각자의 직각을 대고 재었어.」","mis":"M4-2-u2-X18"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이로 재요.","비스듬히 잰 대각선은 수직인 선분보다 길어요.","건우가 잘못 재었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#5','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'ox','auto','「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 수직이 아닌 선분은 모두 수직인 선분보다 길어요.',ARRAY['M4-2-u2-X07']::text[],false,'{"seq":5,"concept":"M4-2-u2-C4","difficulty":3,"kind":"ox","stem":"「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 수직이 아닌 선분은 모두 수직인 선분보다 길어요.","answer":"O","reason_options":[{"t":"평행선 사이에 그은 선분 가운데 수직인 선분이 가장 짧아서","correct":true},{"t":"수직이 아닌 선분이 더 짧을 때도 있어서","mis":"M4-2-u2-X07"}],"mis":"M4-2-u2-X07","explanation":["점 ㄱ에서 수직인 선분 1개와 수직이 아닌 선분 3개를 그었어요.","재어 보면 수직인 선분이 가장 짧아요.","수직이 아닌 선분은 모두 더 길어요(O)."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[75.0,22.5],[75.0,82.5]],[[75.0,22.5],[22.5,82.5]],[[75.0,22.5],[112.5,82.5]],[[75.0,22.5],[138.0,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"]],"right":[[[75.0,22.5],[75.0,82.5],[90.0,82.5]]],"pts":{"ㄱ":[75.0,22.5,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#6','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'ox','auto','「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 평행선 사이의 거리는 변 ㄴㄷ의 길이예요.',ARRAY['M4-2-u2-X07']::text[],false,'{"seq":6,"concept":"M4-2-u2-C4","difficulty":3,"kind":"ox","stem":"「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 평행선 사이의 거리는 변 ㄴㄷ의 길이예요.","answer":"X","reason_options":[{"t":"평행선 사이의 거리는 두 변에 수직인 변 ㄱㄹ의 길이라서","correct":true},{"t":"두 변을 잇는 가장 긴 변이 거리라서","mis":"M4-2-u2-X07"}],"mis":"M4-2-u2-X07","explanation":["변 ㄱㄴ과 변 ㄹㄷ이 평행해요.","두 변에 수직인 변은 변 ㄱㄹ이에요.","변 ㄴㄷ은 비스듬해요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":126.0,"h":90.0,"pts":{"ㄱ":[18.0,18.0,"nw"],"ㄴ":[18.0,72.0,"sw"],"ㄷ":[108.0,45.0,"e"],"ㄹ":[108.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#7','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',3,'error','auto','「수학에 퐁당」 — 친구가 평행선 사이의 거리를 3 cm라고 풀었어요. 친구의 풀이에서 잘못된 점은 무엇인가요?',ARRAY['M4-2-u2-X07','M4-2-u2-X18']::text[],false,'{"seq":7,"concept":"M4-2-u2-C4","difficulty":3,"kind":"error","stem":"「수학에 퐁당」 — 친구가 평행선 사이의 거리를 3 cm라고 풀었어요. 친구의 풀이에서 잘못된 점은 무엇인가요?","options":[{"t":"두 평행선에 수직이 아닌 선분의 길이를 재었어요","correct":true,"mis_target":"M4-2-u2-X07"},{"t":"평행선을 잘못 찾았어요","mis":"M4-2-u2-X18"},{"t":"자의 눈금을 잘못 읽었어요","mis":"M4-2-u2-X18"},{"t":"평행선의 길이를 재었어요","mis":"M4-2-u2-X18"}],"explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","친구는 가로로 그은 선분을 재었는데 이 선분은 평행선과 수직이 아니에요.","수직인 선분을 그어 바르게 재면 2 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"seg":[[[7.5,15.0],[103.5,91.8]],[[52.5,15.0],[148.5,91.8]],[[43.5,43.8],[88.5,43.8]]],"lab":[[[66.0,34.8],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#8','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'sa','auto','「추론」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ은 평행하고, 삼각형 ㄱㄷㄹ은 이등변삼각형이에요. 이 도형에서 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C4","difficulty":4,"kind":"sa","stem":"「추론」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ은 평행하고, 삼각형 ㄱㄷㄹ은 이등변삼각형이에요. 이 도형에서 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각 ㄹ이 직각이라 변 ㄹㄷ이 평행선 사이의 거리예요.","삼각형 ㄱㄷㄹ은 이등변삼각형이라 변 ㄹㄷ의 길이는 변 ㄱㄹ과 같아요.","변 ㄱㄹ이 8 cm이니 8 cm예요 — 10 cm는 변 ㄴㄷ의 길이예요."],"asset":{"type":"geo","items":[{"w":120.0,"h":102.0,"pts":{"ㄱ":[36.0,18.0,"nw"],"ㄴ":[18.0,84.0,"sw"],"ㄷ":[102.0,84.0,"se"],"ㄹ":[102.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[69.0,6.7],"8 cm"],[[60.0,95.3],"10 cm"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#9','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'essay','teacher','「수학에 퐁당」 — 친구는 평행선 사이에 가로 선분을 긋고 3 cm라고 했어요. 잘못된 부분을 찾아 쓰고, 바르게 재는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C4","difficulty":4,"kind":"essay","stem":"「수학에 퐁당」 — 친구는 평행선 사이에 가로 선분을 긋고 3 cm라고 했어요. 잘못된 부분을 찾아 쓰고, 바르게 재는 방법을 써 보세요.","answer_guide":{"answer":"예: 친구가 그은 선분은 평행선과 수직이 아니어서 평행선 사이의 거리가 아닙니다. 평행선의 한 직선에서 다른 직선에 수직인 선분을 긋고 그 길이를 재야 하며, 바르게 재면 2 cm입니다.","scoring_points":["그은 선분이 수직이 아니라고 썼는가","한 직선에서 다른 직선에 수직인 선분을 긋는다고 썼는가","그 길이를 잰다(2 cm)고 썼는가"]},"explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","가로 선분은 평행선과 수직이 아니에요.","수직인 선분을 그어 재면 2 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"seg":[[[7.5,15.0],[103.5,91.8]],[[52.5,15.0],[148.5,91.8]],[[43.5,43.8],[88.5,43.8]]],"lab":[[[66.0,34.8],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L04_challenge#10','math',4,2,'u2','L04','tb_g4_2_math_u2_L04_challenge','lesson_challenge','M4-2-u2-C4',4,'essay','teacher','「생활 속 평행선」 — 도로의 폭을 재거나 횡단보도를 만들 때 평행선 사이의 거리를 왜 쓰는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C4","difficulty":4,"kind":"essay","stem":"「생활 속 평행선」 — 도로의 폭을 재거나 횡단보도를 만들 때 평행선 사이의 거리를 왜 쓰는지 써 보세요.","answer_guide":{"answer":"예: 도로의 두 경계선은 평행선이고, 평행선 사이의 거리는 어디서 재든 같습니다. 그래서 두 경계선에 수직인 선분의 길이로 도로의 폭을 재면 어느 곳이든 같은 폭을 알 수 있고, 횡단보도도 같은 길이로 만들 수 있습니다.","scoring_points":["도로의 경계선이 평행선이라고 썼는가","수직인 선분의 길이로 잰다고 썼는가","평행선 사이의 거리가 어디서나 같다는 점을 썼는가"]},"explanation":["도로의 두 경계선은 평행해요.","평행선 사이의 거리는 일정해요.","그래서 폭을 한 곳에서 재어도 어디서나 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#1','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'mc','auto','「개념 쏙」 — 평행한 변이 한 쌍이라도 있는 사각형을 무엇이라고 하나요?',ARRAY['M4-2-u2-X09','M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":1,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 평행한 변이 한 쌍이라도 있는 사각형을 무엇이라고 하나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X09"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X10"}],"explanation":["사각형을 평행한 변이 있는지에 따라 분류해요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","평행한 변이 두 쌍이어도 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#2','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'sa','auto','「개념 쏙」 — 쌍은 둘을 하나로 묶어 세는 단위예요. 「평행한 변이 한 쌍」이라는 것은 서로 평행한 변이 몇 개라는 뜻인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u2-C5","difficulty":1,"kind":"sa","stem":"「개념 쏙」 — 쌍은 둘을 하나로 묶어 세는 단위예요. 「평행한 변이 한 쌍」이라는 것은 서로 평행한 변이 몇 개라는 뜻인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["쌍은 둘을 하나로 묶어 세는 단위예요.","평행한 변 한 쌍 = 서로 평행한 변 2개예요.","2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#3','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'mc','auto','「생각 톡」 — 책장과 사다리에서 찾은 사각형을 평행한 변이 있는지에 따라 분류했어요. 평행한 변이 없는 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X10']::text[],true,'{"seq":3,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 책장과 사다리에서 찾은 사각형을 평행한 변이 있는지에 따라 분류했어요. 평행한 변이 없는 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"나","mis":"M4-2-u2-X04"},{"t":"가, 라, 마, 바","mis":"M4-2-u2-X18"},{"t":"나, 다, 마","mis":"M4-2-u2-X10"}],"explanation":["삼각자로 마주 보는 두 변이 평행한지 확인해요.","가·라·마·바에는 평행한 변이 있어요.","평행한 변이 없는 사각형은 나와 다예요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[15.0,22.5],[60.0,22.5],[90.0,75.0],[15.0,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[217.5,60.0],[255.0,22.5],[307.5,37.5],[285.0,82.5]],[[15.0,112.5],[90.0,112.5],[90.0,165.0],[15.0,165.0]],[[135.0,112.5],[202.5,112.5],[180.0,165.0],[112.5,165.0]],[[217.5,112.5],[307.5,112.5],[277.5,165.0],[247.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,104.2],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「생각 톡」 — 책장과 사다리에서 찾은 사각형이에요. 사다리꼴을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라, 마, 바","correct":true},{"t":"가, 바","mis":"M4-2-u2-X10"},{"t":"나, 다","mis":"M4-2-u2-X18"},{"t":"가, 라, 바","mis":"M4-2-u2-X09"}],"explanation":["평행한 변이 한 쌍이라도 있는지 봐요.","가·라·마·바에 평행한 변이 있어요 — 평행한 변이 두 쌍인 마도 사다리꼴이에요.","사다리 모양이 아니어도 평행한 변이 있으면 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[15.0,22.5],[60.0,22.5],[90.0,75.0],[15.0,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[217.5,60.0],[255.0,22.5],[307.5,37.5],[285.0,82.5]],[[15.0,112.5],[90.0,112.5],[90.0,165.0],[15.0,165.0]],[[135.0,112.5],[202.5,112.5],[180.0,165.0],[112.5,165.0]],[[217.5,112.5],[307.5,112.5],[277.5,165.0],[247.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,104.2],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#4','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',1,'mc','auto','「확인 문제」 — 사다리꼴 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?',ARRAY['M4-2-u2-X06','M4-2-u2-X23','M4-2-u2-X10']::text[],true,'{"seq":4,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 사다리꼴 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㄱㄹ과 변 ㄴㄷ","correct":true},{"t":"변 ㄱㄴ과 변 ㄹㄷ","mis":"M4-2-u2-X06"},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M4-2-u2-X23"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 두 변을 양쪽으로 늘였을 때 만나지 않는지 봐요.","변 ㄱㄹ과 변 ㄴㄷ은 늘여도 만나지 않아요.","변 ㄱㄴ과 변 ㄴㄷ은 수직이에요."],"asset":{"type":"geo","items":[{"w":111.0,"h":88.5,"grid":15,"pts":{"ㄱ":[18.0,18.0,"nw"],"ㄴ":[18.0,70.5,"sw"],"ㄷ":[93.0,70.5,"se"],"ㄹ":[63.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 사다리꼴 ㄱㄴㄷㄹ에서 서로 평행한 변은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄹㄷ","correct":true},{"t":"변 ㄱㄹ과 변 ㄴㄷ","mis":"M4-2-u2-X06"},{"t":"변 ㄴㄷ과 변 ㄷㄹ","mis":"M4-2-u2-X23"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X10"}],"explanation":["세로로 놓인 두 변을 늘여 봐요.","변 ㄱㄴ과 변 ㄹㄷ은 늘여도 만나지 않아요 — 평행해요.","평행한 변이 세로로 놓여도 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":96.0,"h":96.0,"grid":15,"pts":{"ㄱ":[18.0,25.5,"nw"],"ㄴ":[18.0,78.0,"sw"],"ㄷ":[78.0,63.0,"se"],"ㄹ":[78.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#5','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','「수학익힘」 — 사다리꼴을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X18']::text[],true,'{"seq":5,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 사다리꼴을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"나","mis":"M4-2-u2-X10"},{"t":"가, 라","mis":"M4-2-u2-X18"},{"t":"가, 나, 다","mis":"M4-2-u2-X10"}],"explanation":["평행한 변이 한 쌍이라도 있는 사각형을 찾아요.","나와 다에 평행한 변이 있어요 — 다는 평행한 변이 비스듬히 놓였어요.","가와 라에는 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[15.0,22.5],[82.5,37.5],[97.5,75.0],[7.5,67.5]],[[135.0,22.5],[180.0,22.5],[202.5,75.0],[112.5,75.0]],[[217.5,52.5],[277.5,22.5],[307.5,52.5],[262.5,75.0]],[[322.5,60.0],[360.0,22.5],[412.5,37.5],[390.0,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,14.2],"다"],[[367.5,14.2],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 사다리꼴을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다","correct":true},{"t":"가, 다","mis":"M4-2-u2-X09"},{"t":"라","mis":"M4-2-u2-X18"},{"t":"가, 나, 다, 라","mis":"M4-2-u2-X10"}],"explanation":["평행한 변이 한 쌍이라도 있는지 봐요.","가·다에 평행한 변이 있고, 나(직사각형)는 평행한 변이 두 쌍이에요.","나도 사다리꼴이에요 — 라에는 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,30.0],[202.5,30.0],[202.5,75.0],[112.5,75.0]],[[232.5,22.5],[270.0,22.5],[307.5,75.0],[232.5,75.0]],[[330.0,30.0],[390.0,22.5],[412.5,75.0],[345.0,67.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,21.8],"나"],[[270.0,14.2],"다"],[[371.2,14.2],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#6','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','「개념 톡」 — 사다리꼴 모양의 종이띠를 선을 따라 잘랐어요. 자른 도형 가운데 사다리꼴을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X09']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 사다리꼴 모양의 종이띠를 선을 따라 잘랐어요. 자른 도형 가운데 사다리꼴을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다, 라, 마 모두","correct":true},{"t":"나, 다, 라","mis":"M4-2-u2-X10"},{"t":"가, 마","mis":"M4-2-u2-X10"},{"t":"사다리꼴은 없어요","mis":"M4-2-u2-X09"}],"explanation":["종이띠의 위쪽 변과 아래쪽 변은 평행해요.","잘라도 각 도형에 평행한 변이 한 쌍씩 남아 있어요.","그래서 가~마가 모두 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":240,"h":82.5,"poly":[[[30.0,15.0],[52.5,15.0],[52.5,67.5],[7.5,67.5]],[[52.5,15.0],[75.0,15.0],[105.0,67.5],[52.5,67.5]],[[75.0,15.0],[142.5,15.0],[120.0,67.5],[105.0,67.5]],[[142.5,15.0],[165.0,15.0],[180.0,67.5],[120.0,67.5]],[[165.0,15.0],[195.0,15.0],[225.0,67.5],[180.0,67.5]]],"lab":[[[35.6,43.5],"가"],[[71.2,43.5],"나"],[[110.6,43.5],"다"],[[151.9,43.5],"라"],[[191.2,43.5],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#7','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','「수학익힘」 — 주어진 두 변과 한 점을 연결하여 사각형을 만들려고 해요. 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X10']::text[],true,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 주어진 두 변과 한 점을 연결하여 사각형을 만들려고 해요. 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠","mis":"M4-2-u2-X04"},{"t":"㉡, ㉢","mis":"M4-2-u2-X18"},{"t":"㉠, ㉡, ㉣","mis":"M4-2-u2-X10"}],"explanation":["점을 연결했을 때 평행한 변이 한 쌍이라도 생기는지 봐요.","㉠을 이으면 위쪽 변이 아래쪽 변과, ㉣을 이으면 오른쪽 변이 왼쪽 변과 평행해요.","㉡·㉢을 이으면 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"㉠":[67.5,15.0,"n"],"㉡":[90.0,33.0,"n"],"㉢":[45.0,12.0,"n"],"㉣":[105.0,45.0,"n"]},"seg":[[[15.0,15.0],[15.0,90.0]],[[15.0,90.0],[105.0,90.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 주어진 변과 연결하여 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M4-2-u2-X04"},{"t":"나, 다","mis":"M4-2-u2-X18"},{"t":"가, 나, 라","mis":"M4-2-u2-X10"}],"explanation":["평행한 변이 한 쌍이라도 생기는 점을 찾아요.","점 가와 점 라를 이으면 위쪽 변이 아래쪽 변과 평행해요.","점 나·다를 이으면 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"가":[52.5,30.0,"n"],"나":[75.0,12.0,"n"],"다":[82.5,51.0,"n"],"라":[112.5,30.0,"n"]},"seg":[[[15.0,30.0],[15.0,97.5]],[[15.0,97.5],[135.0,97.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#8','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'ox','auto','「헷갈려요」 — 평행한 변이 두 쌍인 사각형은 사다리꼴이 아니에요.',ARRAY['M4-2-u2-X09']::text[],false,'{"seq":8,"concept":"M4-2-u2-C5","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 평행한 변이 두 쌍인 사각형은 사다리꼴이 아니에요.","answer":"X","reason_options":[{"t":"평행한 변이 한 쌍이라도 있으면 사다리꼴이라서 두 쌍이어도 사다리꼴이어서","correct":true},{"t":"사다리꼴은 평행한 변이 한 쌍만 있어야 해서","mis":"M4-2-u2-X09"}],"mis":"M4-2-u2-X09","explanation":["사다리꼴은 평행한 변이 「한 쌍이라도」 있는 사각형이에요.","평행한 변이 두 쌍이면 「한 쌍이라도」 있는 것이에요.","그래서 사다리꼴이에요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]]],"lab":[[[52.5,14.2],"가"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#9','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','「수학에 퐁당」 — 사다리의 발판은 땅과 평행하게 만들어요. 사다리에서 이웃한 두 발판과 양쪽 다리로 둘러싸인 사각형이 사다리꼴인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X10']::text[],false,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「수학에 퐁당」 — 사다리의 발판은 땅과 평행하게 만들어요. 사다리에서 이웃한 두 발판과 양쪽 다리로 둘러싸인 사각형이 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"두 발판이 서로 평행해서","correct":true},{"t":"양쪽 다리의 길이가 같아서","mis":"M4-2-u2-X10"},{"t":"네 각이 모두 직각이라서","mis":"M4-2-u2-X10"},{"t":"위가 좁고 아래가 넓은 모양이라서","mis":"M4-2-u2-X10"}],"explanation":["사다리의 발판은 모두 땅과 평행해요.","이웃한 두 발판은 서로 평행해요 — 평행한 변이 한 쌍 있어요.","그래서 사다리꼴이에요 — 모양이 아니라 평행한 변으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_basic#10','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_basic','lesson_basic','M4-2-u2-C5',3,'mc','auto','「헷갈려요」 — 이름이 사다리꼴이라서 사다리 모양만 사다리꼴이라고 생각했어요. 바르게 고친 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X09']::text[],false,'{"seq":10,"concept":"M4-2-u2-C5","difficulty":3,"kind":"mc","stem":"「헷갈려요」 — 이름이 사다리꼴이라서 사다리 모양만 사다리꼴이라고 생각했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"모양과 상관없이 평행한 변이 한 쌍이라도 있으면 사다리꼴이에요","correct":true},{"t":"위가 좁고 아래가 넓어야 사다리꼴이에요","mis":"M4-2-u2-X10"},{"t":"평행한 변이 한 쌍만 있어야 사다리꼴이에요","mis":"M4-2-u2-X09"},{"t":"양쪽 변의 길이가 같아야 사다리꼴이에요","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴의 이름은 사다리 모양에서 왔지만, 뜻은 평행한 변으로 정해요.","평행한 변이 한 쌍이라도 있으면 사다리꼴이에요.","평행사변형·직사각형처럼 생긴 사각형도 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#1','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',2,'mc','auto','「재미있는 수학」 — 똑똑! 수학탐험대에서 친구가 만든 사다리꼴이 아닌 사각형을 한 꼭짓점만 움직여 사다리꼴로 바꾸려고 해요. 어떻게 움직여야 하나요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":1,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「재미있는 수학」 — 똑똑! 수학탐험대에서 친구가 만든 사다리꼴이 아닌 사각형을 한 꼭짓점만 움직여 사다리꼴로 바꾸려고 해요. 어떻게 움직여야 하나요?","options":[{"t":"평행한 변이 한 쌍이라도 생기도록 한 꼭짓점을 움직여요","correct":true},{"t":"네 변의 길이가 같아지도록 움직여요","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이 되도록 움직여요","mis":"M4-2-u2-X10"},{"t":"아무 쪽으로나 꼭짓점을 옮겨요","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","한 꼭짓점을 움직여 마주 보는 두 변이 평행하게 만들어요.","그다음 어느 변이 평행한지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#2','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',2,'ox','auto','「수학익힘」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 모두 사다리꼴이에요.',ARRAY['M4-2-u2-X10']::text[],false,'{"seq":2,"concept":"M4-2-u2-C5","difficulty":2,"kind":"ox","stem":"「수학익힘」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 모두 사다리꼴이에요.","answer":"O","reason_options":[{"t":"잘라 낸 도형마다 직사각형의 평행한 변이 한 쌍씩 남아 있어서","correct":true},{"t":"잘라 낸 도형의 크기가 서로 달라서 사다리꼴이 아닌 것도 있어서","mis":"M4-2-u2-X10"}],"mis":"M4-2-u2-X10","explanation":["직사각형의 위쪽 변과 아래쪽 변은 평행해요.","선을 따라 잘라도 도형마다 그 평행한 변이 남아요.","그래서 모두 사다리꼴이에요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#3','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'mc','auto','「생각해 봐요」 — 책장과 사다리에서 찾은 사각형 나에서 마주 보는 두 변에 ○표를 했어요. 두 변은 평행한가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X06','M4-2-u2-X05']::text[],false,'{"seq":3,"concept":"M4-2-u2-C5","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 책장과 사다리에서 찾은 사각형 나에서 마주 보는 두 변에 ○표를 했어요. 두 변은 평행한가요?","options":[{"t":"평행하지 않아요 — 기울어진 정도가 다르고 두 변 사이의 간격이 일정하지 않아요","correct":true},{"t":"평행해요 — 두 변이 마주 보고 있어요","mis":"M4-2-u2-X10"},{"t":"평행해요 — 두 변의 길이가 비슷해요","mis":"M4-2-u2-X06"},{"t":"알 수 없어요 — 그림 안에서 두 변이 만나지 않아요","mis":"M4-2-u2-X05"}],"explanation":["평행인지는 마주 보는지·길이가 비슷한지로 정하지 않아요.","두 변을 늘였을 때 만나는지, 간격이 일정한지 봐요.","나의 마주 보는 두 변은 기울어진 정도가 달라 늘이면 만나요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[15.0,22.5],[60.0,22.5],[90.0,75.0],[15.0,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[217.5,60.0],[255.0,22.5],[307.5,37.5],[285.0,82.5]],[[15.0,112.5],[90.0,112.5],[90.0,165.0],[15.0,165.0]],[[135.0,112.5],[202.5,112.5],[180.0,165.0],[112.5,165.0]],[[217.5,112.5],[307.5,112.5],[277.5,165.0],[247.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,104.2],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#4','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'error','auto','「헷갈려요」 — 사다리꼴에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X18']::text[],false,'{"seq":4,"concept":"M4-2-u2-C5","difficulty":3,"kind":"error","stem":"「헷갈려요」 — 사다리꼴에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"은비 — 「평행한 변이 두 쌍이면 사다리꼴이 아니야.」","correct":true,"mis_target":"M4-2-u2-X09"},{"t":"건우 — 「평행한 변이 한 쌍이라도 있으면 사다리꼴이야.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「직사각형도 평행한 변이 있으니 사다리꼴이야.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「사다리꼴은 모양과 방향이 여러 가지야.」","mis":"M4-2-u2-X18"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","평행한 변이 두 쌍이어도 사다리꼴이에요.","은비의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#5','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'sa','auto','「생각 톡」 — 책장과 사다리에서 찾은 사각형 가운데 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C5","difficulty":3,"kind":"sa","stem":"「생각 톡」 — 책장과 사다리에서 찾은 사각형 가운데 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행한 변이 한 쌍이라도 있는 사각형을 세요.","가, 라, 마, 바예요.","4개예요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[15.0,22.5],[60.0,22.5],[90.0,75.0],[15.0,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[217.5,60.0],[255.0,22.5],[307.5,37.5],[285.0,82.5]],[[15.0,112.5],[90.0,112.5],[90.0,165.0],[15.0,165.0]],[[135.0,112.5],[202.5,112.5],[180.0,165.0],[112.5,165.0]],[[217.5,112.5],[307.5,112.5],[277.5,165.0],[247.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,104.2],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 책장의 책을 꺼내기 위해 이용하는 사다리와 책장에서 찾은 사각형이에요. 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["평행한 변이 한 쌍이라도 있는지 봐요.","가, 나, 마예요.","3개예요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[112.5,52.5],[172.5,22.5],[202.5,52.5],[157.5,75.0]],[[225.0,22.5],[292.5,37.5],[307.5,75.0],[217.5,67.5]],[[7.5,150.0],[45.0,112.5],[97.5,127.5],[75.0,172.5]],[[112.5,112.5],[202.5,112.5],[172.5,165.0],[142.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#6','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'mc','auto','「수학익힘」 — 모눈종이에 주어진 선분을 이용하여 사다리꼴을 그리려고 해요. 먼저 생각해야 할 것은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 모눈종이에 주어진 선분을 이용하여 사다리꼴을 그리려고 해요. 먼저 생각해야 할 것은 무엇인가요?","options":[{"t":"서로 평행한 변이 한 쌍이라도 생기게 하는 것","correct":true},{"t":"네 변의 길이를 모두 같게 하는 것","mis":"M4-2-u2-X14"},{"t":"네 각을 모두 직각으로 하는 것","mis":"M4-2-u2-X10"},{"t":"위가 좁고 아래가 넓게 하는 것","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴의 뜻을 떠올려요.","모눈을 따라 평행한 두 변을 먼저 정해요.","그러면 모양과 변의 길이가 달라도 모두 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#7','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',3,'mc','auto','「생각해 봐요」 — 사다리꼴 모양의 종이띠를 잘라 낸 도형이 모두 사다리꼴인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 사다리꼴 모양의 종이띠를 잘라 낸 도형이 모두 사다리꼴인 까닭은 무엇인가요?","options":[{"t":"잘라도 처음 종이띠의 평행한 두 변이 각 도형에 한 쌍씩 남아 있어서","correct":true},{"t":"잘라 낸 도형의 네 변의 길이가 같아서","mis":"M4-2-u2-X14"},{"t":"잘라 낸 도형의 크기가 모두 같아서","mis":"M4-2-u2-X10"},{"t":"잘라 낸 도형이 모두 사다리 모양이라서","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴 모양 종이띠의 위쪽 변과 아래쪽 변은 평행해요.","어디를 잘라도 도형마다 그 두 변의 일부가 남아요.","평행한 변이 한 쌍이라도 있으니 모두 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":240,"h":82.5,"poly":[[[30.0,15.0],[52.5,15.0],[52.5,67.5],[7.5,67.5]],[[52.5,15.0],[75.0,15.0],[105.0,67.5],[52.5,67.5]],[[75.0,15.0],[142.5,15.0],[120.0,67.5],[105.0,67.5]],[[142.5,15.0],[165.0,15.0],[180.0,67.5],[120.0,67.5]],[[165.0,15.0],[195.0,15.0],[225.0,67.5],[180.0,67.5]]],"lab":[[[35.6,43.5],"가"],[[71.2,43.5],"나"],[[110.6,43.5],"다"],[[151.9,43.5],"라"],[[191.2,43.5],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#8','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'sa','auto','「문제 해결」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ은 서로 평행해요. 이 도형에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C5","difficulty":4,"kind":"sa","stem":"「문제 해결」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ은 서로 평행해요. 이 도형에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["작은 사각형 한 칸짜리, 두 칸을 합친 것, 전체를 차례로 세어요.","작은 사다리꼴 2개 + 두 칸을 합친 사다리꼴 2개 + 전체 1개예요.","모두 5개예요 — 세모 모양 칸은 사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":195,"h":97.5,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄹ":[105.0,15.0,"ne"],"ㄴ":[15.0,82.5,"sw"],"ㄷ":[180.0,82.5,"se"]},"seg":[["ㄱ","ㄹ"],["ㄴ","ㄷ"],["ㄱ","ㄴ"],["ㄹ","ㄷ"],["ㄴ",[67.5,15.0]],[[90.0,15.0],[90.0,82.5]]],"right":[[[90.0,15.0],[90.0,82.5],[180.0,82.5]],["ㄱ","ㄴ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#9','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'essay','teacher','「서술형」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 사다리꼴이에요. 그 이유를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"「서술형」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 사다리꼴이에요. 그 이유를 써 보세요.","answer_guide":{"answer":"예: 직사각형 모양의 종이띠를 자른 것이므로 잘라 낸 도형들은 모두 평행한 변이 한 쌍이라도 있기 때문입니다.","scoring_points":["직사각형의 평행한 변을 썼는가","잘라 낸 도형에 평행한 변이 남는다고 썼는가","평행한 변이 한 쌍이라도 있으면 사다리꼴이라고 썼는가"]},"explanation":["직사각형의 마주 보는 변은 평행해요.","잘라도 평행한 변이 남아요.","그래서 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L05_challenge#10','math',4,2,'u2','L05','tb_g4_2_math_u2_L05_challenge','lesson_challenge','M4-2-u2-C5',4,'essay','teacher','「재미있는 수학」 — 친구가 만든 사다리꼴이 아닌 사각형을 한 꼭짓점만 움직여 사다리꼴로 바꾸었어요. 어떻게 움직였는지와 어느 변이 평행한지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"「재미있는 수학」 — 친구가 만든 사다리꼴이 아닌 사각형을 한 꼭짓점만 움직여 사다리꼴로 바꾸었어요. 어떻게 움직였는지와 어느 변이 평행한지 써 보세요.","answer_guide":{"answer":"예: 위쪽 오른쪽 꼭짓점을 위쪽 왼쪽 꼭짓점과 같은 높이로 옮겨 위쪽 변이 아래쪽 변과 평행하게 만들었습니다. 위쪽 변과 아래쪽 변이 평행하므로 사다리꼴입니다.","scoring_points":["한 꼭짓점만 움직였다고 썼는가","평행해진 두 변을 밝혔는가","평행한 변이 한 쌍이라도 있어 사다리꼴이라고 썼는가"]},"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있어야 해요.","한 꼭짓점을 옮겨 두 변을 평행하게 해요.","어느 변이 평행한지 말할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#1','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',1,'mc','auto','「개념 쏙」 — 마주 보는 두 쌍의 변이 서로 평행한 사각형을 무엇이라고 하나요?',ARRAY['M4-2-u2-X14','M4-2-u2-X11','M4-2-u2-X02']::text[],true,'{"seq":1,"concept":"M4-2-u2-C6","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 마주 보는 두 쌍의 변이 서로 평행한 사각형을 무엇이라고 하나요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"직사각형","mis":"M4-2-u2-X11"},{"t":"평행선","mis":"M4-2-u2-X02"}],"explanation":["사각형을 평행한 변이 몇 쌍인지에 따라 분류해요.","마주 보는 두 쌍의 변이 서로 평행한 사각형을 평행사변형이라고 해요.","평행선은 사각형이 아니라 평행한 두 직선이에요."],"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 평행사변형은 어떤 사각형인가요?","options":[{"t":"마주 보는 두 쌍의 변이 서로 평행한 사각형","correct":true},{"t":"평행한 변이 한 쌍만 있는 사각형","mis":"M4-2-u2-X09"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M4-2-u2-X14"},{"t":"비스듬히 기울어진 사각형","mis":"M4-2-u2-X11"}],"explanation":["평행사변형은 평행한 변으로 정해요.","마주 보는 두 쌍의 변이 모두 평행해야 해요.","기울어졌는지는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#2','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',1,'mc','auto','「생각 톡」 — 벽과 난간에서 찾은 사각형을 평행한 변이 몇 쌍인지에 따라 분류했어요. 평행한 변이 두 쌍인 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X11','M4-2-u2-X09','M4-2-u2-X18']::text[],true,'{"seq":2,"concept":"M4-2-u2-C6","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 벽과 난간에서 찾은 사각형을 평행한 변이 몇 쌍인지에 따라 분류했어요. 평행한 변이 두 쌍인 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마, 바","correct":true},{"t":"다, 마","mis":"M4-2-u2-X11"},{"t":"가, 다, 마, 바","mis":"M4-2-u2-X09"},{"t":"나, 라","mis":"M4-2-u2-X18"}],"explanation":["삼각자로 마주 보는 두 변이 평행한지 두 번 확인해요.","다·마·바는 마주 보는 두 쌍의 변이 모두 평행해요 — 직사각형 바도 그래요.","가는 한 쌍, 나·라는 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[240.0,22.5],[307.5,22.5],[285.0,75.0],[217.5,75.0]],[[7.5,150.0],[45.0,112.5],[97.5,127.5],[75.0,172.5]],[[112.5,150.0],[157.5,112.5],[202.5,127.5],[157.5,165.0]],[[217.5,120.0],[307.5,120.0],[307.5,165.0],[217.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「생각 톡」 — 벽과 난간에서 찾은 사각형이에요. 평행한 변이 없는 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M4-2-u2-X04"},{"t":"가, 나, 라","mis":"M4-2-u2-X09"},{"t":"다, 마, 바","mis":"M4-2-u2-X18"}],"explanation":["마주 보는 두 변을 늘였을 때 만나는지 봐요.","나와 라는 어느 두 변도 평행하지 않아요.","가에는 평행한 변이 한 쌍 있어요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[240.0,22.5],[307.5,22.5],[285.0,75.0],[217.5,75.0]],[[7.5,150.0],[45.0,112.5],[97.5,127.5],[75.0,172.5]],[[112.5,150.0],[157.5,112.5],[202.5,127.5],[157.5,165.0]],[[217.5,120.0],[307.5,120.0],[307.5,165.0],[217.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#3','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',1,'mc','auto','「수학익힘」 — 평행사변형의 성질이에요. 평행사변형은 마주 보는 두 변의 길이가 서로 어떤가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X26','M4-2-u2-X25']::text[],true,'{"seq":3,"concept":"M4-2-u2-C7","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 평행사변형의 성질이에요. 평행사변형은 마주 보는 두 변의 길이가 서로 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"달라요","mis":"M4-2-u2-X14"},{"t":"이웃한 두 변과 같아요","mis":"M4-2-u2-X26"},{"t":"재어 보기 전에는 알 수 없어요","mis":"M4-2-u2-X25"}],"explanation":["평행사변형의 변의 길이를 자로 재어 봐요.","마주 보는 두 변의 길이가 같아요.","모든 평행사변형에서 찾을 수 있는 성질이에요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 평행사변형의 성질이에요. 평행사변형은 마주 보는 두 각의 크기가 서로 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"달라요","mis":"M4-2-u2-X12"},{"t":"합이 90°예요","mis":"M4-2-u2-X12"},{"t":"재어 보기 전에는 알 수 없어요","mis":"M4-2-u2-X25"}],"explanation":["각도기로 네 각을 재어 봐요.","마주 보는 두 각의 크기가 같아요.","이웃한 두 각은 크기의 합이 180°예요."]},{"stem":"「수학익힘」 — 평행사변형의 성질이에요. 평행사변형에서 이웃한 두 각의 크기의 합은 몇 도인가요?","options":[{"t":"180°","correct":true},{"t":"90°","mis":"M4-2-u2-X12"},{"t":"360°","mis":"M4-2-u2-X12"},{"t":"이웃한 두 각의 크기가 같아요","mis":"M4-2-u2-X12"}],"explanation":["나란히 놓여 있는 두 각을 이웃한 각이라고 해요.","각도기로 재어 더해 보면 180°예요.","네 각의 합 360°와 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#4','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',1,'sa','auto','「문제 척」 — 평행사변형에서 두 변의 길이가 6 cm, 8 cm예요. 위쪽 변(8 cm인 변과 마주 보는 변)의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"「문제 척」 — 평행사변형에서 두 변의 길이가 6 cm, 8 cm예요. 위쪽 변(8 cm인 변과 마주 보는 변)의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","위쪽 변은 8 cm인 아래쪽 변과 마주 봐요.","8 cm예요 — 왼쪽 변은 6 cm예요."],"asset":{"type":"geo","items":[{"w":133.8,"h":84.9,"poly":[[[40.8,18.0],[115.8,18.0],[93.0,66.9],[18.0,66.9]]],"lab":[[[78.3,6.8],"? cm"],[[12.3,34.5],"? cm"],[[121.5,50.4],"6 cm"],[[55.5,78.2],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 평행사변형에서 두 변의 길이가 8 cm, 5 cm예요. 5 cm인 변과 마주 보는 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마주 보는 두 변의 길이는 같아요.","5 cm인 변과 마주 보는 변을 찾아요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":133.5,"h":75.0,"poly":[[[40.5,18.0],[115.5,18.0],[93.0,57.0],[18.0,57.0]]],"lab":[[[13.2,28.2],"5 cm"],[[78.0,6.8],"8 cm"],[[120.3,46.7],"? cm"],[[55.5,68.2],"? cm"]]}],"tag":false}},{"stem":"「수학익힘」 — 평행사변형에서 두 변의 길이가 4 cm, 9 cm예요. 9 cm인 변과 마주 보는 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["마주 보는 두 변의 길이는 같아요.","9 cm인 변과 마주 보는 변을 찾아요.","9 cm예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":95.2,"poly":[[[39.5,18.0],[90.5,18.0],[69.0,77.2],[18.0,77.2]]],"lab":[[[65.0,6.8],"4 cm"],[[97.8,54.1],"9 cm"],[[10.8,41.1],"? cm"],[[43.5,88.5],"? cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#5','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'sa','auto','「문제 척」 — 평행사변형의 두 각이 70°, 110°예요. 70°인 각과 마주 보는 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"「문제 척」 — 평행사변형의 두 각이 70°, 110°예요. 70°인 각과 마주 보는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["평행사변형은 마주 보는 두 각의 크기가 같아요.","70°인 각과 마주 보는 각을 찾아요.","70°예요 — 110°인 각과 마주 보는 각은 110°예요."],"asset":{"type":"geo","items":[{"w":129.5,"h":86.7,"poly":[[[36.5,18.0],[111.5,18.0],[93.0,68.7],[18.0,68.7]]],"lab":[[[45.1,30.3],"?"],[[98.2,27.3],"70°"],[[84.4,56.5],"110°"],[[31.3,59.4],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 평행사변형의 두 각이 55°, 125°예요. 125°인 각과 마주 보는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["마주 보는 두 각의 크기는 같아요.","125°인 각과 마주 보는 각을 찾아요.","125°예요."],"asset":{"type":"geo","items":[{"w":136.8,"h":72.9,"poly":[[[43.8,18.0],[118.8,18.0],[93.0,54.9],[18.0,54.9]]],"lab":[[[100.9,27.3],"55°"],[[86.1,41.6],"125°"],[[50.7,31.3],"?"],[[35.9,45.6],"?"]]}],"tag":false}},{"stem":"「확인 문제」 — 평행사변형의 두 각이 110°, 70°예요. 110°인 각과 마주 보는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["마주 보는 두 각의 크기는 같아요.","110°인 각과 마주 보는 각을 찾아요.","110°예요."],"asset":{"type":"geo","items":[{"w":127.4,"h":81.1,"poly":[[[34.4,18.0],[109.4,18.0],[93.0,63.1],[18.0,63.1]]],"lab":[[[43.0,30.3],"110°"],[[96.1,27.3],"70°"],[[31.3,53.8],"?"],[[84.4,50.8],"?"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#6','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',2,'mc','auto','「수학익힘」 — 평행사변형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X11','M4-2-u2-X14','M4-2-u2-X09']::text[],true,'{"seq":6,"concept":"M4-2-u2-C6","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 평행사변형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M4-2-u2-X11"},{"t":"가, 나, 라","mis":"M4-2-u2-X14"},{"t":"다","mis":"M4-2-u2-X09"}],"explanation":["마주 보는 두 쌍의 변이 모두 평행한지 확인해요.","가와 라(직사각형)가 평행사변형이에요.","나는 평행한 변이 없고, 다는 평행한 변이 한 쌍뿐이에요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]],[[157.5,18.0],[187.5,42.0],[157.5,84.0],[127.5,42.0]],[[225.0,22.5],[300.0,22.5],[300.0,75.0],[247.5,75.0]],[[330.0,22.5],[405.0,22.5],[405.0,75.0],[330.0,75.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,9.7],"나"],[[262.5,14.2],"다"],[[367.5,14.2],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 평행사변형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"라","mis":"M4-2-u2-X11"},{"t":"가, 다","mis":"M4-2-u2-X09"},{"t":"가, 나, 다, 라","mis":"M4-2-u2-X09"}],"explanation":["마주 보는 두 쌍의 변이 모두 평행해야 해요.","나(직사각형)와 라가 평행사변형이에요.","가·다는 평행한 변이 한 쌍뿐이에요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[22.5,22.5],[60.0,22.5],[97.5,75.0],[22.5,75.0]],[[135.0,18.0],[180.0,18.0],[180.0,84.0],[135.0,84.0]],[[217.5,22.5],[307.5,22.5],[277.5,75.0],[247.5,75.0]],[[322.5,22.5],[382.5,22.5],[412.5,75.0],[352.5,75.0]]],"lab":[[[60.0,14.2],"가"],[[157.5,9.7],"나"],[[262.5,14.2],"다"],[[367.5,14.2],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#7','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'sa','auto','「문제 척」 — 나란히 놓여 있는 각을 이웃한 각이라고 해요. 평행사변형의 한 각이 70°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"「문제 척」 — 나란히 놓여 있는 각을 이웃한 각이라고 해요. 평행사변형의 한 각이 70°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["평행사변형에서 이웃한 두 각의 크기의 합은 180°예요.","180 − 70 = 110이에요.","110°예요."],"asset":{"type":"geo","items":[{"w":129.5,"h":86.7,"poly":[[[36.5,18.0],[111.5,18.0],[93.0,68.7],[18.0,68.7]]],"lab":[[[45.1,30.3],"?"],[[98.2,27.3],"70°"],[[84.4,56.5],"110°"],[[31.3,59.4],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 평행사변형의 한 각이 55°일 때, 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["이웃한 두 각의 크기의 합은 180°예요.","180 − 55 = 125예요.","125°예요."],"asset":{"type":"geo","items":[{"w":136.8,"h":72.9,"poly":[[[43.8,18.0],[118.8,18.0],[93.0,54.9],[18.0,54.9]]],"lab":[[[100.9,27.3],"55°"],[[86.1,41.6],"125°"],[[50.7,31.3],"?"],[[35.9,45.6],"?"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#8','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C7',2,'sa','auto','「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형은 평행사변형이에요. 이 평행사변형의 한 각이 130°일 때, 이 각과 이웃한 각 ㉠은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형은 평행사변형이에요. 이 평행사변형의 한 각이 130°일 때, 이 각과 이웃한 각 ㉠은 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["두 직사각형의 마주 보는 변은 평행해서 겹친 사각형은 평행사변형이에요.","평행사변형에서 이웃한 두 각의 크기의 합은 180°예요.","180 − 130 = 50 — ㉠은 50°예요."],"asset":{"type":"geo","items":[{"w":143.8,"h":75.1,"poly":[[[50.8,18.0],[125.8,18.0],[93.0,57.1],[18.0,57.1]]],"lab":[[[57.1,31.6],"130°"],[[37.9,47.8],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#9','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',2,'mc','auto','「문제 척」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 완성하려고 해요. 어느 점을 이어야 하나요?',ARRAY['M4-2-u2-X10']::text[],false,'{"seq":9,"concept":"M4-2-u2-C6","difficulty":2,"kind":"mc","stem":"「문제 척」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ에 한 점을 더 이어 평행사변형을 완성하려고 해요. 어느 점을 이어야 하나요?","options":[{"t":"점 가","correct":true},{"t":"점 나","mis":"M4-2-u2-X10"},{"t":"점 다","mis":"M4-2-u2-X10"},{"t":"점 라","mis":"M4-2-u2-X10"}],"explanation":["마주 보는 두 쌍의 변이 서로 평행해야 해요.","점 가를 이으면 위쪽 변이 변 ㄱㄴ과, 왼쪽 변이 변 ㄴㄷ과 평행해요.","모눈 칸을 세어 기울어진 정도가 같은지 확인해요."],"asset":{"type":"geo","items":[{"w":150,"h":97.5,"grid":15,"pts":{"ㄱ":[15.0,75.0,"sw"],"ㄴ":[90.0,75.0,"s"],"ㄷ":[120.0,15.0,"ne"],"가":[45.0,15.0,"n"],"나":[15.0,15.0,"n"],"다":[75.0,15.0,"n"],"라":[45.0,45.0,"n"]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_basic#10','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_basic','lesson_basic','M4-2-u2-C6',3,'ox','auto','「헷갈려요」 — 직사각형은 비스듬한 변이 없으니 평행사변형이라고 할 수 없어요.',ARRAY['M4-2-u2-X11']::text[],false,'{"seq":10,"concept":"M4-2-u2-C6","difficulty":3,"kind":"ox","stem":"「헷갈려요」 — 직사각형은 비스듬한 변이 없으니 평행사변형이라고 할 수 없어요.","answer":"X","reason_options":[{"t":"직사각형도 마주 보는 두 쌍의 변이 서로 평행해서","correct":true},{"t":"평행사변형은 반드시 비스듬한 두 변이 있어야 해서","mis":"M4-2-u2-X11"}],"mis":"M4-2-u2-X11","explanation":["평행사변형인지는 기울어졌는지가 아니라 평행한 변으로 정해요.","직사각형도 마주 보는 두 쌍의 변이 평행해요.","그래서 평행사변형이라고 할 수 있어요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[7.5,30.0],[97.5,30.0],[97.5,75.0],[7.5,75.0]]],"lab":[[[52.5,21.8],"가"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#1','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',2,'match','auto','평행사변형의 성질에 맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"M4-2-u2-C7","difficulty":2,"kind":"match","stem":"평행사변형의 성질에 맞게 이으세요.","pairs":[{"l":"마주 보는 두 변","r":"길이가 같아요"},{"l":"마주 보는 두 각","r":"크기가 같아요"},{"l":"이웃한 두 각","r":"크기의 합이 180°예요"}],"mis":"M4-2-u2-X12","explanation":["자와 각도기로 평행사변형을 재어 성질을 확인해요.","마주 보는 변·각은 같아요.","이웃한 두 각은 크기의 합이 180°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#2','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',2,'mc','auto','평행사변형의 성질이 아닌 것은 어느 것인가요?',ARRAY['M4-2-u2-X18']::text[],false,'{"seq":2,"concept":"M4-2-u2-C7","difficulty":2,"kind":"mc","stem":"평행사변형의 성질이 아닌 것은 어느 것인가요?","options":[{"t":"네 변의 길이가 모두 같아요","correct":true},{"t":"마주 보는 두 변의 길이가 같아요","mis":"M4-2-u2-X18"},{"t":"마주 보는 두 각의 크기가 같아요","mis":"M4-2-u2-X18"},{"t":"이웃한 두 각의 크기의 합이 180°예요","mis":"M4-2-u2-X18"}],"explanation":["모든 평행사변형에서 늘 찾을 수 있는 것만 성질이에요.","평행사변형은 이웃한 두 변의 길이가 다를 수 있어요.","「네 변의 길이가 모두 같다」는 성질이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#3','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'sa','auto','「문제 해결」 — 평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 40 cm예요. 변 ㄱㄹ의 길이가 15 cm일 때, 변 ㄱㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"「문제 해결」 — 평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 40 cm예요. 변 ㄱㄹ의 길이가 15 cm일 때, 변 ㄱㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마주 보는 두 변의 길이가 같으니 변 ㄴㄷ도 15 cm예요.","40 − 15 − 15 = 10이 남은 두 변의 길이의 합이에요.","10을 둘로 똑같이 나누면 5 — 변 ㄱㄴ은 5 cm예요."],"asset":{"type":"geo","items":[{"w":127.5,"h":64.6,"pts":{"ㄱ":[34.5,18.0,"nw"],"ㄹ":[109.5,18.0,"e"],"ㄷ":[93.0,46.6,"se"],"ㄴ":[18.0,46.6,"w"]},"poly":[["ㄱ","ㄹ","ㄷ","ㄴ"]],"lab":[[[72.0,6.7],"15 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#4','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'sa','auto','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄷㅁ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄷㅁ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["선분 ㄱㄴ과 선분 ㄹㅁ, 선분 ㄱㄹ과 선분 ㄴㅁ이 각각 평행해서 사각형 ㄱㄴㅁㄹ은 평행사변형이에요.","선분 ㄴㅁ은 마주 보는 변 ㄱㄹ과 같은 5 cm예요.","12 − 5 = 7 — 선분 ㄷㅁ은 7 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#5','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'error','auto','「개념 톡」 — 평행사변형을 보고 성질을 추측했어요. 잘못 추측한 사람은 누구인가요?',ARRAY['M4-2-u2-X26','M4-2-u2-X18']::text[],false,'{"seq":5,"concept":"M4-2-u2-C7","difficulty":3,"kind":"error","stem":"「개념 톡」 — 평행사변형을 보고 성질을 추측했어요. 잘못 추측한 사람은 누구인가요?","options":[{"t":"도윤 — 「이웃한 두 변의 길이가 같을 것 같아.」","correct":true,"mis_target":"M4-2-u2-X26"},{"t":"채원 — 「마주 보는 두 변의 길이가 같을 것 같아.」","mis":"M4-2-u2-X18"},{"t":"서준 — 「이웃한 두 각의 크기의 합이 일정할 것 같아.」","mis":"M4-2-u2-X18"},{"t":"은비 — 「마주 보는 두 각의 크기가 같을 것 같아.」","mis":"M4-2-u2-X18"}],"explanation":["추측이 맞는지 자와 각도기로 확인해요.","평행사변형은 마주 보는 두 변의 길이가 같아요 — 이웃한 두 변은 다를 수 있어요.","도윤이의 추측이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#6','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C6',3,'mc','auto','「더 해 봐요」 — 칠교판 조각 2개로 사각형을 만들었어요. 만든 사각형이 평행사변형인지 확인하려면 무엇을 보아야 하나요?',ARRAY['M4-2-u2-X11','M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":6,"concept":"M4-2-u2-C6","difficulty":3,"kind":"mc","stem":"「더 해 봐요」 — 칠교판 조각 2개로 사각형을 만들었어요. 만든 사각형이 평행사변형인지 확인하려면 무엇을 보아야 하나요?","options":[{"t":"마주 보는 두 쌍의 변이 서로 평행한지","correct":true},{"t":"비스듬히 기울어졌는지","mis":"M4-2-u2-X11"},{"t":"네 변의 길이가 모두 같은지","mis":"M4-2-u2-X14"},{"t":"조각을 몇 개 썼는지","mis":"M4-2-u2-X10"}],"explanation":["평행사변형의 뜻을 떠올려요.","삼각자로 마주 보는 두 쌍의 변이 모두 평행한지 확인해요.","칠교판 2조각, 3조각, 4조각으로도 평행사변형을 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#7','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',3,'mc','auto','「생각해 봐요」 — 평행사변형의 두 변이 6 cm, 8 cm일 때 □ 안의 답이 8과 6인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X26','M4-2-u2-X14','M4-2-u2-X12']::text[],false,'{"seq":7,"concept":"M4-2-u2-C7","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 평행사변형의 두 변이 6 cm, 8 cm일 때 □ 안의 답이 8과 6인 까닭은 무엇인가요?","options":[{"t":"평행사변형은 마주 보는 두 변의 길이가 같기 때문이에요","correct":true},{"t":"평행사변형은 이웃한 두 변의 길이가 같기 때문이에요","mis":"M4-2-u2-X26"},{"t":"평행사변형은 네 변의 길이가 모두 같기 때문이에요","mis":"M4-2-u2-X14"},{"t":"평행사변형은 이웃한 두 각의 크기의 합이 180°이기 때문이에요","mis":"M4-2-u2-X12"}],"explanation":["위쪽 변은 아래쪽 8 cm 변과, 왼쪽 변은 오른쪽 6 cm 변과 마주 봐요.","평행사변형은 마주 보는 두 변의 길이가 같아요.","그래서 8과 6이에요."],"asset":{"type":"geo","items":[{"w":133.8,"h":84.9,"poly":[[[40.8,18.0],[115.8,18.0],[93.0,66.9],[18.0,66.9]]],"lab":[[[78.3,6.8],"? cm"],[[12.3,34.5],"? cm"],[[121.5,50.4],"6 cm"],[[55.5,78.2],"8 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#8','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',4,'sa','auto','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄹㅁ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄹㅁ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["사각형 ㄱㄴㅁㄹ은 마주 보는 두 쌍의 변이 평행한 평행사변형이에요.","선분 ㄹㅁ은 마주 보는 변 ㄱㄴ과 길이가 같아요.","변 ㄱㄴ이 8 cm이니 선분 ㄹㅁ도 8 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#9','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C7',4,'essay','teacher','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었을 때 선분 ㄷㅁ의 길이를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C7","difficulty":4,"kind":"essay","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었을 때 선분 ㄷㅁ의 길이를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 선분 ㄱㄴ과 선분 ㄹㅁ은 평행하고 선분 ㄱㄹ과 선분 ㄴㅁ도 평행하므로 사각형 ㄱㄴㅁㄹ은 평행사변형입니다. 평행사변형은 마주 보는 두 변의 길이가 같으므로 선분 ㄴㅁ은 5 cm이고, 선분 ㄷㅁ은 12 − 5 = 7(cm)입니다.","scoring_points":["사각형 ㄱㄴㅁㄹ이 평행사변형이라고 밝혔는가","마주 보는 변의 길이가 같아 선분 ㄴㅁ이 5 cm라고 썼는가","12 − 5 = 7(cm)을 구했는가"]},"explanation":["먼저 평행사변형을 찾아요.","마주 보는 두 변의 길이가 같아요.","12 − 5 = 7(cm)이에요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L06_challenge#10','math',4,2,'u2','L06','tb_g4_2_math_u2_L06_challenge','lesson_challenge','M4-2-u2-C6',4,'essay','teacher','「헷갈려요」 — 친구가 「직사각형은 비스듬한 변이 없으니 평행사변형이 아니야.」라고 했어요. 친구의 생각을 바르게 고쳐 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C6","difficulty":4,"kind":"essay","stem":"「헷갈려요」 — 친구가 「직사각형은 비스듬한 변이 없으니 평행사변형이 아니야.」라고 했어요. 친구의 생각을 바르게 고쳐 써 보세요.","answer_guide":{"answer":"예: 평행사변형은 마주 보는 두 쌍의 변이 서로 평행한 사각형입니다. 직사각형도 마주 보는 두 쌍의 변이 서로 평행하므로 평행사변형이라고 할 수 있습니다. 비스듬한지는 상관없습니다.","scoring_points":["평행사변형의 뜻을 썼는가","직사각형의 마주 보는 두 쌍의 변이 평행하다고 썼는가","기울어진 정도는 상관없다고 썼는가"]},"explanation":["평행사변형은 평행한 변으로 정해요.","직사각형의 마주 보는 두 쌍의 변도 평행해요.","그래서 평행사변형이라고 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#1','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'mc','auto','「개념 쏙」 — 네 변의 길이가 모두 같은 사각형을 무엇이라고 하나요?',ARRAY['M4-2-u2-X14','M4-2-u2-X16','M4-2-u2-X10']::text[],true,'{"seq":1,"concept":"M4-2-u2-C8","difficulty":1,"kind":"mc","stem":"「개념 쏙」 — 네 변의 길이가 모두 같은 사각형을 무엇이라고 하나요?","options":[{"t":"마름모","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X16"},{"t":"사다리꼴","mis":"M4-2-u2-X10"}],"explanation":["사각형을 변의 길이에 따라 분류해요.","네 변의 길이가 모두 같은 사각형을 마름모라고 해요.","정사각형은 네 각까지 모두 직각이어야 해요."],"variant_rule":{"alt":[{"stem":"「개념 쏙」 — 마름모는 어떤 사각형인가요?","options":[{"t":"네 변의 길이가 모두 같은 사각형","correct":true},{"t":"마주 보는 두 변의 길이만 같은 사각형","mis":"M4-2-u2-X14"},{"t":"다이아몬드처럼 세워 놓인 사각형","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각인 사각형","mis":"M4-2-u2-X16"}],"explanation":["마름모는 변의 길이로 정해요.","네 변의 길이가 모두 같으면 마름모예요.","놓인 방향은 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#2','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'mc','auto','「생각 톡」 — 학교 정문의 시설물과 안내판에서 찾은 사각형을 변의 길이에 따라 분류했어요. 네 변의 길이가 모두 같은 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X18']::text[],false,'{"seq":2,"concept":"M4-2-u2-C8","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 학교 정문의 시설물과 안내판에서 찾은 사각형을 변의 길이에 따라 분류했어요. 네 변의 길이가 모두 같은 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 바","correct":true},{"t":"가","mis":"M4-2-u2-X17"},{"t":"가, 나, 바","mis":"M4-2-u2-X14"},{"t":"나, 다, 라, 마","mis":"M4-2-u2-X18"}],"explanation":["자로 네 변의 길이를 재어 봐요.","가와 바(정사각형)는 네 변의 길이가 모두 같아요.","나·다·라·마는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[7.5,52.5],[52.5,30.0],[97.5,52.5],[52.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[240.0,19.5],[277.5,19.5],[285.0,81.0],[247.5,81.0]],[[7.5,142.5],[82.5,123.0],[97.5,142.5],[82.5,162.0]],[[135.0,112.5],[180.0,112.5],[202.5,165.0],[112.5,165.0]],[[240.0,120.0],[285.0,120.0],[285.0,165.0],[240.0,165.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,11.2],"다"],[[52.5,114.7],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#3','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'mc','auto','「수학익힘」 — 마름모의 성질이에요. 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 서로 어떻게 만나나요?',ARRAY['M4-2-u2-X23','M4-2-u2-X15']::text[],true,'{"seq":3,"concept":"M4-2-u2-C8","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 마름모의 성질이에요. 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분은 서로 어떻게 만나나요?","options":[{"t":"수직으로 만나요","correct":true},{"t":"평행해요","mis":"M4-2-u2-X23"},{"t":"비스듬히 만나요","mis":"M4-2-u2-X15"},{"t":"만나지 않아요","mis":"M4-2-u2-X15"}],"explanation":["마름모 모양 종이를 마주 보는 꼭짓점끼리 만나도록 접었다 펴 봐요.","접힌 두 선분이 만나는 곳에 삼각자를 대면 직각이에요.","두 선분은 서로 수직으로 만나요."],"variant_rule":{"alt":[{"stem":"「수학익힘」 — 마름모의 성질이에요. 마름모에서 마주 보는 두 쌍의 변은 서로 어떤가요?","options":[{"t":"평행해요","correct":true},{"t":"수직이에요","mis":"M4-2-u2-X23"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X25"},{"t":"한 쌍만 평행해요","mis":"M4-2-u2-X09"}],"explanation":["삼각자를 사용하면 평행한 변이 있는지 확인할 수 있어요.","마름모는 마주 보는 두 쌍의 변이 서로 평행해요.","삼각자를 비뚤게 대면 잘못 볼 수 있어요."]},{"stem":"「수학익힘」 — 마름모의 성질이에요. 마름모에서 마주 보는 두 각의 크기는 서로 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"달라요","mis":"M4-2-u2-X25"},{"t":"합이 90°예요","mis":"M4-2-u2-X12"},{"t":"모두 직각이에요","mis":"M4-2-u2-X16"}],"explanation":["각도기로 네 각을 재어 봐요.","마주 보는 두 각의 크기가 같아요.","네 각이 모두 직각인 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#4','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',1,'sa','auto','「문제 척」 — 마름모의 한 변이 5 cm예요. 마름모의 다른 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「문제 척」 — 마름모의 한 변이 5 cm예요. 마름모의 다른 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","한 변이 5 cm이면 나머지 변도 모두 5 cm예요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":117.3,"h":73.9,"poly":[[[49.8,18.0],[99.3,18.0],[67.5,55.9],[18.0,55.9]]],"lab":[[[42.8,67.2],"5 cm"],[[74.6,6.7],"? cm"],[[37.9,46.6],"50°"],[[61.2,42.3],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 마름모의 한 변이 9 cm예요. 마름모의 다른 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["네 변의 길이가 모두 같아요.","한 변이 9 cm예요.","9 cm예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":86.7,"poly":[[[36.5,18.0],[90.5,18.0],[72.0,68.7],[18.0,68.7]]],"lab":[[[63.5,6.7],"9 cm"],[[99.2,49.9],"? cm"],[[45.1,30.3],"110°"],[[77.2,27.3],"?"]]}],"tag":false}},{"stem":"「확인 문제」 — 마름모의 한 변이 4 cm예요. 마름모의 다른 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["네 변의 길이가 모두 같아요.","한 변이 4 cm예요.","4 cm예요."],"asset":{"type":"geo","items":[{"w":88.8,"h":80.3,"poly":[[[25.8,18.0],[70.8,18.0],[63.0,62.3],[18.0,62.3]]],"lab":[[[48.3,6.7],"4 cm"],[[40.5,73.6],"? cm"],[[29.5,52.7],"80°"],[[59.3,27.6],"?"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#5','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','「문제 척」 — 마름모의 한 각이 50°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"「문제 척」 — 마름모의 한 각이 50°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["마름모도 이웃한 두 각의 크기의 합이 180°예요.","180 − 50 = 130이에요.","130°예요 — 50°인 각과 마주 보는 각은 50°예요."],"asset":{"type":"geo","items":[{"w":117.3,"h":73.9,"poly":[[[49.8,18.0],[99.3,18.0],[67.5,55.9],[18.0,55.9]]],"lab":[[[42.8,67.2],"5 cm"],[[74.6,6.7],"? cm"],[[37.9,46.6],"50°"],[[61.2,42.3],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 마름모의 한 각이 110°예요. 이 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["이웃한 두 각의 크기의 합은 180°예요.","180 − 110 = 70이에요.","70°예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":86.7,"poly":[[[36.5,18.0],[90.5,18.0],[72.0,68.7],[18.0,68.7]]],"lab":[[[63.5,6.7],"9 cm"],[[99.2,49.9],"? cm"],[[45.1,30.3],"110°"],[[77.2,27.3],"?"]]}],"tag":false}},{"stem":"「확인 문제」 — 마름모의 한 각이 80°예요. 이 각과 마주 보는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["마름모는 마주 보는 두 각의 크기가 같아요.","80°인 각과 마주 보는 각을 찾아요.","80°예요."],"asset":{"type":"geo","items":[{"w":88.8,"h":80.3,"poly":[[[25.8,18.0],[70.8,18.0],[63.0,62.3],[18.0,62.3]]],"lab":[[[48.3,6.7],"4 cm"],[[40.5,73.6],"? cm"],[[29.5,52.7],"80°"],[[59.3,27.6],"?"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#6','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','「문제 척」 — 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분을 그었어요. 한 선분의 반은 4 cm, 다른 선분의 반은 6 cm예요. 4 cm의 나머지 반(아래쪽 ?)은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"「문제 척」 — 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분을 그었어요. 한 선분의 반은 4 cm, 다른 선분의 반은 6 cm예요. 4 cm의 나머지 반(아래쪽 ?)은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["마름모의 마주 보는 꼭짓점끼리 이은 두 선분은 서로를 반으로 나눠요.","위쪽 반이 4 cm이면 아래쪽 반도 4 cm예요.","4 cm예요 — 오른쪽 반은 6 cm예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":108.0,"poly":[[[72.0,18.0],[126.0,54.0],[72.0,90.0],[18.0,54.0]]],"seg":[[[72.0,18.0],[72.0,90.0]],[[126.0,54.0],[18.0,54.0]]],"lab":[[[84.7,36.0],"4 cm"],[[45.0,45.0],"6 cm"],[[59.2,72.0],"?"],[[99.0,65.2],"?"]],"right":[[[72.0,18.0],[72.0,54.0],[126.0,54.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 마름모에서 마주 보는 꼭짓점끼리 이은 선분의 위쪽 반이 3 cm예요. 아래쪽 반(?)은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 선분은 서로를 반으로 나눠요.","위쪽 반과 아래쪽 반의 길이가 같아요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":108.0,"poly":[[[69.0,18.0],[120.0,54.0],[69.0,90.0],[18.0,54.0]]],"seg":[[[69.0,18.0],[69.0,90.0]],[[120.0,54.0],[18.0,54.0]]],"lab":[[[81.7,36.0],"3 cm"],[[56.2,72.0],"?"]],"right":[[[69.0,18.0],[69.0,54.0],[120.0,54.0]]]}],"tag":false}},{"stem":"「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 6 cm, 8 cm예요. 6 cm의 나머지 반(아래쪽 ?)은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 선분은 서로를 반으로 나눠요.","위쪽 반이 6 cm이면 아래쪽 반도 6 cm예요.","6 cm예요 — 10 cm는 변의 길이예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":108.0,"poly":[[[66.0,18.0],[114.0,54.0],[66.0,90.0],[18.0,54.0]]],"lab":[[[31.5,22.0],"10 cm"],[[78.8,36.0],"6 cm"],[[42.0,45.0],"8 cm"],[[53.3,72.0],"?"],[[90.0,65.2],"?"]],"seg":[[[66.0,18.0],[66.0,90.0]],[[114.0,54.0],[18.0,54.0]]],"right":[[[66.0,18.0],[66.0,54.0],[114.0,54.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#7','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'sa','auto','「문제 척」 — 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"「문제 척」 — 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나요.","수직으로 만나는 두 선분이 이루는 각은 직각이에요.","90°예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":108.0,"poly":[[[72.0,18.0],[126.0,54.0],[72.0,90.0],[18.0,54.0]]],"seg":[[[72.0,18.0],[72.0,90.0]],[[126.0,54.0],[18.0,54.0]]],"lab":[[[84.7,36.0],"4 cm"],[[45.0,45.0],"6 cm"],[[59.2,72.0],"?"],[[99.0,65.2],"?"]],"right":[[[72.0,18.0],[72.0,54.0],[126.0,54.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["두 선분은 서로 수직으로 만나요.","수직이면 직각이에요.","90°예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":108.0,"poly":[[[69.0,18.0],[120.0,54.0],[69.0,90.0],[18.0,54.0]]],"seg":[[[69.0,18.0],[69.0,90.0]],[[120.0,54.0],[18.0,54.0]]],"lab":[[[81.7,36.0],"3 cm"],[[56.2,72.0],"?"]],"right":[[[69.0,18.0],[69.0,54.0],[120.0,54.0]]]}],"tag":false}},{"stem":"「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["두 선분은 서로 수직으로 만나요.","변의 길이와 상관없이 늘 수직이에요.","90°예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":108.0,"poly":[[[66.0,18.0],[114.0,54.0],[66.0,90.0],[18.0,54.0]]],"lab":[[[31.5,22.0],"10 cm"],[[78.8,36.0],"6 cm"],[[42.0,45.0],"8 cm"],[[53.3,72.0],"?"],[[90.0,65.2],"?"]],"seg":[[[66.0,18.0],[66.0,90.0]],[[114.0,54.0],[18.0,54.0]]],"right":[[[66.0,18.0],[66.0,54.0],[114.0,54.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#8','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'mc','auto','「수학익힘」 — 마름모를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X18']::text[],true,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나","correct":true},{"t":"나","mis":"M4-2-u2-X17"},{"t":"가, 나, 라","mis":"M4-2-u2-X14"},{"t":"다, 라","mis":"M4-2-u2-X18"}],"explanation":["네 변의 길이가 모두 같은지 모눈 칸으로 확인해요.","가(세워 놓은 정사각형)와 나는 네 변의 길이가 모두 같아요.","다·라는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[52.5,18.0],[85.5,51.0],[52.5,84.0],[19.5,51.0]],[[112.5,52.5],[157.5,30.0],[202.5,52.5],[157.5,75.0]],[[240.0,18.0],[285.0,18.0],[285.0,84.0],[240.0,84.0]],[[345.0,19.5],[382.5,19.5],[390.0,81.0],[352.5,81.0]]],"lab":[[[52.5,9.7],"가"],[[157.5,21.8],"나"],[[262.5,9.7],"다"],[[367.5,11.2],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나","correct":true},{"t":"가","mis":"M4-2-u2-X17"},{"t":"가, 나, 라","mis":"M4-2-u2-X14"},{"t":"다, 라","mis":"M4-2-u2-X18"}],"explanation":["네 변의 길이가 모두 같은 사각형을 찾아요.","가와 나(정사각형)가 마름모예요.","정사각형도 네 변의 길이가 모두 같아요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[52.5,18.0],[75.0,51.0],[52.5,84.0],[30.0,51.0]],[[127.5,22.5],[187.5,22.5],[187.5,82.5],[127.5,82.5]],[[240.0,18.0],[285.0,18.0],[285.0,84.0],[240.0,84.0]],[[345.0,22.5],[412.5,22.5],[390.0,75.0],[322.5,75.0]]],"lab":[[[52.5,9.7],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,14.2],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#9','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',2,'mc','auto','「서술형」 — 마름모가 아닌 도형과 그 이유를 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14']::text[],false,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「서술형」 — 마름모가 아닌 도형과 그 이유를 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가 — 길이가 다른 변이 있어요","correct":true},{"t":"나 — 네 각이 모두 직각이에요","mis":"M4-2-u2-X17"},{"t":"가 — 비스듬히 기울어졌어요","mis":"M4-2-u2-X14"},{"t":"나 — 다이아몬드처럼 세워 놓이지 않았어요","mis":"M4-2-u2-X14"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","가는 길이가 다른 변이 있어서 마름모가 아니에요.","나는 네 변의 길이가 모두 같아 마름모예요 — 직각이어도 돼요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]],[[135.0,30.0],[180.0,30.0],[180.0,75.0],[135.0,75.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,21.8],"나"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_basic#10','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_basic','lesson_basic','M4-2-u2-C8',3,'ox','auto','「개념 톡」 — 마름모 모양 종이를 마주 보는 꼭짓점끼리 만나도록 접었다 펴면, 접힌 두 선분은 서로를 반으로 나눠요.',ARRAY['M4-2-u2-X15']::text[],false,'{"seq":10,"concept":"M4-2-u2-C8","difficulty":3,"kind":"ox","stem":"「개념 톡」 — 마름모 모양 종이를 마주 보는 꼭짓점끼리 만나도록 접었다 펴면, 접힌 두 선분은 서로를 반으로 나눠요.","answer":"O","reason_options":[{"t":"마주 보는 꼭짓점끼리 겹치게 접어서 접힌 선이 다른 선분을 똑같이 둘로 나누어서","correct":true},{"t":"두 선분의 길이가 같아서 반으로 나누지 않아서","mis":"M4-2-u2-X15"}],"mis":"M4-2-u2-X15","explanation":["마주 보는 꼭짓점끼리 만나도록 접으면 양쪽이 꼭 겹쳐요.","그래서 접힌 선이 다른 선분을 똑같이 둘로 나눠요.","두 선분은 서로를 반으로 나눠요(O)."],"asset":{"type":"geo","items":[{"w":144.0,"h":108.0,"poly":[[[72.0,18.0],[126.0,54.0],[72.0,90.0],[18.0,54.0]]],"seg":[[[72.0,18.0],[72.0,90.0]],[[126.0,54.0],[18.0,54.0]]],"lab":[[[84.7,36.0],"4 cm"],[[45.0,45.0],"6 cm"],[[59.2,72.0],"?"],[[99.0,65.2],"?"]],"right":[[[72.0,18.0],[72.0,54.0],[126.0,54.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#1','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',2,'sa','auto','「추론」 — 마름모의 네 변의 길이의 합이 48 cm일 때 마름모의 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"「추론」 — 마름모의 네 변의 길이의 합이 48 cm일 때 마름모의 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","네 변의 길이의 합을 4로 나눠요.","48 ÷ 4 = 12 — 12 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#2','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',2,'mc','auto','「수학에 퐁당」 — 「마름모」라는 이름은 어디에서 왔나요?',ARRAY['M4-2-u2-X14','M4-2-u2-X16','M4-2-u2-X10']::text[],false,'{"seq":2,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「수학에 퐁당」 — 「마름모」라는 이름은 어디에서 왔나요?","options":[{"t":"연못에서 자라는 「마름」의 네모난 잎 모양을 보고 만든 이름이에요","correct":true},{"t":"보석 다이아몬드의 모양에서 온 이름이에요","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이라서 붙인 이름이에요","mis":"M4-2-u2-X16"},{"t":"사다리 모양이라서 붙인 이름이에요","mis":"M4-2-u2-X10"}],"explanation":["마름모는 한자 능형(菱形)을 한글로 번역한 것이에요.","「마름」은 연못에서 자라는 한해살이풀이고, 「모」는 네모나게 만든 것을 뜻해요.","마름의 잎 모양을 보고 만든 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#3','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'error','auto','「친구의 설명」 — 마름모의 성질을 추측하고 확인했어요. 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X25','M4-2-u2-X18']::text[],false,'{"seq":3,"concept":"M4-2-u2-C8","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 마름모의 성질을 추측하고 확인했어요. 잘못 말한 사람은 누구인가요?","options":[{"t":"도윤 — 「삼각자를 대어 보니 마름모는 평행한 변이 없어.」","correct":true,"mis_target":"M4-2-u2-X25"},{"t":"서윤 — 「마주 보는 두 각의 크기가 같아.」","mis":"M4-2-u2-X18"},{"t":"건우 — 「이웃한 두 각의 크기의 합은 180°야.」","mis":"M4-2-u2-X18"},{"t":"채원 — 「마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나.」","mis":"M4-2-u2-X18"}],"explanation":["마름모는 마주 보는 두 쌍의 변이 서로 평행해요.","삼각자를 비뚤게 대면 평행한 변을 찾지 못할 수 있어요.","도윤이의 말이 잘못이에요 — 도구를 바르게 대고 다시 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#4','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'mc','auto','「더 해 봐요」 — 색종이를 반으로 두 번 접은 뒤 가위로 비스듬히 잘라 펼쳤더니 마름모가 되었어요. 마름모인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X16','M4-2-u2-X28']::text[],false,'{"seq":4,"concept":"M4-2-u2-C8","difficulty":3,"kind":"mc","stem":"「더 해 봐요」 — 색종이를 반으로 두 번 접은 뒤 가위로 비스듬히 잘라 펼쳤더니 마름모가 되었어요. 마름모인 까닭은 무엇인가요?","options":[{"t":"접힌 종이가 겹쳐 네 변이 모두 같은 자리에서 잘렸으므로 길이가 같아서","correct":true},{"t":"색종이가 정사각형이라서","mis":"M4-2-u2-X14"},{"t":"두 번 접어서 네 각이 모두 직각이 되어서","mis":"M4-2-u2-X16"},{"t":"펼친 모양이 다이아몬드처럼 보여서","mis":"M4-2-u2-X28"}],"explanation":["두 번 접으면 네 겹이 겹쳐요.","한 번 자른 선이 펼치면 네 변이 돼요 — 네 변의 길이가 모두 같아요.","그래서 마름모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#5','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'sa','auto','「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 각각 6 cm, 8 cm예요. 8 cm를 반으로 하는 선분 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 각각 6 cm, 8 cm예요. 8 cm를 반으로 하는 선분 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["두 선분은 서로를 반으로 나눠요.","반이 8 cm이니 전체는 8 + 8이에요.","16 cm예요 — 변의 길이 10 cm와 헷갈리지 않아요."],"asset":{"type":"geo","items":[{"w":132.0,"h":108.0,"poly":[[[66.0,18.0],[114.0,54.0],[66.0,90.0],[18.0,54.0]]],"lab":[[[31.5,22.0],"10 cm"],[[78.8,36.0],"6 cm"],[[42.0,45.0],"8 cm"],[[53.3,72.0],"?"],[[90.0,65.2],"?"]],"seg":[[[66.0,18.0],[66.0,90.0]],[[114.0,54.0],[18.0,54.0]]],"right":[[[66.0,18.0],[66.0,54.0],[114.0,54.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#6','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'mc','auto','「수학익힘」 — 마름모 ㄱㄴㄷㄹ에서 서로 평행한 변을 모두 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X23','M4-2-u2-X25']::text[],false,'{"seq":6,"concept":"M4-2-u2-C8","difficulty":3,"kind":"mc","stem":"「수학익힘」 — 마름모 ㄱㄴㄷㄹ에서 서로 평행한 변을 모두 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ과 변 ㄹㄷ, 변 ㄴㄷ과 변 ㄱㄹ","correct":true},{"t":"변 ㄱㄴ과 변 ㄹㄷ","mis":"M4-2-u2-X09"},{"t":"변 ㄱㄴ과 변 ㄴㄷ, 변 ㄷㄹ과 변 ㄹㄱ","mis":"M4-2-u2-X23"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X25"}],"explanation":["마름모는 마주 보는 두 쌍의 변이 서로 평행해요.","변 ㄱㄴ과 변 ㄹㄷ, 변 ㄴㄷ과 변 ㄱㄹ이 마주 봐요.","두 쌍 모두 평행해요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[54.0,18.0,"nw"],"ㄹ":[114.0,18.0,"ne"],"ㄷ":[78.0,66.0,"se"],"ㄴ":[18.0,66.0,"sw"]},"poly":[["ㄱ","ㄹ","ㄷ","ㄴ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#7','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',3,'ox','auto','「헷갈려요」 — 다이아몬드처럼 세워 놓인 모양만 마름모예요.',ARRAY['M4-2-u2-X14']::text[],false,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":3,"kind":"ox","stem":"「헷갈려요」 — 다이아몬드처럼 세워 놓인 모양만 마름모예요.","answer":"X","reason_options":[{"t":"놓인 방향과 상관없이 네 변의 길이가 모두 같으면 마름모라서","correct":true},{"t":"마름모는 위아래로 뾰족하게 세워 놓여야 해서","mis":"M4-2-u2-X14"}],"mis":"M4-2-u2-X14","explanation":["마름모는 변의 길이로 정해요.","눕혀 놓아도, 비스듬히 놓아도 네 변의 길이가 같으면 마름모예요.","이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[15.0,67.5],[52.5,67.5],[75.0,37.5],[37.5,37.5]]],"lab":[[[45.0,29.2],"가"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#8','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'sa','auto','「추론」 — 한 변의 길이가 12 cm인 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":4,"kind":"sa","stem":"「추론」 — 한 변의 길이가 12 cm인 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","12 cm가 4개예요.","12 × 4 = 48 — 48 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#9','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'essay','teacher','「개념 톡」 — 마름모의 성질을 「평행」「각」「수직」「반」이라는 말을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":4,"kind":"essay","stem":"「개념 톡」 — 마름모의 성질을 「평행」「각」「수직」「반」이라는 말을 넣어 설명해 보세요.","answer_guide":{"answer":"예: 마름모는 마주 보는 두 쌍의 변이 서로 평행합니다. 마주 보는 두 각의 크기가 같고, 이웃한 두 각의 크기의 합은 180°입니다. 마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나고 서로를 반으로 나눕니다.","scoring_points":["마주 보는 두 쌍의 변이 평행하다고 썼는가","각에 대한 성질(마주 보는 각이 같다)을 썼는가","두 선분이 수직으로 만나고 서로를 반으로 나눈다고 썼는가"]},"explanation":["마름모를 접고, 재어 보며 성질을 확인해요.","변·각·마주 보는 꼭짓점을 이은 선분의 성질을 모두 써요.","모든 마름모에서 늘 맞는 것만 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L07_challenge#10','math',4,2,'u2','L07','tb_g4_2_math_u2_L07_challenge','lesson_challenge','M4-2-u2-C8',4,'essay','teacher','「생각해 봐요」 — 마주 보는 꼭짓점끼리 이은 두 선분의 반이 4 cm, 6 cm인 마름모에서 □ 안의 답이 90, 4, 6인 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C8","difficulty":4,"kind":"essay","stem":"「생각해 봐요」 — 마주 보는 꼭짓점끼리 이은 두 선분의 반이 4 cm, 6 cm인 마름모에서 □ 안의 답이 90, 4, 6인 까닭을 써 보세요.","answer_guide":{"answer":"예: 마름모의 마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나므로 90°입니다. 또 두 선분은 서로를 반으로 나누므로 나머지 반의 길이도 각각 4 cm, 6 cm입니다.","scoring_points":["두 선분이 수직으로 만나 90°라고 썼는가","두 선분이 서로를 반으로 나눈다고 썼는가","4와 6을 바르게 설명했는가"]},"explanation":["두 선분은 수직으로 만나요 — 90°.","두 선분은 서로를 반으로 나눠요.","그래서 4 cm, 6 cm예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":108.0,"poly":[[[72.0,18.0],[126.0,54.0],[72.0,90.0],[18.0,54.0]]],"seg":[[[72.0,18.0],[72.0,90.0]],[[126.0,54.0],[18.0,54.0]]],"lab":[[[84.7,36.0],"4 cm"],[[45.0,45.0],"6 cm"],[[59.2,72.0],"?"],[[99.0,65.2],"?"]],"right":[[[72.0,18.0],[72.0,54.0],[126.0,54.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#1','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'mc','auto','「생각 톡」 — 보도블록에서 찾은 직사각형과 정사각형의 성질을 추측하고 확인했어요. 직사각형과 정사각형은 마주 보는 두 쌍의 변이 서로 어떤가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X05','M4-2-u2-X09']::text[],false,'{"seq":1,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 보도블록에서 찾은 직사각형과 정사각형의 성질을 추측하고 확인했어요. 직사각형과 정사각형은 마주 보는 두 쌍의 변이 서로 어떤가요?","options":[{"t":"평행해요","correct":true},{"t":"수직이에요","mis":"M4-2-u2-X23"},{"t":"늘이면 만나요","mis":"M4-2-u2-X05"},{"t":"평행한 변이 한 쌍뿐이에요","mis":"M4-2-u2-X09"}],"explanation":["삼각자로 마주 보는 두 변이 평행한지 확인해요.","직사각형과 정사각형은 마주 보는 두 쌍의 변이 서로 평행해요.","이웃한 두 변은 서로 수직이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#2','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','「수학익힘」 — 직사각형의 두 변이 8 cm, 3 cm예요. 3 cm인 변과 마주 보는 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"「수학익힘」 — 직사각형의 두 변이 8 cm, 3 cm예요. 3 cm인 변과 마주 보는 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","3 cm인 변과 마주 보는 변을 찾아요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":115.5,"h":66.0,"poly":[[[18.0,18.0],[97.5,18.0],[97.5,48.0],[18.0,48.0]]],"right":[[[18.0,48.0],[18.0,18.0],[97.5,18.0]],[[18.0,18.0],[97.5,18.0],[97.5,48.0]],[[97.5,18.0],[97.5,48.0],[18.0,48.0]],[[97.5,48.0],[18.0,48.0],[18.0,18.0]]],"lab":[[[57.8,6.7],"8 cm"],[[-1.7,33.0],"3 cm"],[[117.2,33.0],"? cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 직사각형의 두 변이 7 cm, 5 cm예요. 5 cm인 변과 마주 보는 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","5 cm인 변과 마주 보는 변을 찾아요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":109.5,"h":88.5,"poly":[[[18.0,18.0],[91.5,18.0],[91.5,70.5],[18.0,70.5]]],"right":[[[18.0,70.5],[18.0,18.0],[91.5,18.0]],[[18.0,18.0],[91.5,18.0],[91.5,70.5]],[[91.5,18.0],[91.5,70.5],[18.0,70.5]],[[91.5,70.5],[18.0,70.5],[18.0,18.0]]],"lab":[[[54.8,6.7],"7 cm"],[[-1.7,44.2],"5 cm"],[[111.2,44.2],"? cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#3','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'sa','auto','「수학익힘」 — 한 변이 4 cm인 정사각형이에요. 정사각형의 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C9","difficulty":1,"kind":"sa","stem":"「수학익힘」 — 한 변이 4 cm인 정사각형이에요. 정사각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["정사각형은 네 각이 모두 직각이에요.","직각은 90°예요.","90°예요."],"asset":{"type":"geo","items":[{"w":81.0,"h":81.0,"poly":[[[18.0,18.0],[63.0,18.0],[63.0,63.0],[18.0,63.0]]],"right":[[[18.0,63.0],[18.0,18.0],[63.0,18.0]],[[18.0,18.0],[63.0,18.0],[63.0,63.0]],[[63.0,18.0],[63.0,63.0],[18.0,63.0]],[[63.0,63.0],[18.0,63.0],[18.0,18.0]]],"lab":[[[40.5,6.7],"4 cm"],[[-1.7,40.5],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 한 변이 6 cm인 정사각형이에요. 이웃한 다른 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","한 변이 6 cm이니 나머지 변도 6 cm예요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":84.0,"h":84.0,"poly":[[[18.0,18.0],[66.0,18.0],[66.0,66.0],[18.0,66.0]]],"right":[[[18.0,66.0],[18.0,18.0],[66.0,18.0]],[[18.0,18.0],[66.0,18.0],[66.0,66.0]],[[66.0,18.0],[66.0,66.0],[18.0,66.0]],[[66.0,66.0],[18.0,66.0],[18.0,18.0]]],"lab":[[[42.0,6.7],"6 cm"],[[85.7,42.0],"? cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#4','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',1,'mc','auto','「개념 톡」 — 횡단보도 앞 보도블록에서 찾은 사각형이에요. 직사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X27','M4-2-u2-X18']::text[],true,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「개념 톡」 — 횡단보도 앞 보도블록에서 찾은 사각형이에요. 직사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"다","mis":"M4-2-u2-X17"},{"t":"나, 다, 마","mis":"M4-2-u2-X27"},{"t":"가, 나, 라","mis":"M4-2-u2-X18"}],"explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","다와 마(정사각형)의 네 각이 모두 직각이에요.","나는 평행한 변이 두 쌍이지만 직각이 없어 직사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 직사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다","correct":true},{"t":"다","mis":"M4-2-u2-X17"},{"t":"가, 다","mis":"M4-2-u2-X10"},{"t":"라","mis":"M4-2-u2-X18"}],"explanation":["네 각이 모두 직각인지 확인해요.","가, 나(세워 놓은 정사각형), 다가 직사각형이에요.","정사각형도 직사각형이라고 부를 수 있어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[30.0,30.0],[75.0,30.0],[75.0,75.0],[30.0,75.0]],[[157.5,18.0],[190.5,51.0],[157.5,84.0],[124.5,51.0]],[[240.0,18.0],[285.0,18.0],[285.0,84.0],[240.0,84.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,9.7],"나"],[[262.5,9.7],"다"],[[367.5,21.8],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#5','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'mc','auto','「개념 톡」 — 보도블록에서 찾은 사각형이에요. 마름모를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X26']::text[],true,'{"seq":5,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 보도블록에서 찾은 사각형이에요. 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"라, 마","correct":true},{"t":"라","mis":"M4-2-u2-X17"},{"t":"나, 라, 마","mis":"M4-2-u2-X14"},{"t":"다, 마","mis":"M4-2-u2-X26"}],"explanation":["마름모는 네 변의 길이가 모두 같은 사각형이에요.","라와 마(정사각형)의 네 변의 길이가 모두 같아요.","한 사각형이 여러 이름으로 불릴 수 있어요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학익힘」 — 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 라","correct":true},{"t":"라","mis":"M4-2-u2-X17"},{"t":"나, 라","mis":"M4-2-u2-X10"},{"t":"다","mis":"M4-2-u2-X18"}],"explanation":["네 변의 길이가 모두 같은지 확인해요.","가, 나(정사각형)와 라가 마름모예요.","정사각형도 마름모라고 부를 수 있어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[30.0,30.0],[75.0,30.0],[75.0,75.0],[30.0,75.0]],[[157.5,18.0],[190.5,51.0],[157.5,84.0],[124.5,51.0]],[[240.0,18.0],[285.0,18.0],[285.0,84.0],[240.0,84.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,9.7],"나"],[[262.5,9.7],"다"],[[367.5,21.8],"라"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#6','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'mc','auto','「문제 척」 — 「보기」 ㉠ 평행한 변이 있다. ㉡ 네 변의 길이가 모두 같다. ㉢ 네 각이 모두 직각이다. 마름모에 대한 설명으로 알맞은 것을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X16','M4-2-u2-X18']::text[],true,'{"seq":6,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「문제 척」 — 「보기」 ㉠ 평행한 변이 있다. ㉡ 네 변의 길이가 모두 같다. ㉢ 네 각이 모두 직각이다. 마름모에 대한 설명으로 알맞은 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉡","mis":"M4-2-u2-X09"},{"t":"㉠, ㉡, ㉢","mis":"M4-2-u2-X16"},{"t":"㉢","mis":"M4-2-u2-X18"}],"explanation":["마름모는 마주 보는 두 쌍의 변이 평행하고 네 변의 길이가 모두 같아요.","하지만 네 각이 모두 직각이 아닐 수도 있어요.","그래서 ㉠, ㉡이에요."],"variant_rule":{"alt":[{"stem":"「문제 척」 — 「보기」 ㉠ 평행한 변이 있다. ㉡ 네 변의 길이가 모두 같다. ㉢ 네 각이 모두 직각이다. 평행사변형에 대한 설명으로 알맞은 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉠, ㉡","mis":"M4-2-u2-X14"},{"t":"㉠, ㉢","mis":"M4-2-u2-X27"},{"t":"㉡, ㉢","mis":"M4-2-u2-X18"}],"explanation":["평행사변형은 평행한 변이 있어요.","길이가 다른 변이 있거나 직각이 없을 수도 있어요.","그래서 ㉠뿐이에요."]},{"stem":"「문제 척」 — 「보기」 ㉠ 평행한 변이 있다. ㉡ 네 변의 길이가 모두 같다. ㉢ 네 각이 모두 직각이다. 직사각형에 대한 설명으로 알맞은 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉢","mis":"M4-2-u2-X09"},{"t":"㉠, ㉡, ㉢","mis":"M4-2-u2-X16"},{"t":"㉡","mis":"M4-2-u2-X18"}],"explanation":["직사각형은 평행한 변이 있고 네 각이 모두 직각이에요.","길이가 다른 변이 있을 수도 있어요.","그래서 ㉠, ㉢이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#7','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'mc','auto','「수학익힘」 — 정사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X26','M4-2-u2-X14']::text[],true,'{"seq":7,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 정사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나","correct":true},{"t":"가","mis":"M4-2-u2-X10"},{"t":"가, 나, 다","mis":"M4-2-u2-X26"},{"t":"라","mis":"M4-2-u2-X14"}],"explanation":["정사각형은 네 변의 길이가 모두 같고 네 각이 모두 직각이에요.","가와 나(비스듬히 세워 놓은 정사각형)가 정사각형이에요.","놓인 방향은 상관없어요."],"asset":{"type":"geo","items":[{"w":420,"h":90,"grid":15,"poly":[[[30.0,30.0],[75.0,30.0],[75.0,75.0],[30.0,75.0]],[[157.5,18.0],[190.5,51.0],[157.5,84.0],[124.5,51.0]],[[240.0,18.0],[285.0,18.0],[285.0,84.0],[240.0,84.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,9.7],"나"],[[262.5,9.7],"다"],[[367.5,21.8],"라"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 정사각형을 고른 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"라","mis":"M4-2-u2-X16"},{"t":"마","mis":"M4-2-u2-X16"},{"t":"다, 라, 마","mis":"M4-2-u2-X17"}],"explanation":["네 변의 길이가 모두 같고 네 각이 모두 직각인지 확인해요.","다(세워 놓은 정사각형)만 두 조건을 갖췄어요.","라는 직각이 없고, 마는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#8','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'ox','auto','「궁금해요」 — 여러 가지 사각형 가운데 직사각형을 모두 고르라고 했어요. 정사각형은 고르면 안 돼요.',ARRAY['M4-2-u2-X17']::text[],false,'{"seq":8,"concept":"M4-2-u2-C9","difficulty":2,"kind":"ox","stem":"「궁금해요」 — 여러 가지 사각형 가운데 직사각형을 모두 고르라고 했어요. 정사각형은 고르면 안 돼요.","answer":"X","reason_options":[{"t":"정사각형도 네 각이 모두 직각이라 직사각형이라고 부를 수 있어서","correct":true},{"t":"한 사각형은 이름이 하나뿐이라서","mis":"M4-2-u2-X17"}],"mis":"M4-2-u2-X17","explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","정사각형도 네 각이 모두 직각이에요.","그래서 정사각형도 골라야 해요 — 이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#9','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',2,'mc','auto','「수학익힘」 — 길이가 같은 짧은 막대 2개와 길이가 같은 긴 막대 2개가 있어요. 이 막대 4개를 모두 이어서 만들 수 있는 사각형은 평행사변형, 마름모, 정사각형 가운데 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X17']::text[],false,'{"seq":9,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 길이가 같은 짧은 막대 2개와 길이가 같은 긴 막대 2개가 있어요. 이 막대 4개를 모두 이어서 만들 수 있는 사각형은 평행사변형, 마름모, 정사각형 가운데 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X14"},{"t":"세 가지 모두","mis":"M4-2-u2-X17"}],"explanation":["막대의 길이가 두 가지예요 — 마주 보는 두 변의 길이만 같게 만들 수 있어요.","마름모와 정사각형은 네 변의 길이가 모두 같아야 해요.","그래서 평행사변형만 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_basic#10','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_basic','lesson_basic','M4-2-u2-C9',3,'error','auto','「수학에 퐁당」 — 정사각형에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X12','M4-2-u2-X18']::text[],false,'{"seq":10,"concept":"M4-2-u2-C9","difficulty":3,"kind":"error","stem":"「수학에 퐁당」 — 정사각형에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"지아 — 「정사각형은 마주 보는 두 각의 크기가 서로 달라.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"민준 — 「정사각형은 마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"},{"t":"정후 — 「정사각형은 네 변의 길이가 같아.」","mis":"M4-2-u2-X18"}],"explanation":["정사각형은 네 각의 크기가 모두 90°예요.","그래서 마주 보는 두 각의 크기도 서로 같아요.","지아의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#1','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',2,'ox','auto','「꼭 알아 둬요」 — 마주 보는 두 쌍의 변이 서로 평행하면 직사각형이에요.',ARRAY['M4-2-u2-X27']::text[],false,'{"seq":1,"concept":"M4-2-u2-C9","difficulty":2,"kind":"ox","stem":"「꼭 알아 둬요」 — 마주 보는 두 쌍의 변이 서로 평행하면 직사각형이에요.","answer":"X","reason_options":[{"t":"마주 보는 두 쌍의 변이 평행해도 네 각이 모두 직각이 아니면 직사각형이 아니라서","correct":true},{"t":"평행한 변이 두 쌍이면 모두 직사각형이라서","mis":"M4-2-u2-X27"}],"mis":"M4-2-u2-X27","explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","그림처럼 평행한 변이 두 쌍이어도 직각이 없을 수 있어요.","평행사변형과 직사각형의 차이를 생각해요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]]],"lab":[[[52.5,14.2],"가"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#2','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',2,'mc','auto','「수학익힘」 — 마름모 가와 평행사변형 나의 같은 점은 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X27','M4-2-u2-X06']::text[],false,'{"seq":2,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 마름모 가와 평행사변형 나의 같은 점은 어느 것인가요?","options":[{"t":"마주 보는 두 변의 길이가 서로 같아요","correct":true},{"t":"네 변의 길이가 모두 같아요","mis":"M4-2-u2-X14"},{"t":"네 각이 모두 직각이에요","mis":"M4-2-u2-X27"},{"t":"평행한 변이 없어요","mis":"M4-2-u2-X06"}],"explanation":["마름모와 평행사변형은 모두 마주 보는 두 쌍의 변이 평행해요.","둘 다 마주 보는 두 변의 길이가 같아요.","다른 점: 가는 네 변의 길이가 같지만 나는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"poly":[[[7.5,52.5],[52.5,30.0],[97.5,52.5],[52.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#3','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'sa','auto','「개념 톡」 — 사각형 마는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"「개념 톡」 — 사각형 마는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["평행한 변·변의 길이·각의 크기를 차례로 살펴봐요.","마는 평행한 변이 두 쌍이고 네 변이 같고 네 각이 직각이에요.","다섯 이름 모두 — 5가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「개념 톡」 — 사각형 라는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["라는 평행한 변이 두 쌍이고 네 변의 길이가 모두 같아요.","직각은 없어요.","사다리꼴, 평행사변형, 마름모 — 3가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false}},{"stem":"「개념 톡」 — 사각형 다는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["다는 평행한 변이 두 쌍이고 네 각이 모두 직각이에요.","길이가 다른 변이 있어요.","사다리꼴, 평행사변형, 직사각형 — 3가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#4','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'error','auto','「친구의 설명」 — 직사각형과 정사각형의 성질을 설명했어요. 잘못 설명한 사람은 누구인가요?',ARRAY['M4-2-u2-X26','M4-2-u2-X18']::text[],false,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 직사각형과 정사각형의 성질을 설명했어요. 잘못 설명한 사람은 누구인가요?","options":[{"t":"도윤 — 「직사각형은 이웃한 두 변의 길이가 같아.」","correct":true,"mis_target":"M4-2-u2-X26"},{"t":"서윤 — 「직사각형은 마주 보는 두 각의 크기가 같아.」","mis":"M4-2-u2-X18"},{"t":"은비 — 「정사각형은 이웃한 두 각의 크기의 합이 180°야.」","mis":"M4-2-u2-X18"},{"t":"건우 — 「정사각형은 마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"}],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","이웃한 두 변은 길이가 다를 수 있어요 — 마주 보는 변과 이웃한 변을 섞지 않아요.","도윤이의 설명이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#5','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'mc','auto','「꼭 알아 둬요」 — 「다, 마는 마주 보는 두 쌍의 변이 평행하니까 직사각형이에요.」라고 설명했어요. 나도 마주 보는 두 쌍의 변이 평행한데 직사각형이 아니에요. 무엇을 더 확인해야 하나요?',ARRAY['M4-2-u2-X16','M4-2-u2-X09','M4-2-u2-X11']::text[],false,'{"seq":5,"concept":"M4-2-u2-C9","difficulty":3,"kind":"mc","stem":"「꼭 알아 둬요」 — 「다, 마는 마주 보는 두 쌍의 변이 평행하니까 직사각형이에요.」라고 설명했어요. 나도 마주 보는 두 쌍의 변이 평행한데 직사각형이 아니에요. 무엇을 더 확인해야 하나요?","options":[{"t":"네 각이 모두 직각인지","correct":true},{"t":"네 변의 길이가 모두 같은지","mis":"M4-2-u2-X16"},{"t":"평행한 변이 한 쌍인지","mis":"M4-2-u2-X09"},{"t":"비스듬히 기울어졌는지","mis":"M4-2-u2-X11"}],"explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","평행한 변만으로는 평행사변형과 구별할 수 없어요.","네 각이 모두 직각인지 확인해야 해요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[217.5,30.0],[307.5,30.0],[307.5,75.0],[217.5,75.0]],[[322.5,52.5],[367.5,30.0],[412.5,52.5],[367.5,75.0]],[[442.5,22.5],[502.5,22.5],[502.5,82.5],[442.5,82.5]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,21.8],"다"],[[367.5,21.8],"라"],[[472.5,14.2],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#6','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'mc','auto','「확인 문제」 — 평행사변형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X11','M4-2-u2-X18','M4-2-u2-X17']::text[],true,'{"seq":6,"concept":"M4-2-u2-C9","difficulty":3,"kind":"mc","stem":"「확인 문제」 — 평행사변형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다","correct":true},{"t":"나","mis":"M4-2-u2-X11"},{"t":"가, 다","mis":"M4-2-u2-X18"},{"t":"다","mis":"M4-2-u2-X17"}],"explanation":["마주 보는 두 쌍의 변이 평행한지 확인해요.","가(직사각형), 나, 다(정사각형) 모두 마주 보는 두 쌍의 변이 평행해요.","그래서 셋 다 평행사변형이에요."],"asset":{"type":"geo","items":[{"w":315,"h":90,"grid":15,"poly":[[[7.5,30.0],[97.5,30.0],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[232.5,22.5],[292.5,22.5],[292.5,82.5],[232.5,82.5]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,14.2],"다"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 직사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다","correct":true},{"t":"가","mis":"M4-2-u2-X17"},{"t":"가, 나, 다","mis":"M4-2-u2-X27"},{"t":"나","mis":"M4-2-u2-X18"}],"explanation":["네 각이 모두 직각인지 확인해요.","가와 다(정사각형)가 직사각형이에요.","나는 직각이 없어요."],"asset":{"type":"geo","items":[{"w":315,"h":90,"grid":15,"poly":[[[7.5,30.0],[97.5,30.0],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[232.5,22.5],[292.5,22.5],[292.5,82.5],[232.5,82.5]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,14.2],"다"]]}],"tag":false}},{"stem":"「확인 문제」 — 정사각형을 고른 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M4-2-u2-X26"},{"t":"가, 다","mis":"M4-2-u2-X17"},{"t":"나","mis":"M4-2-u2-X14"}],"explanation":["네 변의 길이가 모두 같고 네 각이 모두 직각인지 확인해요.","다만 정사각형이에요.","가는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":315,"h":90,"grid":15,"poly":[[[7.5,30.0],[97.5,30.0],[97.5,75.0],[7.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[232.5,22.5],[292.5,22.5],[292.5,82.5],[232.5,82.5]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,14.2],"다"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#7','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',3,'match','auto','사각형의 이름과 그 사각형을 정하는 조건을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u2-C9","difficulty":3,"kind":"match","stem":"사각형의 이름과 그 사각형을 정하는 조건을 이으세요.","pairs":[{"l":"사다리꼴","r":"평행한 변이 한 쌍이라도 있어요"},{"l":"마름모","r":"네 변의 길이가 모두 같아요"},{"l":"직사각형","r":"네 각이 모두 직각이에요"}],"mis":"M4-2-u2-X10","explanation":["사각형의 이름은 모양이 아니라 조건으로 정해요.","평행한 변 → 사다리꼴, 변의 길이 → 마름모, 각의 크기 → 직사각형.","정사각형은 네 변과 네 각이 모두 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사각형의 이름과 그 사각형을 정하는 조건을 이으세요.","pairs":[{"l":"평행사변형","r":"마주 보는 두 쌍의 변이 서로 평행해요"},{"l":"정사각형","r":"네 변의 길이가 모두 같고 네 각이 모두 직각이에요"},{"l":"사다리꼴","r":"평행한 변이 한 쌍이라도 있어요"}],"explanation":["평행사변형은 평행한 변이 두 쌍이에요.","정사각형은 변과 각이 모두 같아요.","사다리꼴은 평행한 변이 한 쌍이라도 있으면 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#8','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'sa','auto','「수학익힘」 — 두 변이 8 cm, 3 cm인 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"「수학익힘」 — 두 변이 8 cm, 3 cm인 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","8 cm 두 개, 3 cm 두 개예요.","8 + 3 + 8 + 3 = 22 — 22 cm예요."],"asset":{"type":"geo","items":[{"w":115.5,"h":66.0,"poly":[[[18.0,18.0],[97.5,18.0],[97.5,48.0],[18.0,48.0]]],"right":[[[18.0,48.0],[18.0,18.0],[97.5,18.0]],[[18.0,18.0],[97.5,18.0],[97.5,48.0]],[[97.5,18.0],[97.5,48.0],[18.0,48.0]],[[97.5,48.0],[18.0,48.0],[18.0,18.0]]],"lab":[[[57.8,6.7],"8 cm"],[[-1.7,33.0],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#9','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'essay','teacher','「친구의 설명」 — 직사각형과 정사각형의 성질을 「변」「각」「평행」이라는 말을 넣어 각각 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"「친구의 설명」 — 직사각형과 정사각형의 성질을 「변」「각」「평행」이라는 말을 넣어 각각 설명해 보세요.","answer_guide":{"answer":"예: 직사각형은 마주 보는 두 쌍의 변이 서로 평행하고 마주 보는 두 변의 길이가 같으며, 네 각이 모두 직각이라 마주 보는 두 각의 크기가 같고 이웃한 두 각의 크기의 합은 180°입니다. 정사각형도 같은 성질이 있고, 네 변의 길이가 모두 같습니다.","scoring_points":["평행에 대한 성질을 썼는가","변의 길이에 대한 성질을 썼는가","각에 대한 성질을 썼는가"]},"explanation":["직사각형과 정사각형을 자·각도기·삼각자로 확인해요.","변·각·평행 세 가지로 나누어 써요.","정사각형은 네 변의 길이까지 모두 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L08_challenge#10','math',4,2,'u2','L08','tb_g4_2_math_u2_L08_challenge','lesson_challenge','M4-2-u2-C9',4,'essay','teacher','「수학에 퐁당」 — 지아는 「정사각형은 마주 보는 두 각의 크기가 서로 달라.」라고 말했어요. 바르게 고치고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"「수학에 퐁당」 — 지아는 「정사각형은 마주 보는 두 각의 크기가 서로 달라.」라고 말했어요. 바르게 고치고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 정사각형은 마주 보는 두 각의 크기가 서로 같습니다. 정사각형은 네 각의 크기가 모두 90°이므로 마주 보는 두 각의 크기도 같습니다.","scoring_points":["마주 보는 두 각의 크기가 같다고 고쳤는가","네 각이 모두 90°라는 까닭을 썼는가","바르게 고친 문장을 완성했는가"]},"explanation":["정사각형은 네 각이 모두 직각이에요.","그래서 마주 보는 두 각도 같아요.","지아의 말을 「같아」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#1','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'mc','auto','「알지오매스로 마름모 그리기」 — 두 원을 겹치게 그리고, 두 원이 만나는 점과 원의 중심을 연결했더니 마름모가 아니었어요. 그 까닭은 무엇인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X16']::text[],false,'{"seq":1,"concept":"M4-2-u2-C10","difficulty":1,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 두 원을 겹치게 그리고, 두 원이 만나는 점과 원의 중심을 연결했더니 마름모가 아니었어요. 그 까닭은 무엇인가요?","options":[{"t":"네 변의 길이가 모두 같지 않아서","correct":true},{"t":"변이 네 개가 아니어서","mis":"M4-2-u2-X19"},{"t":"네 각이 모두 직각이 아니어서","mis":"M4-2-u2-X16"},{"t":"두 원이 서로 겹쳐서","mis":"M4-2-u2-X19"}],"explanation":["두 원의 크기가 서로 달라요.","그래서 사각형에 길이가 다른 변이 생겨요.","네 변의 길이가 모두 같지 않으니 마름모가 아니에요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.5,68.2,"w"],"ㄴ":[87.8,29.3,"n"],"ㄷ":[136.5,68.2,"e"],"ㄹ":[87.8,107.2,"s"]},"circle":[[[58.5,68.2],48.7],[[136.5,68.2],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#2','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'mc','auto','「알지오매스로 마름모 그리기」 — 두 원을 겹쳐 그려서 마름모를 만들려면 두 원을 어떻게 그려야 하나요?',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":2,"concept":"M4-2-u2-C10","difficulty":1,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 두 원을 겹쳐 그려서 마름모를 만들려면 두 원을 어떻게 그려야 하나요?","options":[{"t":"크기가 같은 원 두 개를 그려요","correct":true},{"t":"크기가 다른 원 두 개를 그려요","mis":"M4-2-u2-X19"},{"t":"서로 만나지 않게 그려요","mis":"M4-2-u2-X19"},{"t":"한 원을 아주 크게 그려요","mis":"M4-2-u2-X19"}],"explanation":["마름모는 네 변의 길이가 모두 같아야 해요.","두 원의 크기가 다르면 길이가 다른 변이 생겨요.","그래서 크기가 같은 원 두 개를 그려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#3','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'mc','auto','「알지오매스로 마름모 그리기」 — ① 반지름이 5 cm인 원 두 개를 서로 겹치게 그렸어요. ② 다음에 할 일은 무엇인가요?',ARRAY['M4-2-u2-X18','M4-2-u2-X19']::text[],false,'{"seq":3,"concept":"M4-2-u2-C10","difficulty":1,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — ① 반지름이 5 cm인 원 두 개를 서로 겹치게 그렸어요. ② 다음에 할 일은 무엇인가요?","options":[{"t":"두 원이 서로 만나는 점을 찍어요","correct":true},{"t":"원을 잡고 움직이며 여러 가지 마름모를 관찰해요","mis":"M4-2-u2-X18"},{"t":"원 하나를 지워요","mis":"M4-2-u2-X19"},{"t":"두 원의 중심끼리만 연결해요","mis":"M4-2-u2-X19"}],"explanation":["① 반지름이 5 cm인 원 두 개를 겹치게 그려요.","② 두 원이 서로 만나는 점을 찍어요.","③ 만나는 점과 두 원의 중심을 연결하고, ④ 원을 움직이며 관찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#4','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',1,'sa','auto','「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 원 두 개를 겹치게 그리고, 두 원이 만나는 점과 두 원의 중심을 연결하여 마름모를 그렸어요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u2-C10","difficulty":1,"kind":"sa","stem":"「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 원 두 개를 겹치게 그리고, 두 원이 만나는 점과 두 원의 중심을 연결하여 마름모를 그렸어요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변은 모두 원의 중심과 원 위의 점을 이은 선분이에요.","그 선분은 원의 반지름이에요.","반지름이 5 cm이니 한 변은 5 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[68.2,68.2],[19.5,68.2]]],"lab":[[[43.9,57.0],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#5','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'mc','auto','「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 사각형 ㄱㄴㄷㄹ이 마름모인 까닭은 무엇인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X19','M4-2-u2-X28']::text[],false,'{"seq":5,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 사각형 ㄱㄴㄷㄹ이 마름모인 까닭은 무엇인가요?","options":[{"t":"네 변이 모두 원의 반지름이어서 길이가 같기 때문에","correct":true},{"t":"네 각이 모두 직각이기 때문에","mis":"M4-2-u2-X16"},{"t":"두 원이 겹쳤기 때문에","mis":"M4-2-u2-X19"},{"t":"네 변의 길이가 같아 보이기 때문에","mis":"M4-2-u2-X28"}],"explanation":["원은 반지름의 길이가 일정해요.","사각형의 네 변은 모두 두 원의 반지름이에요.","그래서 네 변의 길이가 모두 같은 마름모예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#6','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'sa','auto','「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 크기가 같은 두 원으로 마름모를 그렸어요. 이 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u2-C10","difficulty":2,"kind":"sa","stem":"「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 크기가 같은 두 원으로 마름모를 그렸어요. 이 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["네 변이 모두 반지름이에요.","5 cm가 4개예요.","5 × 4 = 20 — 20 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[68.2,68.2],[19.5,68.2]]],"lab":[[[43.9,57.0],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#7','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'mc','auto','「알지오매스로 마름모 그리기」 — ④ 원을 잡고 움직이며 여러 가지 마름모를 관찰했어요. 원을 움직여도 바뀌지 않는 것은 무엇인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X14','M4-2-u2-X19']::text[],false,'{"seq":7,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — ④ 원을 잡고 움직이며 여러 가지 마름모를 관찰했어요. 원을 움직여도 바뀌지 않는 것은 무엇인가요?","options":[{"t":"사각형의 네 변의 길이가 모두 같은 것","correct":true},{"t":"네 각의 크기","mis":"M4-2-u2-X16"},{"t":"사각형의 모양","mis":"M4-2-u2-X14"},{"t":"두 원이 만나는 점의 자리","mis":"M4-2-u2-X19"}],"explanation":["원을 움직이면 두 원이 만나는 점의 자리와 사각형의 모양이 바뀌어요.","하지만 네 변은 언제나 반지름이에요.","그래서 네 변의 길이가 같은 마름모는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#8','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',2,'ox','auto','「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 크기가 같은 두 원으로 그린 마름모의 한 변은 10 cm예요.',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":2,"kind":"ox","stem":"「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 크기가 같은 두 원으로 그린 마름모의 한 변은 10 cm예요.","answer":"X","reason_options":[{"t":"마름모의 변은 지름이 아니라 반지름이라서 5 cm여서","correct":true},{"t":"원의 지름이 마름모의 한 변이 되어서","mis":"M4-2-u2-X19"}],"mis":"M4-2-u2-X19","explanation":["마름모의 변은 원의 중심과 원 위의 한 점을 이은 선분이에요.","이 선분은 반지름이에요.","한 변은 5 cm예요 — 이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#9','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C5',2,'mc','auto','「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그려요. 직선을 그린 다음에 할 일은 무엇인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X19','M4-2-u2-X14']::text[],false,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그려요. 직선을 그린 다음에 할 일은 무엇인가요?","options":[{"t":"그 직선과 평행한 직선을 그려요","correct":true},{"t":"그 직선에 수직인 직선을 그려요","mis":"M4-2-u2-X23"},{"t":"크기가 같은 원 두 개를 그려요","mis":"M4-2-u2-X19"},{"t":"길이가 같은 선분 네 개를 그려요","mis":"M4-2-u2-X14"}],"explanation":["① 직선을 그려요. ② 평행선을 그려요.","③ 평행선의 한 직선에 점을 표시하고 ④ 선분을 그어 사각형을 만들어요.","평행한 변이 한 쌍이라도 생기니 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_basic#10','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_basic','lesson_basic','M4-2-u2-C10',3,'mc','auto','「꼭 알아 둬요」 — 공학 도구를 사용하기 어려우면 컴퍼스와 자로 마름모를 그릴 수 있어요. 두 번째 원을 그릴 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":10,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「꼭 알아 둬요」 — 공학 도구를 사용하기 어려우면 컴퍼스와 자로 마름모를 그릴 수 있어요. 두 번째 원을 그릴 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"컴퍼스를 벌린 정도를 첫 번째 원과 같게 해요","correct":true},{"t":"컴퍼스를 첫 번째 원보다 더 벌려요","mis":"M4-2-u2-X19"},{"t":"첫 번째 원과 만나지 않게 그려요","mis":"M4-2-u2-X19"},{"t":"첫 번째 원의 지름만큼 벌려요","mis":"M4-2-u2-X19"}],"explanation":["컴퍼스를 벌린 정도가 반지름이에요.","두 원의 반지름이 같아야 네 변의 길이가 같아요.","그래서 벌린 정도를 그대로 두고 두 번째 원을 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#1','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',2,'mc','auto','「친구의 설명」 — 「그린 사각형은 네 변의 길이가 같아 보이기 때문에 마름모입니다.」 이 설명을 더 바르게 하려면 어떤 근거를 대야 하나요?',ARRAY['M4-2-u2-X16','M4-2-u2-X14','M4-2-u2-X19']::text[],false,'{"seq":1,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「친구의 설명」 — 「그린 사각형은 네 변의 길이가 같아 보이기 때문에 마름모입니다.」 이 설명을 더 바르게 하려면 어떤 근거를 대야 하나요?","options":[{"t":"네 변이 모두 원의 반지름이라 길이가 같다는 것","correct":true},{"t":"네 각이 모두 직각이라는 것","mis":"M4-2-u2-X16"},{"t":"다이아몬드처럼 세워져 있다는 것","mis":"M4-2-u2-X14"},{"t":"두 원이 서로 겹쳐 있다는 것","mis":"M4-2-u2-X19"}],"explanation":["「같아 보인다」는 눈대중이에요.","원은 반지름의 길이가 일정해요 — 네 변이 모두 반지름이에요.","그래서 네 변의 길이가 같은 마름모라고 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#2','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',2,'ox','auto','「알지오매스로 마름모 그리기」 — 크기가 다른 두 원을 겹쳐 그리고, 두 원이 만나는 점과 두 원의 중심을 연결하면 마름모가 돼요.',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":2,"concept":"M4-2-u2-C10","difficulty":2,"kind":"ox","stem":"「알지오매스로 마름모 그리기」 — 크기가 다른 두 원을 겹쳐 그리고, 두 원이 만나는 점과 두 원의 중심을 연결하면 마름모가 돼요.","answer":"X","reason_options":[{"t":"두 원의 반지름이 달라 길이가 다른 변이 생겨서","correct":true},{"t":"두 원이 만나기만 하면 마름모가 되어서","mis":"M4-2-u2-X19"}],"mis":"M4-2-u2-X19","explanation":["두 원이 만나는 점과 각 원의 중심을 이은 선분은 그 원의 반지름이에요.","두 원의 크기가 다르면 반지름도 달라요.","길이가 다른 변이 생겨 마름모가 아니에요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.5,68.2,"w"],"ㄴ":[87.8,29.3,"n"],"ㄷ":[136.5,68.2,"e"],"ㄹ":[87.8,107.2,"s"]},"circle":[[[58.5,68.2],48.7],[[136.5,68.2],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#3','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'mc','auto','「생각해 봐요」 — 크기가 다른 두 원으로 마름모를 그리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X15']::text[],false,'{"seq":3,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 크기가 다른 두 원으로 마름모를 그리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원의 중심을 맞춰 그리고, 작은 원의 지름과 그 지름에 수직이면서 원의 중심을 지나는 큰 원의 지름을 그은 뒤 네 끝점을 이어요","correct":true},{"t":"두 원을 조금만 겹쳐 그리고 만나는 점과 두 중심을 이어요","mis":"M4-2-u2-X19"},{"t":"두 원을 떨어뜨려 그리고 두 중심을 이어요","mis":"M4-2-u2-X19"},{"t":"큰 원의 지름 두 개를 비스듬히 긋고 끝점을 이어요","mis":"M4-2-u2-X15"}],"explanation":["크기가 다른 두 원이라도 원의 중심을 맞춰 그릴 수 있어요.","수직인 두 지름은 서로를 반으로 나누고 수직으로 만나요.","그 끝점을 이으면 네 변의 길이가 같은 마름모가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#4','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C8',3,'mc','auto','「생각해 봐요」 — 원의 중심을 맞춰 그린 두 원에서 수직인 두 지름의 끝점을 이으면 마름모가 돼요. 이 방법과 관계있는 마름모의 성질은 어느 것인가요?',ARRAY['M4-2-u2-X25','M4-2-u2-X16','M4-2-u2-X09']::text[],false,'{"seq":4,"concept":"M4-2-u2-C8","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 원의 중심을 맞춰 그린 두 원에서 수직인 두 지름의 끝점을 이으면 마름모가 돼요. 이 방법과 관계있는 마름모의 성질은 어느 것인가요?","options":[{"t":"마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나고 서로를 반으로 나눠요","correct":true},{"t":"마주 보는 두 각의 크기가 달라요","mis":"M4-2-u2-X25"},{"t":"네 각이 모두 직각이에요","mis":"M4-2-u2-X16"},{"t":"평행한 변이 한 쌍만 있어요","mis":"M4-2-u2-X09"}],"explanation":["두 지름은 원의 중심에서 만나요 — 서로를 반으로 나눠요.","두 지름이 수직이에요.","마름모의 마주 보는 꼭짓점을 이은 두 선분의 성질과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#5','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'error','auto','「꼭 알아 둬요」 — 컴퍼스와 자로 마름모를 그리는 방법을 말했어요. 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X18']::text[],false,'{"seq":5,"concept":"M4-2-u2-C10","difficulty":3,"kind":"error","stem":"「꼭 알아 둬요」 — 컴퍼스와 자로 마름모를 그리는 방법을 말했어요. 잘못 말한 사람은 누구인가요?","options":[{"t":"건우 — 「두 번째 원은 컴퍼스를 더 벌려 그려도 마름모가 돼.」","correct":true,"mis_target":"M4-2-u2-X19"},{"t":"은비 — 「컴퍼스를 벌린 정도를 그대로 두고 두 원을 그려.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「두 원의 중심과 두 원이 만나는 점을 이어.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「네 변이 모두 반지름이라 길이가 같아.」","mis":"M4-2-u2-X18"}],"explanation":["컴퍼스를 벌린 정도가 원의 반지름이에요.","더 벌리면 두 원의 반지름이 달라져요.","건우의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#6','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',3,'mc','auto','「알지오매스로 마름모 그리기」 — 알지오매스로 마름모를 그리는 순서로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X18']::text[],false,'{"seq":6,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 알지오매스로 마름모를 그리는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"①→②→③→④","correct":true},{"t":"②→①→③→④","mis":"M4-2-u2-X18"},{"t":"①→③→②→④","mis":"M4-2-u2-X18"},{"t":"③→②→①→④","mis":"M4-2-u2-X18"}],"explanation":["① 원 두 개를 서로 겹치게 그려요.","② 두 원이 서로 만나는 점을 찍어요 → ③ 두 원이 만나는 점과 두 원의 중심을 연결해요.","④ 원을 잡고 움직이며 여러 가지 마름모를 관찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#7','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C8',3,'mc','auto','「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ에서 두 원의 중심을 이은 선분 ㄱㄷ과 두 원이 만나는 점을 이은 선분 ㄴㄹ은 서로 어떻게 만나나요?',ARRAY['M4-2-u2-X23','M4-2-u2-X15']::text[],false,'{"seq":7,"concept":"M4-2-u2-C8","difficulty":3,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 마름모 ㄱㄴㄷㄹ에서 두 원의 중심을 이은 선분 ㄱㄷ과 두 원이 만나는 점을 이은 선분 ㄴㄹ은 서로 어떻게 만나나요?","options":[{"t":"서로 수직으로 만나요","correct":true},{"t":"서로 평행해요","mis":"M4-2-u2-X23"},{"t":"비스듬히 만나요","mis":"M4-2-u2-X15"},{"t":"만나지 않아요","mis":"M4-2-u2-X15"}],"explanation":["선분 ㄱㄷ과 선분 ㄴㄹ은 마름모의 마주 보는 꼭짓점끼리 이은 두 선분이에요.","마름모에서 이 두 선분은 서로 수직으로 만나요.","또 서로를 반으로 나눠요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"dash":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#8','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',4,'essay','teacher','「알지오매스로 마름모 그리기」 — 알지오매스(또는 컴퍼스와 자)를 이용하여 마름모를 그리는 방법을 순서대로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C10","difficulty":4,"kind":"essay","stem":"「알지오매스로 마름모 그리기」 — 알지오매스(또는 컴퍼스와 자)를 이용하여 마름모를 그리는 방법을 순서대로 설명해 보세요.","answer_guide":{"answer":"예: 반지름이 5 cm인 원 두 개를 서로 겹치게 그립니다. 두 원이 서로 만나는 점을 찍고, 두 원이 만나는 점과 두 원의 중심을 연결합니다. 원을 잡고 움직이며 여러 가지 마름모를 관찰합니다.","scoring_points":["크기가 같은 원 두 개를 겹치게 그린다고 썼는가","두 원이 만나는 점을 찍는다고 썼는가","만나는 점과 두 원의 중심을 연결한다고 썼는가"]},"explanation":["크기가 같은 두 원을 겹쳐 그려요.","만나는 점과 두 중심을 이어요.","원을 움직여 여러 가지 마름모를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#9','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C10',4,'essay','teacher','「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 사각형이 마름모인 이유를 원의 성질을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u2-C10","difficulty":4,"kind":"essay","stem":"「알지오매스로 마름모 그리기」 — 크기가 같은 두 원으로 그린 사각형이 마름모인 이유를 원의 성질을 써서 설명해 보세요.","answer_guide":{"answer":"예: 원은 반지름의 길이가 일정합니다. 그린 사각형의 네 변은 모두 두 원의 반지름이고 두 원의 크기가 같으므로 네 변의 길이가 모두 같습니다. 그래서 마름모입니다.","scoring_points":["원은 반지름의 길이가 일정하다고 썼는가","네 변이 모두 반지름이라고 썼는가","네 변의 길이가 같아 마름모라고 결론을 냈는가"]},"explanation":["원의 반지름은 모두 같아요.","네 변이 모두 반지름이에요.","그래서 마름모예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_L09_challenge#10','math',4,2,'u2','L09','tb_g4_2_math_u2_L09_challenge','lesson_challenge','M4-2-u2-C5',4,'essay','teacher','「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그리는 방법을 쓰고, 그린 사각형이 사다리꼴인 이유를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그리는 방법을 쓰고, 그린 사각형이 사다리꼴인 이유를 써 보세요.","answer_guide":{"answer":"예: 직선을 그리고 그 직선과 평행한 직선을 그립니다. 평행선의 두 직선에 점을 두 개씩 표시하고 선분으로 이어 사각형을 만듭니다. 평행한 변이 한 쌍이라도 있으므로 사다리꼴입니다.","scoring_points":["평행선을 먼저 그린다고 썼는가","점을 표시하고 선분으로 사각형을 만든다고 썼는가","평행한 변이 한 쌍이라도 있어 사다리꼴이라고 썼는가"]},"explanation":["평행선을 먼저 그려요.","평행선 위의 점을 선분으로 이어요.","평행한 변이 있으니 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#1','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C2',1,'mc','auto','「스스로 마무리하기」 — 직선 다에 대한 수선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X01']::text[],false,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 직선 다에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 가, 직선 나","correct":true},{"t":"직선 가","mis":"M4-2-u2-X04"},{"t":"직선 나","mis":"M4-2-u2-X04"},{"t":"수선이 없어요","mis":"M4-2-u2-X01"}],"explanation":["직선 다와 직각으로 만나는 직선을 찾아요.","직선 가와 직선 나가 모두 직선 다와 수직으로 만나요.","하나만 찾지 않도록 해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[75.0,0.0],[75.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[63.8,13.5],"다"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#2','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C3',1,'mc','auto','「스스로 마무리하기」 — 서로 평행한 직선을 찾아 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X05']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 서로 평행한 직선을 찾아 고른 것은 어느 것인가요?","options":[{"t":"직선 가와 직선 나","correct":true},{"t":"직선 가와 직선 다","mis":"M4-2-u2-X23"},{"t":"직선 나와 직선 다","mis":"M4-2-u2-X23"},{"t":"평행한 직선이 없어요","mis":"M4-2-u2-X05"}],"explanation":["서로 만나지 않는 두 직선을 찾아요.","직선 가와 직선 나는 모두 직선 다에 수직이라 만나지 않아요.","그래서 직선 가와 직선 나가 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[75.0,0.0],[75.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[63.8,13.5],"다"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#3','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C4',1,'sa','auto','「스스로 마무리하기」 — 평행선 사이의 거리를 재어 보세요. 한 직선에서 다른 직선에 수직인 선분을 그어 재었더니 4 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 평행선 사이의 거리를 재어 보세요. 한 직선에서 다른 직선에 수직인 선분을 그어 재었더니 4 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","직각 표시가 있는 선분이 4 cm예요.","4 cm예요 — 비스듬한 선분은 재지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[45.0,22.5],[45.0,82.5]],[[90.0,22.5],[127.5,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"],[[64.5,52.5],"4 cm"]],"right":[[[45.0,22.5],[45.0,82.5],[60.0,82.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#4','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',1,'mc','auto','「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 평행사변형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X11','M4-2-u2-X17','M4-2-u2-X16']::text[],false,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 평행사변형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다, 라, 마","correct":true},{"t":"나","mis":"M4-2-u2-X11"},{"t":"나, 라","mis":"M4-2-u2-X17"},{"t":"가, 나, 다, 라, 마","mis":"M4-2-u2-X16"}],"explanation":["마주 보는 두 쌍의 변이 평행한지 확인해요.","나, 다(정사각형), 라(마름모), 마(직사각형)예요.","가는 평행한 변이 한 쌍뿐이에요 — 한 사각형을 여러 번 쓸 수 있어요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#5','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C8',1,'sa','auto','「스스로 마무리하기」 — 마름모의 한 변이 6 cm, 한 각이 70°예요. ? cm로 표시된 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 마름모의 한 변이 6 cm, 한 각이 70°예요. ? cm로 표시된 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","한 변이 6 cm예요.","6 cm예요."],"asset":{"type":"geo","items":[{"w":104.4,"h":83.9,"poly":[[[35.4,18.0],[86.4,18.0],[69.0,65.9],[18.0,65.9]]],"lab":[[[60.9,6.8],"6 cm"],[[95.7,48.5],"? cm"],[[31.3,56.6],"70°"],[[73.2,27.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#6','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',1,'mc','auto','「스스로 마무리하기」 — 주어진 변과 연결하여 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X10']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 주어진 변과 연결하여 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M4-2-u2-X04"},{"t":"나, 다","mis":"M4-2-u2-X18"},{"t":"가, 나, 라","mis":"M4-2-u2-X10"}],"explanation":["점을 연결했을 때 평행한 변이 한 쌍이라도 생기는지 봐요.","점 가와 점 라를 이으면 위쪽 변이 아래쪽 변과 평행해요.","점 나·다를 이으면 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"가":[52.5,30.0,"n"],"나":[75.0,12.0,"n"],"다":[82.5,51.0,"n"],"라":[112.5,30.0,"n"]},"seg":[[[15.0,30.0],[15.0,97.5]],[[15.0,97.5],[135.0,97.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#7','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',1,'mc','auto','「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ의 이름으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X10','M4-2-u2-X14']::text[],false,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X16"},{"t":"직사각형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"}],"explanation":["변 ㄱㄹ과 변 ㄴㄷ은 직사각형의 마주 보는 변 위에 있어 평행해요.","변 ㄱㄴ과 변 ㄹㄷ은 평행하지 않아요.","평행한 변이 한 쌍 있는 사각형 — 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"pts":{"ㄱ":[45.0,30.0,"nw"],"ㄴ":[60.0,75.0,"sw"],"ㄷ":[90.0,75.0,"se"],"ㄹ":[90.0,30.0,"ne"]},"poly":[[[15.0,30.0],[135.0,30.0],[135.0,75.0],[15.0,75.0]],[[37.5,7.5],[90.0,7.5],[90.0,97.5],[67.5,97.5]]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#8','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C8',1,'sa','auto','「스스로 마무리하기」 — 두 변이 7 cm, 5 cm인 평행사변형과 마름모는 네 변의 길이의 합이 서로 같아요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 두 변이 7 cm, 5 cm인 평행사변형과 마름모는 네 변의 길이의 합이 서로 같아요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요 — 7 + 5 + 7 + 5 = 24(cm).","마름모의 네 변의 길이의 합도 24 cm예요.","마름모는 네 변이 같으니 24 ÷ 4 = 6 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":121.5,"h":75.0,"poly":[[[40.5,18.0],[103.5,18.0],[81.0,57.0],[18.0,57.0]]],"lab":[[[72.0,6.8],"7 cm"],[[13.2,28.2],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#9','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',2,'mc','auto','「이 단원 학습을 마치고」 — 주차장에서 찾은 사각형을 평행한 변의 수에 따라 분류했어요. 평행한 변이 한 쌍인 사각형을 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X18']::text[],false,'{"seq":9,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 — 주차장에서 찾은 사각형을 평행한 변의 수에 따라 분류했어요. 평행한 변이 한 쌍인 사각형을 고른 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"가, 다","mis":"M4-2-u2-X09"},{"t":"나, 라","mis":"M4-2-u2-X18"},{"t":"가, 다, 마, 바","mis":"M4-2-u2-X09"}],"explanation":["마주 보는 변을 두 쌍 모두 살펴봐요.","가는 한 쌍만 평행해요.","다·마·바는 두 쌍, 나·라는 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[240.0,22.5],[307.5,22.5],[285.0,75.0],[217.5,75.0]],[[7.5,150.0],[45.0,112.5],[97.5,127.5],[75.0,172.5]],[[112.5,150.0],[157.5,112.5],[202.5,127.5],[157.5,165.0]],[[217.5,120.0],[307.5,120.0],[307.5,165.0],[217.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#10','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',2,'mc','auto','「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 서현이가 가장 좋아하는 건물은 두 쌍의 변이 모두 평행하고, 네 변의 길이와 네 각의 크기가 모두 같아요. 어느 건물인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X26','M4-2-u2-X27']::text[],false,'{"seq":10,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 서현이가 가장 좋아하는 건물은 두 쌍의 변이 모두 평행하고, 네 변의 길이와 네 각의 크기가 모두 같아요. 어느 건물인가요?","options":[{"t":"시청","correct":true},{"t":"우리 집","mis":"M4-2-u2-X14"},{"t":"백화점","mis":"M4-2-u2-X26"},{"t":"경찰서","mis":"M4-2-u2-X27"}],"explanation":["조건을 하나씩 확인해요.","두 쌍 평행: 경찰서·시청·백화점·우리 집 → 네 변이 같음: 시청·우리 집 → 네 각이 같음: 시청.","모든 조건을 만족하는 건물은 시청이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#11','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C7',2,'sa','auto','평행사변형의 한 각이 125°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"평행사변형의 한 각이 125°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["평행사변형에서 이웃한 두 각의 크기의 합은 180°예요.","180 − 125 = 55예요.","55°예요."],"asset":{"type":"geo","items":[{"w":136.8,"h":72.9,"poly":[[[43.8,18.0],[118.8,18.0],[93.0,54.9],[18.0,54.9]]],"lab":[[[86.1,41.6],"125°"],[[35.9,45.6],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#12','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C4',2,'sa','auto','「수학익힘」 — 직선 가와 나는 평행해요. 그림의 세 선분 가운데 평행선 사이의 거리를 나타내는 선분은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 직선 가와 나는 평행해요. 그림의 세 선분 가운데 평행선 사이의 거리를 나타내는 선분은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["수직인 선분을 찾아요.","직각 표시가 있는 선분이 3 cm예요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":165,"h":105,"line":[[[0.0,15.0],[165.0,15.0]],[[0.0,82.5],[165.0,82.5]]],"seg":[[[24.0,15.0],[24.0,82.5]],[[72.0,15.0],[108.0,82.5]],[[123.0,15.0],[144.0,82.5]]],"lab":[[[6.8,26.2],"가"],[[6.8,93.8],"나"],[[43.5,48.8],"3 cm"],[[103.5,48.8],"4 cm"],[[147.0,48.8],"3.5 cm"]],"right":[[[24.0,15.0],[24.0,82.5],[39.0,82.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#13','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',2,'match','auto','「스스로 마무리하기」 — 빈칸에 알맞은 이름을 이으세요.','{}'::text[],false,'{"seq":13,"concept":"M4-2-u2-C5","difficulty":2,"kind":"match","stem":"「스스로 마무리하기」 — 빈칸에 알맞은 이름을 이으세요.","pairs":[{"l":"평행한 변이 한 쌍이라도 있는 사각형","r":"사다리꼴"},{"l":"마주 보는 두 쌍의 변이 서로 평행한 사각형","r":"평행사변형"},{"l":"네 변의 길이가 모두 같은 사각형","r":"마름모"}],"mis":"M4-2-u2-X10","explanation":["사각형의 이름은 조건으로 정해요.","평행한 변 한 쌍 → 사다리꼴, 두 쌍 → 평행사변형.","네 변의 길이가 같으면 → 마름모."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#14','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C2',2,'mc','auto','「개념 톡」 — 삼각자로 주어진 직선에 대한 수선을 그어요. 주어진 직선에 삼각자의 직각을 낀 한 변을 맞춘 다음 할 일은 무엇인가요?',ARRAY['M4-2-u2-X03','M4-2-u2-X23']::text[],false,'{"seq":14,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 삼각자로 주어진 직선에 대한 수선을 그어요. 주어진 직선에 삼각자의 직각을 낀 한 변을 맞춘 다음 할 일은 무엇인가요?","options":[{"t":"삼각자의 직각을 낀 다른 변을 따라 선을 그어요","correct":true},{"t":"삼각자의 가장 긴 변을 따라 선을 그어요","mis":"M4-2-u2-X03"},{"t":"주어진 직선과 만나지 않게 나란히 그어요","mis":"M4-2-u2-X23"},{"t":"삼각자를 떼고 눈대중으로 그어요","mis":"M4-2-u2-X03"}],"explanation":["수선은 주어진 직선과 직각으로 만나요.","직각을 낀 다른 변이 직선과 직각을 이뤄요.","그 변을 따라 그어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#15','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C10',2,'mc','auto','「알지오매스로 마름모 그리기」 — 두 원을 겹쳐 그려서 마름모를 만들려면 두 원을 어떻게 그려야 하나요?',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":15,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 두 원을 겹쳐 그려서 마름모를 만들려면 두 원을 어떻게 그려야 하나요?","options":[{"t":"크기가 같은 원 두 개를 그려요","correct":true},{"t":"크기가 다른 원 두 개를 그려요","mis":"M4-2-u2-X19"},{"t":"서로 만나지 않게 그려요","mis":"M4-2-u2-X19"},{"t":"한 원을 아주 크게 그려요","mis":"M4-2-u2-X19"}],"explanation":["마름모는 네 변의 길이가 같아야 해요.","두 원의 크기가 다르면 길이가 다른 변이 생겨요.","크기가 같은 원 두 개를 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#16','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',2,'ox','auto','「궁금해요」 — 직사각형을 모두 고르라고 할 때 정사각형은 고르면 안 돼요.',ARRAY['M4-2-u2-X17']::text[],false,'{"seq":16,"concept":"M4-2-u2-C9","difficulty":2,"kind":"ox","stem":"「궁금해요」 — 직사각형을 모두 고르라고 할 때 정사각형은 고르면 안 돼요.","answer":"X","reason_options":[{"t":"정사각형도 네 각이 모두 직각이라서","correct":true},{"t":"한 사각형은 이름이 하나뿐이라서","mis":"M4-2-u2-X17"}],"mis":"M4-2-u2-X17","explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","정사각형도 네 각이 모두 직각이에요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#17','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C1',3,'error','auto','「수학에 퐁당」 — 수직과 수선에 대해 잘못 설명한 사람은 누구인가요?',ARRAY['M4-2-u2-X20','M4-2-u2-X18']::text[],false,'{"seq":17,"concept":"M4-2-u2-C1","difficulty":3,"kind":"error","stem":"「수학에 퐁당」 — 수직과 수선에 대해 잘못 설명한 사람은 누구인가요?","options":[{"t":"민준 — 「직사각형에는 서로 수직인 변이 없어.」","correct":true,"mis_target":"M4-2-u2-X20"},{"t":"지아 — 「한 직선에 대한 수선은 셀 수 없이 많아.」","mis":"M4-2-u2-X18"},{"t":"정후 — 「선분과 선분이 만나서 이루는 각이 직각일 때도 서로 수직이라고 해.」","mis":"M4-2-u2-X18"}],"explanation":["직사각형은 이웃한 두 변이 모두 수직이에요.","선분끼리 직각으로 만나도 수직이에요.","민준이의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#18','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',3,'sa','auto','「문제 해결」 — 변 ㄱㄹ과 변 ㄴㄷ이 평행한 사다리꼴 ㄱㄴㄷㄹ에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u2-C5","difficulty":3,"kind":"sa","stem":"「문제 해결」 — 변 ㄱㄹ과 변 ㄴㄷ이 평행한 사다리꼴 ㄱㄴㄷㄹ에서 찾을 수 있는 크고 작은 사다리꼴은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸짜리, 두 칸을 합친 것, 전체를 세어요.","2 + 2 + 1이에요.","5개예요."],"asset":{"type":"geo","items":[{"w":195,"h":97.5,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄹ":[105.0,15.0,"ne"],"ㄴ":[15.0,82.5,"sw"],"ㄷ":[180.0,82.5,"se"]},"seg":[["ㄱ","ㄹ"],["ㄴ","ㄷ"],["ㄱ","ㄴ"],["ㄹ","ㄷ"],["ㄴ",[67.5,15.0]],[[90.0,15.0],[90.0,82.5]]],"right":[[[90.0,15.0],[90.0,82.5],[180.0,82.5]],["ㄱ","ㄴ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#19','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',3,'sa','auto','「스스로 마무리하기」 — 사각형 다는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 사각형 다는 사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["평행한 변·변의 길이·각의 크기를 살펴봐요.","다는 세워 놓은 정사각형이에요.","다섯 이름 모두 — 5가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#20','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C7',3,'sa','auto','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄷㅁ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄷㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["사각형 ㄱㄴㅁㄹ은 평행사변형이에요.","선분 ㄴㅁ은 변 ㄱㄹ과 같은 5 cm예요.","12 − 5 = 7 — 7 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#21','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',3,'ox','auto','「꼭 알아 둬요」 — 마주 보는 두 쌍의 변이 서로 평행하면 직사각형이에요.',ARRAY['M4-2-u2-X27']::text[],false,'{"seq":21,"concept":"M4-2-u2-C9","difficulty":3,"kind":"ox","stem":"「꼭 알아 둬요」 — 마주 보는 두 쌍의 변이 서로 평행하면 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"평행한 변이 두 쌍이면 모두 직사각형이라서","mis":"M4-2-u2-X27"}],"mis":"M4-2-u2-X27","explanation":["직사각형은 네 각이 모두 직각이에요.","평행사변형은 평행한 변이 두 쌍이어도 직각이 없을 수 있어요.","이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[30.0,22.5],[97.5,22.5],[75.0,75.0],[7.5,75.0]]],"lab":[[[52.5,14.2],"가"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#22','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C10',3,'mc','auto','「친구의 설명」 — 「그린 사각형은 네 변의 길이가 같아 보이기 때문에 마름모입니다.」 이 설명을 더 바르게 하려면 어떤 근거를 대야 하나요?',ARRAY['M4-2-u2-X16','M4-2-u2-X14','M4-2-u2-X19']::text[],false,'{"seq":22,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「친구의 설명」 — 「그린 사각형은 네 변의 길이가 같아 보이기 때문에 마름모입니다.」 이 설명을 더 바르게 하려면 어떤 근거를 대야 하나요?","options":[{"t":"네 변이 모두 원의 반지름이라 길이가 같다는 것","correct":true},{"t":"네 각이 모두 직각이라는 것","mis":"M4-2-u2-X16"},{"t":"다이아몬드처럼 세워져 있다는 것","mis":"M4-2-u2-X14"},{"t":"두 원이 서로 겹쳐 있다는 것","mis":"M4-2-u2-X19"}],"explanation":["「같아 보인다」는 눈대중이에요.","네 변이 모두 반지름이에요.","그래서 네 변의 길이가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#23','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C5',4,'essay','teacher','「서술형」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 사다리꼴이에요. 그 이유를 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"「서술형」 — 직사각형 모양의 종이를 선을 따라 잘랐을 때 만들어지는 도형은 사다리꼴이에요. 그 이유를 써 보세요.","answer_guide":{"answer":"예: 직사각형 모양의 종이를 자른 것이므로 잘라 낸 도형들은 모두 직사각형의 평행한 변이 한 쌍이라도 남아 있기 때문입니다. 평행한 변이 한 쌍이라도 있는 사각형은 사다리꼴입니다.","scoring_points":["직사각형의 마주 보는 변이 평행하다고 썼는가","잘라 낸 도형에 평행한 변이 남는다고 썼는가","평행한 변이 한 쌍이라도 있으면 사다리꼴이라고 썼는가"]},"explanation":["직사각형의 마주 보는 변은 평행해요.","잘라도 도형마다 평행한 변이 남아요.","그래서 모두 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#24','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',4,'sa','auto','「수학익힘」 — 두 변이 8 cm, 3 cm인 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"「수학익힘」 — 두 변이 8 cm, 3 cm인 직사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["마주 보는 두 변의 길이가 같아요.","8 + 3 + 8 + 3이에요.","22 cm예요."],"asset":{"type":"geo","items":[{"w":115.5,"h":66.0,"poly":[[[18.0,18.0],[97.5,18.0],[97.5,48.0],[18.0,48.0]]],"right":[[[18.0,48.0],[18.0,18.0],[97.5,18.0]],[[18.0,18.0],[97.5,18.0],[97.5,48.0]],[[97.5,18.0],[97.5,48.0],[18.0,48.0]],[[97.5,48.0],[18.0,48.0],[18.0,18.0]]],"lab":[[[57.8,6.7],"8 cm"],[[-1.7,33.0],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_a#25','math',4,2,'u2','','tb_g4_2_math_u2_review_a','unit_review','M4-2-u2-C9',4,'essay','teacher','「단원 핵심 질문」 — 다양한 모양의 사각형을 어떻게 분류할 수 있는지, 분류하는 기준을 두 가지 이상 들어 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"「단원 핵심 질문」 — 다양한 모양의 사각형을 어떻게 분류할 수 있는지, 분류하는 기준을 두 가지 이상 들어 써 보세요.","answer_guide":{"answer":"예: 평행한 변의 수에 따라 평행한 변이 없는 사각형, 한 쌍인 사각형, 두 쌍인 사각형으로 분류할 수 있습니다. 변의 길이에 따라 네 변의 길이가 모두 같은 사각형과 길이가 다른 변이 있는 사각형으로 분류할 수도 있고, 각의 크기에 따라 네 각이 모두 직각인 사각형을 찾을 수도 있습니다.","scoring_points":["평행한 변의 수를 기준으로 썼는가","변의 길이(또는 각의 크기)를 기준으로 썼는가","기준마다 나뉘는 무리를 썼는가"]},"explanation":["만화에서 평행한 변의 수와 변의 길이로 분류했어요.","각의 크기로도 분류할 수 있어요.","기준이 달라지면 한 사각형이 여러 무리에 들어갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#1','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C2',1,'mc','auto','「수학익힘」 — 직선 라에 대한 수선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X03']::text[],false,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 직선 라에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 가, 직선 나","correct":true},{"t":"직선 가","mis":"M4-2-u2-X04"},{"t":"직선 다","mis":"M4-2-u2-X03"},{"t":"직선 가, 직선 나, 직선 다","mis":"M4-2-u2-X03"}],"explanation":["직선 라와 직각으로 만나는 직선을 찾아요.","직선 가와 직선 나예요.","직선 다는 비스듬히 만나요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,30.0],[150.0,30.0]],[[0.0,75.0],[150.0,75.0]],[[45.0,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]]],"lab":[[[13.5,41.2],"가"],[[13.5,86.2],"나"],[[60.1,8.9],"다"],[[116.2,13.5],"라"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#2','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C3',1,'mc','auto','「수학익힘」 — 서로 평행한 직선을 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X23']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 서로 평행한 직선을 고른 것은 어느 것인가요?","options":[{"t":"직선 다와 직선 마","correct":true},{"t":"직선 나와 직선 라","mis":"M4-2-u2-X05"},{"t":"직선 가와 직선 다","mis":"M4-2-u2-X23"},{"t":"직선 가와 직선 마","mis":"M4-2-u2-X23"}],"explanation":["직선 다와 직선 마는 모두 직선 가에 수직이에요.","한 직선에 수직인 두 직선은 만나지 않아요.","그래서 직선 다와 직선 마가 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,90.0],[150.0,90.0]],[[7.5,90.0],[37.5,0.0]],[[60.0,0.0],[60.0,105.0]],[[82.5,0.0],[105.0,105.0]],[[127.5,0.0],[127.5,105.0]]],"lab":[[[36.0,78.8],"가"],[[22.6,9.2],"나"],[[71.2,36.0],"다"],[[96.3,10.8],"라"],[[138.8,13.5],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#3','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C4',1,'sa','auto','「스스로 마무리하기」 — 비스듬히 놓인 평행선의 한 직선에서 다른 직선에 수직인 선분을 그어 재었더니 1 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 비스듬히 놓인 평행선의 한 직선에서 다른 직선에 수직인 선분을 그어 재었더니 1 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["평행선이 비스듬히 놓여도 재는 방법은 같아요.","수직인 선분의 길이가 거리예요.","1 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#4','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',1,'mc','auto','「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 마름모를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X26']::text[],false,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 마름모를 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"라","mis":"M4-2-u2-X17"},{"t":"나, 다, 라","mis":"M4-2-u2-X14"},{"t":"다, 마","mis":"M4-2-u2-X26"}],"explanation":["네 변의 길이가 모두 같은지 확인해요.","다(정사각형)와 라가 마름모예요.","세워 놓은 정사각형도 마름모예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#5','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C8',1,'sa','auto','「스스로 마무리하기」 — 마름모의 한 각이 70°예요. 이 각과 마주 보는 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 마름모의 한 각이 70°예요. 이 각과 마주 보는 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["마름모는 마주 보는 두 각의 크기가 같아요.","70°인 각과 마주 보는 각을 찾아요.","70°예요."],"asset":{"type":"geo","items":[{"w":104.4,"h":83.9,"poly":[[[35.4,18.0],[86.4,18.0],[69.0,65.9],[18.0,65.9]]],"lab":[[[60.9,6.8],"6 cm"],[[95.7,48.5],"? cm"],[[31.3,56.6],"70°"],[[73.2,27.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#6','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C5',1,'mc','auto','「스스로 마무리하기」 — 주어진 변과 점 나를 연결하여 만든 사각형은 왜 사다리꼴이 아닌가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X10']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 주어진 변과 점 나를 연결하여 만든 사각형은 왜 사다리꼴이 아닌가요?","options":[{"t":"평행한 변이 없기 때문이에요","correct":true},{"t":"네 변의 길이가 모두 달라서예요","mis":"M4-2-u2-X14"},{"t":"직각이 없어서예요","mis":"M4-2-u2-X10"},{"t":"위가 좁고 아래가 넓지 않아서예요","mis":"M4-2-u2-X10"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있어야 해요.","점 나를 이으면 어느 두 변도 평행하지 않아요.","그래서 사다리꼴이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"가":[52.5,30.0,"n"],"나":[75.0,12.0,"n"],"다":[82.5,51.0,"n"],"라":[112.5,30.0,"n"]},"seg":[[[15.0,30.0],[15.0,97.5]],[[15.0,97.5],[135.0,97.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#7','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C5',1,'mc','auto','「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ이 평행한 까닭은 무엇인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X06','M4-2-u2-X05']::text[],false,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄹ과 변 ㄴㄷ이 평행한 까닭은 무엇인가요?","options":[{"t":"두 변이 직사각형의 마주 보는 두 변 위에 있어서","correct":true},{"t":"두 변이 사다리꼴의 비스듬한 변이라서","mis":"M4-2-u2-X10"},{"t":"두 변의 길이가 같아 보여서","mis":"M4-2-u2-X06"},{"t":"그림 안에서 두 변이 만나지 않아서","mis":"M4-2-u2-X05"}],"explanation":["직사각형의 마주 보는 두 변은 평행해요.","변 ㄱㄹ과 변 ㄴㄷ은 그 두 변의 일부예요.","그래서 서로 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"pts":{"ㄱ":[45.0,30.0,"nw"],"ㄴ":[60.0,75.0,"sw"],"ㄷ":[90.0,75.0,"se"],"ㄹ":[90.0,30.0,"ne"]},"poly":[[[15.0,30.0],[135.0,30.0],[135.0,75.0],[15.0,75.0]],[[37.5,7.5],[90.0,7.5],[90.0,97.5],[67.5,97.5]]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#8','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C7',1,'sa','auto','「스스로 마무리하기」 — 두 변이 7 cm, 5 cm인 평행사변형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 두 변이 7 cm, 5 cm인 평행사변형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","7 cm 두 개, 5 cm 두 개예요.","7 + 5 + 7 + 5 = 24 — 24 cm예요."],"asset":{"type":"geo","items":[{"w":121.5,"h":75.0,"poly":[[[40.5,18.0],[103.5,18.0],[81.0,57.0],[18.0,57.0]]],"lab":[[[72.0,6.8],"7 cm"],[[13.2,28.2],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#9','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C6',2,'mc','auto','「이 단원 학습을 마치고」 — 주차장에서 찾은 사각형을 평행한 변의 수에 따라 분류했어요. 평행한 변이 두 쌍인 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X11','M4-2-u2-X09','M4-2-u2-X18']::text[],false,'{"seq":9,"concept":"M4-2-u2-C6","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 — 주차장에서 찾은 사각형을 평행한 변의 수에 따라 분류했어요. 평행한 변이 두 쌍인 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마, 바","correct":true},{"t":"다, 마","mis":"M4-2-u2-X11"},{"t":"가","mis":"M4-2-u2-X09"},{"t":"나, 라","mis":"M4-2-u2-X18"}],"explanation":["마주 보는 두 쌍의 변이 모두 평행한지 봐요.","다, 마, 바(직사각형)예요.","기울어지지 않은 직사각형도 두 쌍이에요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[30.0,22.5],[75.0,22.5],[97.5,75.0],[7.5,75.0]],[[120.0,30.0],[180.0,22.5],[202.5,75.0],[135.0,67.5]],[[240.0,22.5],[307.5,22.5],[285.0,75.0],[217.5,75.0]],[[7.5,150.0],[45.0,112.5],[97.5,127.5],[75.0,172.5]],[[112.5,150.0],[157.5,112.5],[202.5,127.5],[157.5,165.0]],[[217.5,120.0],[307.5,120.0],[307.5,165.0],[217.5,165.0]]],"lab":[[[52.5,14.2],"가"],[[161.2,14.2],"나"],[[262.5,14.2],"다"],[[52.5,104.2],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#10','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',2,'mc','auto','「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 모양이 직사각형인 건물을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X27']::text[],false,'{"seq":10,"concept":"M4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 모양이 직사각형인 건물을 모두 고른 것은 어느 것인가요?","options":[{"t":"백화점, 시청","correct":true},{"t":"백화점","mis":"M4-2-u2-X17"},{"t":"시청, 우리 집","mis":"M4-2-u2-X14"},{"t":"경찰서, 백화점","mis":"M4-2-u2-X27"}],"explanation":["직사각형은 네 각이 모두 직각인 사각형이에요.","네 각의 크기가 모두 같은(직각인) 건물은 백화점과 시청이에요.","시청도 직사각형이라고 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#11','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C8',2,'sa','auto','마름모의 한 각이 110°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"마름모의 한 각이 110°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["마름모에서도 이웃한 두 각의 크기의 합은 180°예요.","180 − 110 = 70이에요.","70°예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":86.7,"poly":[[[36.5,18.0],[90.5,18.0],[72.0,68.7],[18.0,68.7]]],"lab":[[[45.1,30.3],"110°"],[[77.2,27.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#12','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C4',2,'sa','auto','「추론」 — 변 ㄱㄹ과 변 ㄴㄷ이 평행하고 삼각형 ㄱㄷㄹ은 이등변삼각형이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"「추론」 — 변 ㄱㄹ과 변 ㄴㄷ이 평행하고 삼각형 ㄱㄷㄹ은 이등변삼각형이에요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["변 ㄹㄷ이 두 평행선에 수직이에요.","이등변삼각형이라 변 ㄹㄷ은 변 ㄱㄹ과 같아요.","8 cm예요."],"asset":{"type":"geo","items":[{"w":120.0,"h":102.0,"pts":{"ㄱ":[36.0,18.0,"nw"],"ㄴ":[18.0,84.0,"sw"],"ㄷ":[102.0,84.0,"se"],"ㄹ":[102.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]],"lab":[[[69.0,6.7],"8 cm"],[[60.0,95.3],"10 cm"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#13','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C1',2,'match','auto','알맞은 말끼리 이으세요.','{}'::text[],false,'{"seq":13,"concept":"M4-2-u2-C1","difficulty":2,"kind":"match","stem":"알맞은 말끼리 이으세요.","pairs":[{"l":"두 직선이 만나서 이루는 각이 직각인 관계","r":"수직"},{"l":"서로 수직으로 만날 때 한 직선을 다른 직선에 대해 부르는 말","r":"수선"},{"l":"평행한 두 직선","r":"평행선"}],"mis":"M4-2-u2-X02","explanation":["수직은 관계, 수선은 직선이에요.","평행선은 평행한 두 직선이에요.","관계를 나타내는 말과 직선을 가리키는 말을 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#14','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C3',2,'mc','auto','「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 그어요. 바른 방법은 어느 것인가요?',ARRAY['M4-2-u2-X24','M4-2-u2-X23']::text[],false,'{"seq":14,"concept":"M4-2-u2-C3","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 삼각자 두 개로 주어진 직선과 평행한 직선을 그어요. 바른 방법은 어느 것인가요?","options":[{"t":"두 삼각자의 한 변을 주어진 직선에 맞추고, 한 삼각자를 고정한 채 다른 삼각자를 움직여 그어요","correct":true},{"t":"두 삼각자를 모두 움직이며 그어요","mis":"M4-2-u2-X24"},{"t":"직각을 낀 다른 변을 따라 그어요","mis":"M4-2-u2-X23"},{"t":"삼각자 없이 나란해 보이게 그어요","mis":"M4-2-u2-X24"}],"explanation":["한 삼각자는 고정해요.","다른 삼각자만 움직여 그어요.","직각을 낀 다른 변을 따라 그으면 수선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#15','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C10',2,'sa','auto','「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 원 두 개를 겹치게 그려 마름모를 그렸어요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M4-2-u2-C10","difficulty":2,"kind":"sa","stem":"「알지오매스로 마름모 그리기」 — 반지름이 5 cm인 원 두 개를 겹치게 그려 마름모를 그렸어요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모의 네 변은 모두 원의 반지름이에요.","반지름은 5 cm예요.","5 cm예요."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[68.2,68.2,"w"],"ㄴ":[97.5,29.3,"n"],"ㄷ":[126.8,68.2,"e"],"ㄹ":[97.5,107.2,"s"]},"circle":[[[68.2,68.2],48.7],[[126.8,68.2],48.8]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[68.2,68.2],[19.5,68.2]]],"lab":[[[43.9,57.0],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#16','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',2,'ox','auto','「이 단원 학습을 마치고」 — 정사각형은 네 변의 길이가 모두 같으므로 마름모라고 부를 수 있어요.',ARRAY['M4-2-u2-X17']::text[],false,'{"seq":16,"concept":"M4-2-u2-C9","difficulty":2,"kind":"ox","stem":"「이 단원 학습을 마치고」 — 정사각형은 네 변의 길이가 모두 같으므로 마름모라고 부를 수 있어요.","answer":"O","reason_options":[{"t":"마름모는 네 변의 길이가 모두 같은 사각형이라서","correct":true},{"t":"한 사각형은 이름이 하나뿐이라서","mis":"M4-2-u2-X17"}],"mis":"M4-2-u2-X17","explanation":["변의 길이를 기준으로 봐요.","정사각형은 네 변의 길이가 모두 같아요.","그래서 마름모라고도 불러요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#17','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',3,'error','auto','「수학에 퐁당」 — 정사각형에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X12','M4-2-u2-X18']::text[],false,'{"seq":17,"concept":"M4-2-u2-C9","difficulty":3,"kind":"error","stem":"「수학에 퐁당」 — 정사각형에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"지아 — 「정사각형은 마주 보는 두 각의 크기가 서로 달라.」","correct":true,"mis_target":"M4-2-u2-X12"},{"t":"민준 — 「정사각형은 마주 보는 두 쌍의 변이 서로 평행해.」","mis":"M4-2-u2-X18"},{"t":"정후 — 「정사각형은 네 변의 길이가 같아.」","mis":"M4-2-u2-X18"}],"explanation":["정사각형의 네 각은 모두 90°예요.","마주 보는 두 각도 같아요.","지아의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#18','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C3',3,'sa','auto','「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u2-C3","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 도형에서 변 ㄱㄴ과 평행한 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변 ㄱㄴ을 늘였을 때 만나지 않는 변을 찾아요.","변 ㅁㅂ, 변 ㄷㄹ이에요.","2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"pts":{"ㄱ":[15.0,15.0,"nw"],"ㄴ":[15.0,90.0,"sw"],"ㄷ":[120.0,90.0,"se"],"ㄹ":[120.0,52.5,"ne"],"ㅁ":[90.0,52.5,"sw"],"ㅂ":[90.0,15.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"right":[["ㅂ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㅁ"],["ㄹ","ㅁ","ㅂ"],["ㅁ","ㅂ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#19','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',3,'sa','auto','「스스로 마무리하기」 — 사각형 라는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 사각형 라는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["라는 네 변의 길이가 모두 같고 직각이 없어요.","사다리꼴, 평행사변형, 마름모예요.","3가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#20','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C7',3,'sa','auto','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄹㅁ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u2-C7","difficulty":3,"kind":"sa","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었어요. 선분 ㄹㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["사각형 ㄱㄴㅁㄹ은 평행사변형이에요.","선분 ㄹㅁ은 변 ㄱㄴ과 마주 봐요.","8 cm예요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#21','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',3,'ox','auto','「친구의 설명」 — 직사각형은 이웃한 두 변의 길이가 같아요.',ARRAY['M4-2-u2-X26']::text[],false,'{"seq":21,"concept":"M4-2-u2-C9","difficulty":3,"kind":"ox","stem":"「친구의 설명」 — 직사각형은 이웃한 두 변의 길이가 같아요.","answer":"X","reason_options":[{"t":"직사각형은 마주 보는 두 변의 길이가 같고 이웃한 두 변은 다를 수 있어서","correct":true},{"t":"직사각형은 네 변의 길이가 모두 같아서","mis":"M4-2-u2-X26"}],"mis":"M4-2-u2-X26","explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","이웃한 두 변은 길이가 다를 수 있어요.","이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":115.5,"h":66.0,"poly":[[[18.0,18.0],[97.5,18.0],[97.5,48.0],[18.0,48.0]]],"right":[[[18.0,48.0],[18.0,18.0],[97.5,18.0]],[[18.0,18.0],[97.5,18.0],[97.5,48.0]],[[97.5,18.0],[97.5,48.0],[18.0,48.0]],[[97.5,48.0],[18.0,48.0],[18.0,18.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#22','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C10',3,'ox','auto','「알지오매스로 마름모 그리기」 — 크기가 다른 두 원을 겹쳐 그리고 만나는 점과 두 원의 중심을 연결하면 마름모가 돼요.',ARRAY['M4-2-u2-X19']::text[],false,'{"seq":22,"concept":"M4-2-u2-C10","difficulty":3,"kind":"ox","stem":"「알지오매스로 마름모 그리기」 — 크기가 다른 두 원을 겹쳐 그리고 만나는 점과 두 원의 중심을 연결하면 마름모가 돼요.","answer":"X","reason_options":[{"t":"두 원의 반지름이 달라 길이가 다른 변이 생겨서","correct":true},{"t":"두 원이 만나기만 하면 마름모가 되어서","mis":"M4-2-u2-X19"}],"mis":"M4-2-u2-X19","explanation":["각 원의 중심과 만나는 점을 이은 선분은 그 원의 반지름이에요.","두 원의 반지름이 달라요.","이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":210,"h":138.0,"pts":{"ㄱ":[58.5,68.2,"w"],"ㄴ":[87.8,29.3,"n"],"ㄷ":[136.5,68.2,"e"],"ㄹ":[87.8,107.2,"s"]},"circle":[[[58.5,68.2],48.7],[[136.5,68.2],62.4]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#23','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C6',4,'essay','teacher','「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형이 평행사변형인 이유를 쓰고, 한 각이 130°일 때 이웃한 각의 크기를 구하는 방법을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u2-C6","difficulty":4,"kind":"essay","stem":"「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형이 평행사변형인 이유를 쓰고, 한 각이 130°일 때 이웃한 각의 크기를 구하는 방법을 써 보세요.","answer_guide":{"answer":"예: 두 직사각형은 각각 마주 보는 변이 평행하므로 겹친 사각형은 마주 보는 두 쌍의 변이 서로 평행한 평행사변형입니다. 평행사변형은 이웃한 두 각의 크기의 합이 180°이므로 이웃한 각은 180° − 130° = 50°입니다.","scoring_points":["마주 보는 두 쌍의 변이 평행하다고 썼는가","이웃한 두 각의 합이 180°라고 썼는가","50°를 구했는가"]},"explanation":["직사각형의 마주 보는 변은 평행해요.","겹친 사각형은 평행사변형이에요.","180 − 130 = 50이에요."],"asset":{"type":"geo","items":[{"w":143.8,"h":75.1,"poly":[[[50.8,18.0],[125.8,18.0],[93.0,57.1],[18.0,57.1]]],"lab":[[[57.1,31.6],"130°"],[[37.9,47.8],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#24','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',4,'sa','auto','「확인 문제」 — 한 변이 6 cm인 정사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u2-C9","difficulty":4,"kind":"sa","stem":"「확인 문제」 — 한 변이 6 cm인 정사각형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","6 cm가 4개예요.","6 × 4 = 24 — 24 cm예요."],"asset":{"type":"geo","items":[{"w":84.0,"h":84.0,"poly":[[[18.0,18.0],[66.0,18.0],[66.0,66.0],[18.0,66.0]]],"right":[[[18.0,66.0],[18.0,18.0],[66.0,18.0]],[[18.0,18.0],[66.0,18.0],[66.0,66.0]],[[66.0,18.0],[66.0,66.0],[18.0,66.0]],[[66.0,66.0],[18.0,66.0],[18.0,18.0]]],"lab":[[[42.0,6.7],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_b#25','math',4,2,'u2','','tb_g4_2_math_u2_review_b','unit_review','M4-2-u2-C9',4,'essay','teacher','「나의 성장 기록」 — 「사각형이 다양한 이름으로 불릴 수 있다」는 것을 정사각형을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C9","difficulty":4,"kind":"essay","stem":"「나의 성장 기록」 — 「사각형이 다양한 이름으로 불릴 수 있다」는 것을 정사각형을 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 정사각형은 평행한 변이 있으므로 사다리꼴, 마주 보는 두 쌍의 변이 평행하므로 평행사변형, 네 변의 길이가 모두 같으므로 마름모, 네 각이 모두 직각이므로 직사각형이라고도 부를 수 있습니다.","scoring_points":["평행한 변 기준의 이름을 썼는가","변의 길이 기준(마름모)을 썼는가","각의 크기 기준(직사각형)을 썼는가"]},"explanation":["기준마다 이름이 달라져요.","정사각형은 다섯 이름 모두 맞아요.","까닭을 조건으로 대어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#1','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C2',1,'mc','auto','「문제 척」 — 직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X03']::text[],false,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「문제 척」 — 직선 가에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 나, 직선 라","correct":true},{"t":"직선 나","mis":"M4-2-u2-X04"},{"t":"직선 다, 직선 마","mis":"M4-2-u2-X18"},{"t":"직선 나, 직선 다, 직선 라, 직선 마","mis":"M4-2-u2-X03"}],"explanation":["직선 가와 직각으로 만나는 직선을 찾아요.","직선 나와 직선 라예요.","직선 다·마는 직각으로 만나지 않아요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,82.5],[150.0,82.5]],[[30.0,0.0],[30.0,105.0]],[[52.5,0.0],[82.5,105.0]],[[105.0,0.0],[105.0,105.0]],[[142.5,0.0],[120.0,105.0]]],"lab":[[[13.5,93.8],"가"],[[18.8,13.5],"나"],[[67.0,9.9],"다"],[[116.2,13.5],"라"],[[133.8,94.2],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#2','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C3',1,'mc','auto','「확인 문제」 — 평행선을 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X23']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 평행선을 고른 것은 어느 것인가요?","options":[{"t":"직선 다와 직선 라","correct":true},{"t":"직선 가와 직선 나","mis":"M4-2-u2-X05"},{"t":"직선 나와 직선 다","mis":"M4-2-u2-X23"},{"t":"직선 나와 직선 라","mis":"M4-2-u2-X23"}],"explanation":["직선 다와 직선 라는 모두 직선 나에 수직이에요.","그래서 두 직선은 만나지 않아요.","직선 다와 직선 라가 평행선이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,105.0],[60.0,0.0]],[[0.0,60.0],[150.0,60.0]],[[82.5,0.0],[82.5,105.0]],[[120.0,0.0],[120.0,105.0]]],"lab":[[[30.7,97.0],"가"],[[13.5,48.8],"나"],[[93.8,13.5],"다"],[[131.2,13.5],"라"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#3','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C4',1,'sa','auto','「수학익힘」 — 직선 가와 나는 평행해요. 직선 가와 나 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「수학익힘」 — 직선 가와 나는 평행해요. 직선 가와 나 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","직각 표시가 있는 3 cm 선분이에요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":165,"h":105,"line":[[[0.0,15.0],[165.0,15.0]],[[0.0,82.5],[165.0,82.5]]],"seg":[[[24.0,15.0],[24.0,82.5]],[[72.0,15.0],[108.0,82.5]],[[123.0,15.0],[144.0,82.5]]],"lab":[[[6.8,26.2],"가"],[[6.8,93.8],"나"],[[43.5,48.8],"3 cm"],[[103.5,48.8],"4 cm"],[[147.0,48.8],"3.5 cm"]],"right":[[[24.0,15.0],[24.0,82.5],[39.0,82.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#4','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C9',1,'mc','auto','「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 직사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X27','M4-2-u2-X16']::text[],false,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 알맞은 사각형을 모두 찾아요. 직사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"마","mis":"M4-2-u2-X17"},{"t":"나, 다, 마","mis":"M4-2-u2-X27"},{"t":"다, 라, 마","mis":"M4-2-u2-X16"}],"explanation":["네 각이 모두 직각인지 확인해요.","다(정사각형)와 마가 직사각형이에요.","나는 평행한 변이 두 쌍이지만 직각이 없어요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#5','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',1,'sa','auto','「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 두 선분을 이었어요. 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 두 선분을 이었어요. 두 선분이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나요.","수직이면 직각이에요.","90°예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":117.0,"poly":[[[72.0,18.0],[126.0,58.5],[72.0,99.0],[18.0,58.5]]],"lab":[[[35.2,25.2],"5 cm"],[[45.0,49.5],"4 cm"],[[59.2,78.8],"3 cm"],[[99.0,69.8],"?"],[[84.7,38.3],"?"]],"seg":[[[72.0,18.0],[72.0,99.0]],[[126.0,58.5],[18.0,58.5]]],"right":[[[72.0,18.0],[72.0,58.5],[126.0,58.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#6','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C5',1,'mc','auto','「수학익힘」 — 주어진 변과 연결하여 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X18','M4-2-u2-X10']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 주어진 변과 연결하여 사다리꼴을 만들 수 있는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠","mis":"M4-2-u2-X04"},{"t":"㉡, ㉢","mis":"M4-2-u2-X18"},{"t":"㉠, ㉡, ㉣","mis":"M4-2-u2-X10"}],"explanation":["평행한 변이 한 쌍이라도 생기는 점을 찾아요.","㉠은 위쪽 변이, ㉣은 오른쪽 변이 평행해져요.","㉡·㉢을 이으면 평행한 변이 없어요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"㉠":[67.5,15.0,"n"],"㉡":[90.0,33.0,"n"],"㉢":[45.0,12.0,"n"],"㉣":[105.0,45.0,"n"]},"seg":[[[15.0,15.0],[15.0,90.0]],[[15.0,90.0],[105.0,90.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#7','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C6',1,'mc','auto','「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형의 이름으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X27','M4-2-u2-X14','M4-2-u2-X16']::text[],false,'{"seq":7,"concept":"M4-2-u2-C6","difficulty":1,"kind":"mc","stem":"「수학익힘」 — 두 직사각형을 겹쳤을 때 생긴 사각형의 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"직사각형","mis":"M4-2-u2-X27"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X16"}],"explanation":["두 직사각형의 마주 보는 변은 각각 평행해요.","겹친 사각형은 마주 보는 두 쌍의 변이 서로 평행해요.","직각은 없으니 평행사변형이에요."],"asset":{"type":"geo","items":[{"w":143.8,"h":75.1,"poly":[[[50.8,18.0],[125.8,18.0],[93.0,57.1],[18.0,57.1]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#8','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',1,'sa','auto','「추론」 — 마름모의 네 변의 길이의 합이 48 cm예요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「추론」 — 마름모의 네 변의 길이의 합이 48 cm예요. 마름모의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","48을 4로 나눠요.","48 ÷ 4 = 12 — 12 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#9','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',2,'mc','auto','「이 단원 학습을 마치고」 — 사각형을 변의 길이로도 분류할 수 있어요. 네 변의 길이가 모두 같은 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X17','M4-2-u2-X14','M4-2-u2-X18']::text[],false,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 — 사각형을 변의 길이로도 분류할 수 있어요. 네 변의 길이가 모두 같은 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 바","correct":true},{"t":"가","mis":"M4-2-u2-X17"},{"t":"가, 나, 바","mis":"M4-2-u2-X14"},{"t":"나, 다, 라, 마","mis":"M4-2-u2-X18"}],"explanation":["자로 네 변을 재어 봐요.","가와 바(정사각형)예요.","나머지는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[7.5,52.5],[52.5,30.0],[97.5,52.5],[52.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[240.0,19.5],[277.5,19.5],[285.0,81.0],[247.5,81.0]],[[7.5,142.5],[82.5,123.0],[97.5,142.5],[82.5,162.0]],[[135.0,112.5],[180.0,112.5],[202.5,165.0],[112.5,165.0]],[[240.0,120.0],[285.0,120.0],[285.0,165.0],[240.0,165.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,11.2],"다"],[[52.5,114.7],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#10','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',2,'mc','auto','「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 우리 집의 모양으로 가장 알맞은 이름은 무엇인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X10','M4-2-u2-X14']::text[],false,'{"seq":10,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 우리 집의 모양으로 가장 알맞은 이름은 무엇인가요?","options":[{"t":"마름모","correct":true},{"t":"정사각형","mis":"M4-2-u2-X16"},{"t":"직사각형","mis":"M4-2-u2-X10"},{"t":"경찰서와 같은 평행사변형 모양","mis":"M4-2-u2-X14"}],"explanation":["우리 집은 두 쌍의 변이 평행하고 네 변의 길이가 모두 같아요.","하지만 네 각의 크기는 모두 같지 않아요.","네 변의 길이가 모두 같은 사각형 — 마름모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#11','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',2,'sa','auto','마름모의 한 각이 50°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u2-C8","difficulty":2,"kind":"sa","stem":"마름모의 한 각이 50°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["이웃한 두 각의 크기의 합은 180°예요.","180 − 50 = 130이에요.","130°예요."],"asset":{"type":"geo","items":[{"w":117.3,"h":73.9,"poly":[[[49.8,18.0],[99.3,18.0],[67.5,55.9],[18.0,55.9]]],"lab":[[[37.9,46.6],"50°"],[[61.2,42.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#12','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C4',2,'sa','auto','「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 가장 짧은 선분이 3 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M4-2-u2-C4","difficulty":2,"kind":"sa","stem":"「생각 톡」 — 점 ㄱ에서 직선 나에 그은 선분 가운데 가장 짧은 선분이 3 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가장 짧은 선분은 수직인 선분이에요.","수직인 선분의 길이가 거리예요.","3 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,82.5],[150.0,82.5]]],"seg":[[[75.0,22.5],[75.0,82.5]],[[75.0,22.5],[22.5,82.5]],[[75.0,22.5],[112.5,82.5]],[[75.0,22.5],[138.0,82.5]]],"lab":[[[6.8,33.8],"가"],[[6.8,93.8],"나"]],"right":[[[75.0,22.5],[75.0,82.5],[90.0,82.5]]],"pts":{"ㄱ":[75.0,22.5,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#13','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C7',2,'match','auto','평행사변형의 성질에 맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"M4-2-u2-C7","difficulty":2,"kind":"match","stem":"평행사변형의 성질에 맞게 이으세요.","pairs":[{"l":"마주 보는 두 변","r":"길이가 같아요"},{"l":"마주 보는 두 각","r":"크기가 같아요"},{"l":"이웃한 두 각","r":"크기의 합이 180°예요"}],"mis":"M4-2-u2-X12","explanation":["자와 각도기로 확인한 성질이에요.","마주 보는 변·각은 같아요.","이웃한 두 각의 합은 180°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#14','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C4',2,'mc','auto','「문제 척」 — 평행선 사이의 거리가 3 cm인 평행선을 완성하는 바른 방법은 어느 것인가요?',ARRAY['M4-2-u2-X24','M4-2-u2-X07']::text[],false,'{"seq":14,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「문제 척」 — 평행선 사이의 거리가 3 cm인 평행선을 완성하는 바른 방법은 어느 것인가요?","options":[{"t":"한 삼각자를 고정하고 다른 삼각자를 주어진 직선과 수직인 방향으로 3 cm만큼 움직여 그어요","correct":true},{"t":"두 삼각자를 함께 3 cm만큼 움직여 그어요","mis":"M4-2-u2-X24"},{"t":"비스듬히 3 cm 선분을 긋고 그 끝에서 나란해 보이게 그어요","mis":"M4-2-u2-X07"},{"t":"3 cm 떨어진 점 하나만 찍고 아무 방향으로 그어요","mis":"M4-2-u2-X24"}],"explanation":["평행선 사이의 거리는 수직인 방향으로 재요.","한 삼각자를 고정하고 다른 삼각자를 3 cm만큼 움직여요.","그래서 거리가 3 cm인 평행선이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#15','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C10',2,'mc','auto','「알지오매스로 마름모 그리기」 — 원 두 개를 서로 겹치게 그린 다음에 할 일은 무엇인가요?',ARRAY['M4-2-u2-X18','M4-2-u2-X19']::text[],false,'{"seq":15,"concept":"M4-2-u2-C10","difficulty":2,"kind":"mc","stem":"「알지오매스로 마름모 그리기」 — 원 두 개를 서로 겹치게 그린 다음에 할 일은 무엇인가요?","options":[{"t":"두 원이 서로 만나는 점을 찍어요","correct":true},{"t":"원을 잡고 움직이며 여러 가지 마름모를 관찰해요","mis":"M4-2-u2-X18"},{"t":"원 하나를 지워요","mis":"M4-2-u2-X19"},{"t":"두 원의 중심끼리만 연결해요","mis":"M4-2-u2-X19"}],"explanation":["① 원 두 개를 겹치게 그려요.","② 두 원이 서로 만나는 점을 찍어요.","③ 만나는 점과 두 원의 중심을 연결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#16','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C5',2,'ox','auto','「헷갈려요」 — 평행한 변이 두 쌍인 사각형은 사다리꼴이라고 할 수 없어요.',ARRAY['M4-2-u2-X09']::text[],false,'{"seq":16,"concept":"M4-2-u2-C5","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 평행한 변이 두 쌍인 사각형은 사다리꼴이라고 할 수 없어요.","answer":"X","reason_options":[{"t":"평행한 변이 한 쌍이라도 있으면 사다리꼴이라서","correct":true},{"t":"사다리꼴은 평행한 변이 한 쌍만 있어야 해서","mis":"M4-2-u2-X09"}],"mis":"M4-2-u2-X09","explanation":["사다리꼴은 평행한 변이 「한 쌍이라도」 있는 사각형이에요.","두 쌍이어도 그 조건을 만족해요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#17','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C5',3,'error','auto','「헷갈려요」 — 사다리꼴에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X09','M4-2-u2-X18']::text[],false,'{"seq":17,"concept":"M4-2-u2-C5","difficulty":3,"kind":"error","stem":"「헷갈려요」 — 사다리꼴에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"은비 — 「평행한 변이 두 쌍이면 사다리꼴이 아니야.」","correct":true,"mis_target":"M4-2-u2-X09"},{"t":"건우 — 「평행한 변이 한 쌍이라도 있으면 사다리꼴이야.」","mis":"M4-2-u2-X18"},{"t":"서윤 — 「직사각형도 평행한 변이 있으니 사다리꼴이야.」","mis":"M4-2-u2-X18"}],"explanation":["사다리꼴은 평행한 변이 한 쌍이라도 있는 사각형이에요.","두 쌍이어도 사다리꼴이에요.","은비의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#18','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C1',3,'sa','auto','「수학익힘」 — 그림에서 선분 ㄱㄷ과 서로 수직인 선분은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u2-C1","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 그림에서 선분 ㄱㄷ과 서로 수직인 선분은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분 ㄱㄷ과 직각으로 만나는 선분을 찾아요.","선분 ㄱㄴ과 선분 ㅁㄹ이에요.","2개예요."],"asset":{"type":"geo","items":[{"w":195,"h":96.0,"pts":{"ㄱ":[42.0,15.0,"n"],"ㄴ":[4.5,90.0,"w"],"ㄷ":[192.0,90.0,"e"],"ㅁ":[42.0,90.0,"s"],"ㄹ":[72.0,30.0,"ne"],"ㅂ":[117.0,52.5,"ne"]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄱ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㄹ"],["ㅁ","ㅂ"]],"right":[["ㄴ","ㄱ","ㄷ"],["ㄴ","ㅁ","ㄱ"],["ㅁ","ㄹ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#19','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C9',3,'sa','auto','「스스로 마무리하기」 — 사각형 마는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 사각형 마는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["마는 네 각이 모두 직각이고 길이가 다른 변이 있어요.","사다리꼴, 평행사변형, 직사각형이에요.","3가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#20','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',3,'sa','auto','「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 6 cm, 8 cm예요. 8 cm를 반으로 하는 선분 전체는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"「수학익힘」 — 한 변이 10 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 6 cm, 8 cm예요. 8 cm를 반으로 하는 선분 전체는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["두 선분은 서로를 반으로 나눠요.","8 + 8이에요.","16 cm예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":108.0,"poly":[[[66.0,18.0],[114.0,54.0],[66.0,90.0],[18.0,54.0]]],"lab":[[[31.5,22.0],"10 cm"],[[78.8,36.0],"6 cm"],[[42.0,45.0],"8 cm"],[[53.3,72.0],"?"],[[90.0,65.2],"?"]],"seg":[[[66.0,18.0],[66.0,90.0]],[[114.0,54.0],[18.0,54.0]]],"right":[[[66.0,18.0],[66.0,54.0],[114.0,54.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#21','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C4',3,'ox','auto','「꼭 알아 둬요」 — 평행선 사이의 거리를 잴 때 선분이 평행선에 닿지 않아도 비슷하게만 재면 돼요.',ARRAY['M4-2-u2-X22']::text[],false,'{"seq":21,"concept":"M4-2-u2-C4","difficulty":3,"kind":"ox","stem":"「꼭 알아 둬요」 — 평행선 사이의 거리를 잴 때 선분이 평행선에 닿지 않아도 비슷하게만 재면 돼요.","answer":"X","reason_options":[{"t":"선분의 두 끝이 두 평행선에 꼭 닿아야 거리가 되어서","correct":true},{"t":"대강 비슷한 길이만 알면 되어서","mis":"M4-2-u2-X22"}],"mis":"M4-2-u2-X22","explanation":["평행선 사이의 거리는 한 직선에서 다른 직선까지의 수직인 선분이에요.","닿지 않거나 지나치면 길이가 달라져요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#22','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C10',3,'mc','auto','「생각해 봐요」 — 크기가 다른 두 원으로 마름모를 그리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X15']::text[],false,'{"seq":22,"concept":"M4-2-u2-C10","difficulty":3,"kind":"mc","stem":"「생각해 봐요」 — 크기가 다른 두 원으로 마름모를 그리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원의 중심을 맞춰 그리고, 작은 원의 지름과 그 지름에 수직이면서 원의 중심을 지나는 큰 원의 지름을 그은 뒤 네 끝점을 이어요","correct":true},{"t":"두 원을 조금만 겹쳐 그리고 만나는 점과 두 중심을 이어요","mis":"M4-2-u2-X19"},{"t":"두 원을 떨어뜨려 그리고 두 중심을 이어요","mis":"M4-2-u2-X19"},{"t":"큰 원의 지름 두 개를 비스듬히 긋고 끝점을 이어요","mis":"M4-2-u2-X15"}],"explanation":["원의 중심을 맞추면 두 지름이 원의 중심에서 만나요.","두 지름은 수직으로 만나고 서로를 반으로 나눠요.","그 끝점을 이으면 마름모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#23','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C5',4,'essay','teacher','「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ의 이름을 쓰고, 그렇게 생각한 이유를 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u2-C5","difficulty":4,"kind":"essay","stem":"「서술형」 — 직사각형과 사다리꼴을 겹쳐서 만든 사각형 ㄱㄴㄷㄹ의 이름을 쓰고, 그렇게 생각한 이유를 써 보세요.","answer_guide":{"answer":"예: 사다리꼴. 직사각형과 사다리꼴을 겹친 것이므로 변 ㄱㄹ과 변 ㄴㄷ은 평행합니다. 사각형 ㄱㄴㄷㄹ은 평행한 변이 한 쌍이라도 있는 사각형이므로 사다리꼴입니다.","scoring_points":["사다리꼴이라고 썼는가","변 ㄱㄹ과 변 ㄴㄷ이 평행하다고 썼는가","평행한 변이 한 쌍이라도 있어 사다리꼴이라고 썼는가"]},"explanation":["직사각형의 마주 보는 변은 평행해요.","변 ㄱㄹ과 변 ㄴㄷ이 평행해요.","그래서 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"pts":{"ㄱ":[45.0,30.0,"nw"],"ㄴ":[60.0,75.0,"sw"],"ㄷ":[90.0,75.0,"se"],"ㄹ":[90.0,30.0,"ne"]},"poly":[[[15.0,30.0],[135.0,30.0],[135.0,75.0],[15.0,75.0]],[[37.5,7.5],[90.0,7.5],[90.0,97.5],[67.5,97.5]]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#24','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C8',4,'sa','auto','「수학익힘」 — 한 변이 9 cm인 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u2-C8","difficulty":4,"kind":"sa","stem":"「수학익힘」 — 한 변이 9 cm인 마름모의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","9 cm가 4개예요.","9 × 4 = 36 — 36 cm예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":86.7,"poly":[[[36.5,18.0],[90.5,18.0],[72.0,68.7],[18.0,68.7]]],"lab":[[[63.5,6.7],"9 cm"],[[99.2,49.9],"? cm"],[[45.1,30.3],"110°"],[[77.2,27.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_c#25','math',4,2,'u2','','tb_g4_2_math_u2_review_c','unit_review','M4-2-u2-C3',4,'essay','teacher','「생각해 봐요」 — 생활 속에서 찾은 두 직선이 평행선인지 확인하는 방법을 「공통의 수선」이라는 말을 넣어 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C3","difficulty":4,"kind":"essay","stem":"「생각해 봐요」 — 생활 속에서 찾은 두 직선이 평행선인지 확인하는 방법을 「공통의 수선」이라는 말을 넣어 써 보세요.","answer_guide":{"answer":"예: 두 직선에 공통으로 수직인 직선(공통의 수선)을 그어 봅니다. 두 직선이 모두 그 직선과 수직으로 만나면 두 직선은 만나지 않으므로 평행선입니다. 또는 두 직선을 양쪽으로 늘여 만나는지 확인합니다.","scoring_points":["공통의 수선을 긋는다고 썼는가","두 직선이 모두 수직이면 만나지 않는다고 썼는가","그래서 평행선이라고 썼는가"]},"explanation":["직관만으로 판단하지 않아요.","공통의 수선이 있으면 두 직선은 만나지 않아요.","그래서 평행선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#1','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C2',1,'mc','auto','「확인 문제」 — 직선 나에 대한 수선을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X04','M4-2-u2-X03']::text[],false,'{"seq":1,"concept":"M4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 직선 나에 대한 수선을 모두 고른 것은 어느 것인가요?","options":[{"t":"직선 다, 직선 라","correct":true},{"t":"직선 다","mis":"M4-2-u2-X04"},{"t":"직선 가","mis":"M4-2-u2-X03"},{"t":"직선 가, 직선 다, 직선 라","mis":"M4-2-u2-X03"}],"explanation":["직선 나와 직각으로 만나는 직선을 찾아요.","직선 다와 직선 라예요.","직선 가는 비스듬히 만나요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"line":[[[15.0,105.0],[60.0,0.0]],[[0.0,60.0],[150.0,60.0]],[[82.5,0.0],[82.5,105.0]],[[120.0,0.0],[120.0,105.0]]],"lab":[[[30.7,97.0],"가"],[[13.5,48.8],"나"],[[93.8,13.5],"다"],[[131.2,13.5],"라"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#2','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C3',1,'mc','auto','「생각 톡」 — 자전거 도로와 인도의 선에서 서로 평행한 직선을 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X05','M4-2-u2-X23']::text[],false,'{"seq":2,"concept":"M4-2-u2-C3","difficulty":1,"kind":"mc","stem":"「생각 톡」 — 자전거 도로와 인도의 선에서 서로 평행한 직선을 고른 것은 어느 것인가요?","options":[{"t":"직선 가와 직선 나","correct":true},{"t":"직선 가와 직선 다","mis":"M4-2-u2-X05"},{"t":"직선 나와 직선 다","mis":"M4-2-u2-X05"},{"t":"직선 가와 직선 ㉠","mis":"M4-2-u2-X23"}],"explanation":["직선 가와 직선 나는 모두 직선 ㉠에 수직이에요.","그래서 끝없이 늘여도 만나지 않아요.","직선 가와 직선 나가 평행해요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"line":[[[0.0,22.5],[150.0,22.5]],[[0.0,52.5],[150.0,52.5]],[[0.0,97.5],[150.0,75.0]],[[45.0,0.0],[45.0,105.0]]],"lab":[[[13.5,33.8],"가"],[[136.5,41.2],"나"],[[11.7,84.4],"다"],[[56.2,69.0],"㉠"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#3','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C4',1,'sa','auto','「확인 문제」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 긋고 재었더니 2 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u2-C4","difficulty":1,"kind":"sa","stem":"「확인 문제」 — 평행선의 한 직선에서 다른 직선에 수직인 선분을 긋고 재었더니 2 cm였어요. 평행선 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","수직인 선분이 2 cm예요.","2 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#4','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C9',1,'mc','auto','「스스로 마무리하기」 — 알맞은 사각형을 찾아요. 정사각형을 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X17']::text[],false,'{"seq":4,"concept":"M4-2-u2-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 알맞은 사각형을 찾아요. 정사각형을 고른 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"라","mis":"M4-2-u2-X16"},{"t":"마","mis":"M4-2-u2-X16"},{"t":"다, 라, 마","mis":"M4-2-u2-X17"}],"explanation":["네 변의 길이가 모두 같고 네 각이 모두 직각인지 확인해요.","다(세워 놓은 정사각형)만 두 조건을 모두 갖췄어요.","라는 직각이 없고, 마는 길이가 다른 변이 있어요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#5','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',1,'sa','auto','「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 선분의 아래쪽 반이 3 cm예요. 위쪽 반(?)은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u2-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 선분의 아래쪽 반이 3 cm예요. 위쪽 반(?)은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 선분은 서로를 반으로 나눠요.","아래쪽 반이 3 cm이면 위쪽 반도 3 cm예요.","3 cm예요 — 5 cm는 변의 길이예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":117.0,"poly":[[[72.0,18.0],[126.0,58.5],[72.0,99.0],[18.0,58.5]]],"lab":[[[35.2,25.2],"5 cm"],[[45.0,49.5],"4 cm"],[[59.2,78.8],"3 cm"],[[99.0,69.8],"?"],[[84.7,38.3],"?"]],"seg":[[[72.0,18.0],[72.0,99.0]],[[126.0,58.5],[18.0,58.5]]],"right":[[[72.0,18.0],[72.0,58.5],[126.0,58.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#6','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C5',1,'mc','auto','「스스로 마무리하기」 — 주어진 변과 점 가를 연결하여 만든 사각형이 사다리꼴인 이유는 무엇인가요?',ARRAY['M4-2-u2-X10','M4-2-u2-X14']::text[],false,'{"seq":6,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 주어진 변과 점 가를 연결하여 만든 사각형이 사다리꼴인 이유는 무엇인가요?","options":[{"t":"평행한 변이 한 쌍이라도 있기 때문이에요","correct":true},{"t":"네 각이 모두 직각이라서예요","mis":"M4-2-u2-X10"},{"t":"네 변의 길이가 모두 같아서예요","mis":"M4-2-u2-X14"},{"t":"사다리처럼 생겨서예요","mis":"M4-2-u2-X10"}],"explanation":["점 가를 이으면 위쪽 변이 아래쪽 변과 평행해요.","평행한 변이 한 쌍 생겨요.","그래서 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":150,"h":112.5,"grid":15,"pts":{"가":[52.5,30.0,"n"],"나":[75.0,12.0,"n"],"다":[82.5,51.0,"n"],"라":[112.5,30.0,"n"]},"seg":[[[15.0,30.0],[15.0,97.5]],[[15.0,97.5],[135.0,97.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#7','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C5',1,'mc','auto','「수학 되돌아보기」 — 서현이의 도시 안내도에서 학교는 마주 보는 한 쌍의 변만 평행하게 그려져 있어요. 학교는 어떤 모양인가요?',ARRAY['M4-2-u2-X16','M4-2-u2-X10','M4-2-u2-X14']::text[],false,'{"seq":7,"concept":"M4-2-u2-C5","difficulty":1,"kind":"mc","stem":"「수학 되돌아보기」 — 서현이의 도시 안내도에서 학교는 마주 보는 한 쌍의 변만 평행하게 그려져 있어요. 학교는 어떤 모양인가요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M4-2-u2-X16"},{"t":"직사각형","mis":"M4-2-u2-X10"},{"t":"마름모","mis":"M4-2-u2-X14"}],"explanation":["평행한 변이 몇 쌍인지 봐요.","학교는 평행한 변이 한 쌍이에요.","평행한 변이 한 쌍이라도 있으니 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#8','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',1,'sa','auto','「문제 해결」 — 평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 40 cm이고 변 ㄱㄹ은 15 cm예요. 변 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u2-C7","difficulty":1,"kind":"sa","stem":"「문제 해결」 — 평행사변형 ㄱㄴㄷㄹ의 네 변의 길이의 합은 40 cm이고 변 ㄱㄹ은 15 cm예요. 변 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["변 ㄴㄷ도 15 cm예요.","40 − 15 − 15 = 10이에요.","10을 둘로 나누면 5 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":127.5,"h":64.6,"pts":{"ㄱ":[34.5,18.0,"nw"],"ㄹ":[109.5,18.0,"e"],"ㄷ":[93.0,46.6,"se"],"ㄴ":[18.0,46.6,"w"]},"poly":[["ㄱ","ㄹ","ㄷ","ㄴ"]],"lab":[[[72.0,6.7],"15 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#9','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',2,'mc','auto','「이 단원 학습을 마치고」 — 사각형을 변의 길이로 분류했어요. 길이가 다른 변이 있는 사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u2-X14','M4-2-u2-X17','M4-2-u2-X18']::text[],false,'{"seq":9,"concept":"M4-2-u2-C8","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 — 사각형을 변의 길이로 분류했어요. 길이가 다른 변이 있는 사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다, 라, 마","correct":true},{"t":"라, 마","mis":"M4-2-u2-X14"},{"t":"나, 다, 라, 마, 바","mis":"M4-2-u2-X17"},{"t":"가, 바","mis":"M4-2-u2-X18"}],"explanation":["네 변의 길이가 모두 같은지 아닌지 봐요.","나, 다, 라, 마는 길이가 다른 변이 있어요.","가와 바는 네 변의 길이가 모두 같아요."],"asset":{"type":"geo","items":[{"w":315,"h":180,"grid":15,"poly":[[[7.5,52.5],[52.5,30.0],[97.5,52.5],[52.5,75.0]],[[135.0,22.5],[202.5,22.5],[180.0,75.0],[112.5,75.0]],[[240.0,19.5],[277.5,19.5],[285.0,81.0],[247.5,81.0]],[[7.5,142.5],[82.5,123.0],[97.5,142.5],[82.5,162.0]],[[135.0,112.5],[180.0,112.5],[202.5,165.0],[112.5,165.0]],[[240.0,120.0],[285.0,120.0],[285.0,165.0],[240.0,165.0]]],"lab":[[[52.5,21.8],"가"],[[157.5,14.2],"나"],[[262.5,11.2],"다"],[[52.5,114.7],"라"],[[157.5,104.2],"마"],[[262.5,111.8],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#10','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C6',2,'mc','auto','「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 경찰서의 모양으로 가장 알맞은 이름은 무엇인가요?',ARRAY['M4-2-u2-X27','M4-2-u2-X14','M4-2-u2-X16']::text[],false,'{"seq":10,"concept":"M4-2-u2-C6","difficulty":2,"kind":"mc","stem":"「수학 되돌아보기」 — 서현이의 도시 안내도에서 경찰서·시청·백화점·우리 집은 두 쌍의 변이 모두 평행하게, 시청·우리 집은 네 변의 길이가 모두 같게, 시청·백화점은 네 각의 크기가 모두 같게 그려져 있어요. 경찰서의 모양으로 가장 알맞은 이름은 무엇인가요?","options":[{"t":"평행사변형","correct":true},{"t":"직사각형","mis":"M4-2-u2-X27"},{"t":"마름모","mis":"M4-2-u2-X14"},{"t":"정사각형","mis":"M4-2-u2-X16"}],"explanation":["경찰서는 두 쌍의 변이 모두 평행해요.","네 변의 길이도, 네 각의 크기도 모두 같지는 않아요.","평행사변형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#11','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',2,'sa','auto','평행사변형의 한 각이 70°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M4-2-u2-C7","difficulty":2,"kind":"sa","stem":"평행사변형의 한 각이 70°예요. 이 각과 이웃한 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["이웃한 두 각의 크기의 합은 180°예요.","180 − 70 = 110이에요.","110°예요."],"asset":{"type":"geo","items":[{"w":129.5,"h":86.7,"poly":[[[36.5,18.0],[111.5,18.0],[93.0,68.7],[18.0,68.7]]],"lab":[[[98.2,27.3],"70°"],[[45.1,30.3],"?"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#12','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C4',2,'mc','auto','「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 평행해요. 평행선 사이의 거리를 재려면 어느 변을 재어야 하나요?',ARRAY['M4-2-u2-X07','M4-2-u2-X23']::text[],false,'{"seq":12,"concept":"M4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「수학익힘」 — 사각형 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 변 ㄹㄷ은 평행해요. 평행선 사이의 거리를 재려면 어느 변을 재어야 하나요?","options":[{"t":"변 ㄱㄹ","correct":true},{"t":"변 ㄴㄷ","mis":"M4-2-u2-X07"},{"t":"변 ㄱㄴ","mis":"M4-2-u2-X23"},{"t":"변 ㄹㄷ","mis":"M4-2-u2-X23"}],"explanation":["두 평행한 변에 모두 수직인 변을 찾아요.","각 ㄱ과 각 ㄹ이 직각이에요.","변 ㄱㄹ을 재요."],"asset":{"type":"geo","items":[{"w":126.0,"h":90.0,"pts":{"ㄱ":[18.0,18.0,"nw"],"ㄴ":[18.0,72.0,"sw"],"ㄷ":[108.0,45.0,"e"],"ㄹ":[108.0,18.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄹ","ㄱ","ㄴ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#13','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C4',2,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],false,'{"seq":13,"concept":"M4-2-u2-C4","difficulty":2,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"평행선 사이의 거리","r":"한 직선에서 다른 직선에 그은 수직인 선분의 길이"},{"l":"평행","r":"한 직선에 수직인 두 직선처럼 서로 만나지 않는 관계"},{"l":"수선","r":"다른 직선과 수직으로 만나는 직선"}],"mis":"M4-2-u2-X02","explanation":["평행선 사이의 거리는 수직인 선분의 길이예요.","평행은 만나지 않는 관계예요.","수선은 수직으로 만나는 직선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#14','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C2',2,'mc','auto','「개념 톡」 — 각도기와 자로 수선을 그어요. 각도기의 중심을 직선 위의 점에, 밑금을 직선에 맞춘 다음 몇 도가 되는 곳에 점을 표시하나요?',ARRAY['M4-2-u2-X03']::text[],false,'{"seq":14,"concept":"M4-2-u2-C2","difficulty":2,"kind":"mc","stem":"「개념 톡」 — 각도기와 자로 수선을 그어요. 각도기의 중심을 직선 위의 점에, 밑금을 직선에 맞춘 다음 몇 도가 되는 곳에 점을 표시하나요?","options":[{"t":"90°","correct":true},{"t":"180°","mis":"M4-2-u2-X03"},{"t":"45°","mis":"M4-2-u2-X03"},{"t":"60°","mis":"M4-2-u2-X03"}],"explanation":["수선은 직선과 직각으로 만나요.","직각은 90°예요.","90°가 되는 곳에 점을 표시하고 두 점을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#15','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C5',2,'mc','auto','「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그려요. 직선을 그린 다음에 할 일은 무엇인가요?',ARRAY['M4-2-u2-X23','M4-2-u2-X19','M4-2-u2-X14']::text[],false,'{"seq":15,"concept":"M4-2-u2-C5","difficulty":2,"kind":"mc","stem":"「수학과 공학 도구」 — 알지오매스 키즈로 사다리꼴을 그려요. 직선을 그린 다음에 할 일은 무엇인가요?","options":[{"t":"그 직선과 평행한 직선을 그려요","correct":true},{"t":"그 직선에 수직인 직선을 그려요","mis":"M4-2-u2-X23"},{"t":"크기가 같은 원 두 개를 그려요","mis":"M4-2-u2-X19"},{"t":"길이가 같은 선분 네 개를 그려요","mis":"M4-2-u2-X14"}],"explanation":["① 직선, ② 평행선을 그려요.","③ 평행선 위에 점을 찍고 ④ 선분으로 사각형을 만들어요.","평행한 변이 생기니 사다리꼴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#16','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C6',2,'ox','auto','「헷갈려요」 — 평행사변형은 반드시 비스듬한 두 변이 있어야 해요.',ARRAY['M4-2-u2-X11']::text[],false,'{"seq":16,"concept":"M4-2-u2-C6","difficulty":2,"kind":"ox","stem":"「헷갈려요」 — 평행사변형은 반드시 비스듬한 두 변이 있어야 해요.","answer":"X","reason_options":[{"t":"직사각형처럼 비스듬한 변이 없어도 마주 보는 두 쌍의 변이 평행하면 평행사변형이라서","correct":true},{"t":"평행사변형은 기울어져 있어야 해서","mis":"M4-2-u2-X11"}],"mis":"M4-2-u2-X11","explanation":["평행사변형은 평행한 변으로 정해요.","직사각형도 마주 보는 두 쌍의 변이 평행해요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#17','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',3,'error','auto','「친구의 설명」 — 마름모의 성질을 확인했어요. 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X25','M4-2-u2-X18']::text[],false,'{"seq":17,"concept":"M4-2-u2-C8","difficulty":3,"kind":"error","stem":"「친구의 설명」 — 마름모의 성질을 확인했어요. 잘못 말한 사람은 누구인가요?","options":[{"t":"도윤 — 「삼각자를 대어 보니 마름모는 평행한 변이 없어.」","correct":true,"mis_target":"M4-2-u2-X25"},{"t":"서윤 — 「마주 보는 두 각의 크기가 같아.」","mis":"M4-2-u2-X18"},{"t":"채원 — 「마주 보는 꼭짓점끼리 이은 두 선분은 서로 수직으로 만나.」","mis":"M4-2-u2-X18"}],"explanation":["마름모는 마주 보는 두 쌍의 변이 평행해요.","삼각자를 바르게 대고 다시 확인해요.","도윤이의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#18','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C3',3,'sa','auto','「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u2-C3","difficulty":3,"kind":"sa","stem":"「추론」 — 글자 ㄱ, ㄴ, ㅁ, ㅂ, ㅋ, ㅍ 가운데 평행선이 있는 글자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["서로 만나지 않는 두 획을 찾아요.","ㅁ, ㅂ, ㅋ, ㅍ이에요.","4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#19','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C9',3,'sa','auto','「스스로 마무리하기」 — 사각형 나는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u2-C9","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 사각형 나는 다섯 이름(사다리꼴, 평행사변형, 마름모, 직사각형, 정사각형) 가운데 몇 가지 이름으로 부를 수 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["나는 마주 보는 두 쌍의 변이 평행해요.","네 변이 같지도, 직각이지도 않아요.","사다리꼴, 평행사변형 — 2가지예요."],"asset":{"type":"geo","items":[{"w":525,"h":90,"grid":15,"poly":[[[7.5,22.5],[97.5,22.5],[67.5,75.0],[37.5,75.0]],[[112.5,22.5],[172.5,22.5],[202.5,75.0],[142.5,75.0]],[[262.5,18.0],[295.5,51.0],[262.5,84.0],[229.5,51.0]],[[367.5,18.0],[390.0,51.0],[367.5,84.0],[345.0,51.0]],[[450.0,18.0],[495.0,18.0],[495.0,84.0],[450.0,84.0]]],"lab":[[[52.5,14.2],"가"],[[157.5,14.2],"나"],[[262.5,9.7],"다"],[[367.5,9.7],"라"],[[472.5,9.7],"마"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#20','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',3,'sa','auto','「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 4 cm, 3 cm예요. 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u2-C8","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 — 한 변이 5 cm인 마름모에서 마주 보는 꼭짓점끼리 이은 두 선분의 반이 4 cm, 3 cm예요. 두 선분의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["두 선분은 서로를 반으로 나눠요 — 한 선분은 4 + 4 = 8(cm).","다른 선분은 3 + 3 = 6(cm)이에요.","8 + 6 = 14 — 14 cm예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":117.0,"poly":[[[72.0,18.0],[126.0,58.5],[72.0,99.0],[18.0,58.5]]],"lab":[[[35.2,25.2],"5 cm"],[[45.0,49.5],"4 cm"],[[59.2,78.8],"3 cm"],[[99.0,69.8],"?"],[[84.7,38.3],"?"]],"seg":[[[72.0,18.0],[72.0,99.0]],[[126.0,58.5],[18.0,58.5]]],"right":[[[72.0,18.0],[72.0,58.5],[126.0,58.5]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#21','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C2',3,'ox','auto','「궁금해요」 — 수직인 직선을 줄여서 수직선이라고 불러요.',ARRAY['M4-2-u2-X21']::text[],false,'{"seq":21,"concept":"M4-2-u2-C2","difficulty":3,"kind":"ox","stem":"「궁금해요」 — 수직인 직선을 줄여서 수직선이라고 불러요.","answer":"X","reason_options":[{"t":"수직인 직선은 줄여서 수선이라고 약속해서","correct":true},{"t":"수직인 직선이니 수직선이라고 해서","mis":"M4-2-u2-X21"}],"mis":"M4-2-u2-X21","explanation":["수직선은 눈금과 수가 있는 선이에요.","수직인 직선은 수선이라고 해요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#22','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C10',3,'error','auto','「꼭 알아 둬요」 — 컴퍼스와 자로 마름모를 그리는 방법을 말했어요. 잘못 말한 사람은 누구인가요?',ARRAY['M4-2-u2-X19','M4-2-u2-X18']::text[],false,'{"seq":22,"concept":"M4-2-u2-C10","difficulty":3,"kind":"error","stem":"「꼭 알아 둬요」 — 컴퍼스와 자로 마름모를 그리는 방법을 말했어요. 잘못 말한 사람은 누구인가요?","options":[{"t":"건우 — 「두 번째 원은 컴퍼스를 더 벌려 그려도 마름모가 돼.」","correct":true,"mis_target":"M4-2-u2-X19"},{"t":"은비 — 「컴퍼스를 벌린 정도를 그대로 두고 두 원을 그려.」","mis":"M4-2-u2-X18"},{"t":"지아 — 「네 변이 모두 반지름이라 길이가 같아.」","mis":"M4-2-u2-X18"}],"explanation":["컴퍼스를 벌린 정도가 반지름이에요.","더 벌리면 반지름이 달라져요.","건우의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#23','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',4,'essay','teacher','「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었을 때 선분 ㄷㅁ의 길이를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u2-C7","difficulty":4,"kind":"essay","stem":"「수학에 퐁당」 — 사다리꼴 ㄱㄴㄷㄹ에서 변 ㄱㄴ과 평행한 선분 ㄹㅁ을 그었을 때 선분 ㄷㅁ의 길이를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 선분 ㄱㄴ과 선분 ㄹㅁ, 선분 ㄱㄹ과 선분 ㄴㅁ이 각각 평행하므로 사각형 ㄱㄴㅁㄹ은 평행사변형입니다. 마주 보는 두 변의 길이가 같으므로 선분 ㄴㅁ은 5 cm이고, 선분 ㄷㅁ은 12 − 5 = 7(cm)입니다.","scoring_points":["사각형 ㄱㄴㅁㄹ이 평행사변형이라고 밝혔는가","선분 ㄴㅁ이 5 cm라고 썼는가","12 − 5 = 7(cm)을 구했는가"]},"explanation":["먼저 평행사변형을 찾아요.","마주 보는 두 변의 길이가 같아요.","12 − 5 = 7(cm)이에요."],"asset":{"type":"geo","items":[{"w":135,"h":111.0,"pts":{"ㄱ":[37.5,15.0,"nw"],"ㄴ":[12.0,78.0,"sw"],"ㄷ":[120.0,78.0,"se"],"ㄹ":[82.5,15.0,"ne"],"ㅁ":[57.0,78.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"lab":[[[60.0,6.8],"5 cm"],[[9.0,45.0],"8 cm"],[[75.0,105.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#24','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C7',4,'sa','auto','「수학익힘」 — 두 변이 4 cm, 9 cm인 평행사변형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u2-C7","difficulty":4,"kind":"sa","stem":"「수학익힘」 — 두 변이 4 cm, 9 cm인 평행사변형의 네 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["마주 보는 두 변의 길이가 같아요.","4 + 9 + 4 + 9예요.","26 cm예요."],"asset":{"type":"geo","items":[{"w":108.5,"h":95.2,"poly":[[[39.5,18.0],[90.5,18.0],[69.0,77.2],[18.0,77.2]]],"lab":[[[65.0,6.8],"4 cm"],[[97.8,54.1],"9 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u2_review_d#25','math',4,2,'u2','','tb_g4_2_math_u2_review_d','unit_review','M4-2-u2-C8',4,'essay','teacher','「개념 톡」 — 마름모 모양 종이를 마주 보는 꼭짓점끼리 만나도록 두 번 접었다 폈어요. 접힌 두 선분에서 알 수 있는 마름모의 성질을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u2-C8","difficulty":4,"kind":"essay","stem":"「개념 톡」 — 마름모 모양 종이를 마주 보는 꼭짓점끼리 만나도록 두 번 접었다 폈어요. 접힌 두 선분에서 알 수 있는 마름모의 성질을 써 보세요.","answer_guide":{"answer":"예: 접힌 두 선분은 마주 보는 꼭짓점끼리 이은 선분입니다. 두 선분이 만나는 곳에 삼각자를 대면 직각이므로 서로 수직으로 만나고, 접혀서 겹치므로 서로를 반으로 나눕니다.","scoring_points":["두 선분이 수직으로 만난다고 썼는가","두 선분이 서로를 반으로 나눈다고 썼는가","삼각자 등으로 확인하는 방법을 썼는가"]},"explanation":["마주 보는 꼭짓점끼리 만나도록 접어요.","두 선분은 수직으로 만나요.","서로를 반으로 나눠요."],"asset":{"type":"geo","items":[{"w":144.0,"h":108.0,"poly":[[[72.0,18.0],[126.0,54.0],[72.0,90.0],[18.0,54.0]]],"seg":[[[72.0,18.0],[72.0,90.0]],[[126.0,54.0],[18.0,54.0]]],"lab":[[[84.7,36.0],"4 cm"],[[45.0,45.0],"6 cm"],[[59.2,72.0],"?"],[[99.0,65.2],"?"]],"right":[[[72.0,18.0],[72.0,54.0],[126.0,54.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
